export const vocab = [  {id: "aag", word: { baseRomanUrdu: "aag", baseUrdu: "آگ", english: "fire", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/aag.webp", riddles: { english: "Hot and bright, it dances high,\nKeep your hands away nearby!", romanUrdu: "Garam roshni naach dikhaye,\nHaath lagao to jalan ho jaye!", urdu: "گرم روشنی ناچ دکھائے،\nہاتھ لگاؤ تو جلن ہو جائے!", }, },{id: "aagai", word: { baseRomanUrdu: "aagai", baseUrdu: "آگے", english: "forward", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/aagai.webp", riddles: { english: "Step this way and do not stay,\nIt helps you move along your way.", romanUrdu: "Is taraf qadam barhao,\nRukna nahi, chaltay jao.", urdu: "اس طرف قدم بڑھاؤ،\nرکنا نہیں، چلتے جاؤ۔", }, },{id: "aaina", word: { baseRomanUrdu: "aaina", baseUrdu: "آئینہ", english: "mirror", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "aainay", urdu: "آئینے", english: "mirrors / mirror oblique", gender: "masculine", number: "plural", form: "plural / oblique", }, { romanUrdu: "aainon", urdu: "آئینوں", english: "mirrors / of mirrors", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/aaina.webp", riddles: { english: "Look at me and you will see, A face looking back at thee.", romanUrdu: "Mujh mein dekho apna chehra, Samne aaye roop tumhara.", urdu: "مجھ میں دیکھو اپنا چہرہ، سامنے آئے روپ تمہارا۔", }, },{id: "aakhri", word: { baseRomanUrdu: "aakhri", baseUrdu: "آخری", english: "last", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/aakhri.webp", riddles: { english: "After all the others are done,\nThis one comes after everyone.", romanUrdu: "Sab ke baad jo aaye,\nSilsila woh khatam kar jaye.", urdu: "سب کے بعد جو آئے،\nسلسلہ وہ ختم کر جائے۔", }, },{id: "aaloo", word: { baseRomanUrdu: "aaloo", baseUrdu: "آلو", english: "potato", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "aaloo", urdu: "آلو", english: "potatoes", gender: "masculine", number: "plural", form: "plural", }, ], image: "/qr/assets/images/aaloo.webp", riddles: { english: "I grow under the ground, round and plain,\nFry me or cook me, I fill your plate again!", romanUrdu: "Zameen ke neeche chhupa rehta hoon,\nPak jaoon to har plate mein aata hoon!", urdu: "زمین کے نیچے چھپا رہتا ہوں،\nپک جاؤں تو ہر پلیٹ میں آتا ہوں!", }, },{id: "aam", word: { baseRomanUrdu: "aam", baseUrdu: "آم", english: "mango", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/aam.webp", riddles: { english: "Golden fruit in summer heat,\nSoft and juicy, very sweet.", romanUrdu: "Garmi ka phal sab ko bhaye,\nRas bhara maza dil ko aaye.", urdu: "گرمی کا پھل سب کو بھائے،\nرس بھرا مزہ دل کو آئے۔", }, },{id: "aana", word: { baseRomanUrdu: "aana", baseUrdu: "آنا", english: "come", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "aaya", urdu: "آیا", english: "came", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "aayi", urdu: "آئی", english: "came", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "aaye", urdu: "آئے", english: "came", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "aa gaya", urdu: "آ گیا", english: "arrived", gender: "masculine", number: "singular", form: "past compound", }, { romanUrdu: "aa gayi", urdu: "آ گئی", english: "arrived", gender: "feminine", number: "singular", form: "past compound", }, { romanUrdu: "aa gaye", urdu: "آ گئے", english: "arrived", gender: "masculine", number: "plural", form: "past compound", }, { romanUrdu: "aao", urdu: "آؤ", english: "come here", gender: null, number: null, form: "command", }, { romanUrdu: "aayin", urdu: "آئیں", english: "came", gender: "feminine", number: "plural", form: "past respectful", }, { romanUrdu: "aati", urdu: "آتی", english: "coming", gender: "feminine", number: "singular", form: "habitual", }, { romanUrdu: "aatay", urdu: "آتے", english: "coming", gender: "masculine", number: "plural", form: "habitual", }], image: "/qr/assets/images/aana.webp", riddles: { english: "Someone is far, then near your side,\nThey reach the place where you reside.", romanUrdu: "Door se koi paas pohanchay,\nTumhari taraf qadam woh rakhay.", urdu: "دور سے کوئی پاس پہنچے،\nتمہاری طرف قدم وہ رکھے۔", }, },{id: "aankh", word: { baseRomanUrdu: "aankh", baseUrdu: "آنکھ", english: "eye", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "aankhen", urdu: "آنکھیں", english: "eyes", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "aankhon", urdu: "آنکھوں", english: "eyes", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/aankh.webp", riddles: { english: "With this you look and see,\nColors, faces, and a tree.", romanUrdu: "Is se rang aur chehray dikhen,\nKitab, darakht, sab nazar aayen.", urdu: "اس سے رنگ اور چہرے دکھیں،\nکتاب، درخت، سب نظر آئیں۔", }, },{id: "aansoo", word: { baseRomanUrdu: "aansoo", baseUrdu: "آنسو", english: "tears", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/aansoo.webp", riddles: { english: "Tiny drops from feelings deep,\nThey may fall when you laugh or weep.", romanUrdu: "Ehsaas ki chhoti boonden,\nHansi ya gham mein gir paren.", urdu: "احساس کی چھوٹی بوندیں،\nہنسی یا غم میں گر پڑیں۔", }, },{id: "aapas", word: { baseRomanUrdu: "aapas", baseUrdu: "آپس", english: "mutual", pos: "phrase", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/aapas.webp", riddles: { english: "Two sides connect, both are there,\nIt shows a bond people share.", romanUrdu: "Do taraf se rishta ban jaye,\nMil kar baat samajh mein aaye.", urdu: "دو طرف سے رشتہ بن جائے،\nمل کر بات سمجھ میں آئے۔", }, },{id: "aasmaan", word: { baseRomanUrdu: "aasmaan", baseUrdu: "آسمان", english: "sky", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/aasmaan.webp", riddles: { english: "A wide blue roof above us all,\nWhere birds and clouds can rise and fall.", romanUrdu: "Upar neeli chhat si chhayi,\nParinday aur badal wahin dikhayi.", urdu: "اوپر نیلی چھت سی چھائی،\nپرندے اور بادل وہیں دکھائی۔", }, },{id: "acha", word: { baseRomanUrdu: "acha", baseUrdu: "اچھا", english: "good", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "achi", urdu: "اچھی", english: "good", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "achay", urdu: "اچھے", english: "good plural", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/acha.webp", riddles: { english: "Kind and nice, just right to do,\nA happy word for me and you.", romanUrdu: "Naram, pyara, theek sa kaam,\nSun kar dil ko milay aaram.", urdu: "نرم، پیارا، ٹھیک سا کام،\nسن کر دل کو ملے آرام۔", }, },{id: "achanak", word: { baseRomanUrdu: "achanak", baseUrdu: "اچانک", english: "suddenly", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/achanak.webp", riddles: { english: "No warning, no slow start,\nIt happens fast and makes you start.", romanUrdu: "Na pehle khabar, na koi ishara,\nFauran ho jaye kaam sara.", urdu: "نہ پہلے خبر، نہ کوئی اشارہ،\nفوراً ہو جائے کام سارا۔", }, },{id: "ahista", word: { baseRomanUrdu: "ahista", baseUrdu: "آہستہ", english: "slowly", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/ahista.webp", riddles: { english: "Soft small steps, no rush today,\nMove with care along the way.", romanUrdu: "Narm qadam, jaldi nahi,\nAram se chalo, ghabrahat nahi.", urdu: "نرم قدم، جلدی نہیں،\nآرام سے چلو، گھبراہٹ نہیں۔", }, },{id: "aik", word: { baseRomanUrdu: "aik", baseUrdu: "ایک", english: "one", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/aik.webp", riddles: { english: "Not two, not many in a row,\nJust a single thing to show.", romanUrdu: "Do nahi, zyada bhi nahi,\nBas tanha si gintee yahi.", urdu: "دو نہیں، زیادہ بھی نہیں،\nبس تنہا سی گنتی یہی۔", }, },{id: "ailan", word: { baseRomanUrdu: "ailan", baseUrdu: "اعلان", english: "announcement", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "ailanaat", urdu: "اعلانات", english: "announcements", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/ailan.webp", riddles: { english: "When news is shared for all to hear,\nEveryone listens, loud and clear.", romanUrdu: "Jab khabar sab ko sunayi jaye,\nHar koi dhyan se sunta jaye.", urdu: "جب خبر سب کو سنائی جائے،\nہر کوئی دھیان سے سنتا جائے۔", }, },{id: "ajeeb", word: { baseRomanUrdu: "ajeeb", baseUrdu: "عجیب", english: "strange", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/ajeeb.webp", riddles: { english: "Not normal, quite a surprise,\nIt makes you open wide your eyes.", romanUrdu: "Aam sa bilkul nahi lagta,\nDekh kar hairat mein dalta.", urdu: "عام سا بالکل نہیں لگتا،\nدیکھ کر حیرت میں ڈالتا۔", }, },{id: "ajnabi", word: { baseRomanUrdu: "ajnabi", baseUrdu: "اجنبی", english: "stranger", pos: "noun", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/ajnabi.webp", riddles: { english: "A person you do not yet know,\nMaybe a friend as days will go.", romanUrdu: "Jis se abhi pehchan nahi,\nKal shayad dosti ho jaye kahin.", urdu: "جس سے ابھی پہچان نہیں،\nکل شاید دوستی ہو جائے کہیں۔", }, },{id: "akela", word: { baseRomanUrdu: "akela", baseUrdu: "اکیلا", english: "alone", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "akeli", urdu: "اکیلی", english: "alone", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "akelay", urdu: "اکیلے", english: "alone plural", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/akela.webp", riddles: { english: "No crowd, no team, just one is there,\nQuiet steps and empty air.", romanUrdu: "Na jhund, na saathi paas,\nBas khamoshi aur apni saans.", urdu: "نہ جھنڈ، نہ ساتھی پاس،\nبس خاموشی اور اپنی سانس۔", }, },{id: "alag", word: { baseRomanUrdu: "alag", baseUrdu: "الگ", english: "different / separate", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/alag.webp", riddles: { english: "Not the same as all the rest,\nIt stands apart from every guest.", romanUrdu: "Sab jaisa yeh hota nahi,\nApni pehchan rakhta yahi.", urdu: "سب جیسا یہ ہوتا نہیں،\nاپنی پہچان رکھتا یہی۔", }, },{id: "ami", word: { baseRomanUrdu: "ami", baseUrdu: "امی", english: "mother", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/ami.webp", riddles: { english: "She hugs you close and knows your heart,\nHer love is there from the very start.", romanUrdu: "Jo pyar se gale lagaye,\nDil ki baat foran samajh jaye.", urdu: "جو پیار سے گلے لگائے،\nدل کی بات فوراً سمجھ جائے۔", }, },{id: "andar", word: { baseRomanUrdu: "andar", baseUrdu: "اندر", english: "inside", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/andar.webp", riddles: { english: "Not out in the open air,\nThis means within a place somewhere.", romanUrdu: "Bahar nahi, kisi jagah ke beech,\nYahin chhupi hoti hai cheez.", urdu: "باہر نہیں، کسی جگہ کے بیچ،\nیہیں چھپی ہوتی ہے چیز۔", }, },{id: "andhera", word: { baseRomanUrdu: "andhera", baseUrdu: "اندھیرا", english: "darkness", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "andheri", urdu: "اندھیری", english: "dark", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "andheray", urdu: "اندھیرے", english: "darkness / dark plural", gender: "masculine", number: "plural", form: "plural / oblique", }], image: "/qr/assets/images/andhera.webp", riddles: { english: "When light is gone, I fill the space, You may need a lamp to see a face.", romanUrdu: "Roshni jaye to main aaun, Cheezon ko chup sa kar jaun.", urdu: "روشنی جائے تو میں آؤں، چیزوں کو چپ سا کر جاؤں۔", }, },{id: "awaaz", word: { baseRomanUrdu: "awaaz", baseUrdu: "آواز", english: "sound", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "awaazen", urdu: "آوازیں", english: "sounds", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "awaazon", urdu: "آوازوں", english: "sounds", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/awaaz.webp", riddles: { english: "You cannot hold it in your hand,\nBut ears can hear it where you stand.", romanUrdu: "Haath se isay pakar na pao,\nKaanon se is ko sunte jao.", urdu: "ہاتھ سے اسے پکڑ نہ پاؤ،\nکانوں سے اس کو سنتے جاؤ۔", }, },{id: "azan", word: { baseRomanUrdu: "azan", baseUrdu: "اذان", english: "call", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "azanen", urdu: "اذانیں", english: "calls", gender: "feminine", number: "plural", form: "plural", }, ], image: "/qr/assets/images/azan.webp", riddles: { english: "A beautiful message fills the air,\nIt reminds hearts to turn to prayer.", romanUrdu: "Piyara paigham hawa mein aaye,\nDilon ko ibadat yaad dilaye.", urdu: "پیارا پیغام ہوا میں آئے،\nدلوں کو عبادت یاد دلائے۔", }, },{id: "baad", word: { baseRomanUrdu: "baad", baseUrdu: "بعد", english: "after", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/baad.webp", riddles: { english: "First one thing, then this is next,\nIt follows later in the text.", romanUrdu: "Pehle kuch ho, phir yeh aaye,\nWaqt ka silsila aagay barhaye.", urdu: "پہلے کچھ ہو، پھر یہ آئے،\nوقت کا سلسلہ آگے بڑھائے۔", }, },{id: "baantna", word: { baseRomanUrdu: "baantna", baseUrdu: "بانٹنا", english: "share/distribute", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "baanta", urdu: "بانٹا", english: "shared", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "baanti", urdu: "بانٹی", english: "shared", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "baantay", urdu: "بانٹے", english: "shared", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/baantna.webp", riddles: { english: "One thing becomes portions for all,\nKindness grows from big to small.", romanUrdu: "Ek cheez sab mein taqseem ho jaye,\nDil mein darya dili aa jaye.", urdu: "ایک چیز سب میں تقسیم ہو جائے،\nدل میں دریا دلی آ جائے۔", }, },{id: "baarish", word: { baseRomanUrdu: "baarish", baseUrdu: "بارش", english: "rain", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "baarishen", urdu: "بارشیں", english: "rains", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "baarishon", urdu: "بارشوں", english: "rains", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/baarish.webp", riddles: { english: "Tiny drops fall from above,\nPlants and puddles both it love.", romanUrdu: "Upar se chhoti boonden aayen,\nPoday aur gadday khush ho jaayen.", urdu: "اوپر سے چھوٹی بوندیں آئیں،\nپودے اور گڑھے خوش ہو جائیں۔", }, },{id: "baat", word: { baseRomanUrdu: "baat", baseUrdu: "بات", english: "talk", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "baatein", urdu: "باتیں", english: "talks", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "baaton", urdu: "باتوں", english: "talks", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/baat.webp", riddles: { english: "Words go out and words come back,\nPeople share what thoughts they pack.", romanUrdu: "Lafz nikal kar wapas aayen,\nLog apne khayal sunayen.", urdu: "لفظ نکل کر واپس آئیں،\nلوگ اپنے خیال سنائیں۔", }, },{id: "baatcheet", word: { baseRomanUrdu: "baatcheet", baseUrdu: "بات چیت", english: "conversation", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/baatcheet.webp", riddles: { english: "You say something, I reply,\nWords keep moving, low and high.", romanUrdu: "Tum kuch kaho, main jawab doon,\nLafzon se rishta jor doon.", urdu: "تم کچھ کہو، میں جواب دوں،\nلفظوں سے رشتہ جوڑ دوں۔", }, },{id: "bacha", word: { baseRomanUrdu: "bacha", baseUrdu: "بچہ", english: "child", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "bachi", urdu: "بچی", english: "girl child", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "bachay", urdu: "بچے", english: "children", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "bachon", urdu: "بچوں", english: "children", gender: "masculine", number: "plural", form: "plural oblique", }, { romanUrdu: "bachiyan", urdu: "بچیاں", english: "girls", gender: "feminine", number: "plural", form: "plural", }], image: "/qr/assets/images/bacha.webp", riddles: { english: "Small and curious, ready to play,\nLearning new things every day.", romanUrdu: "Chhota sa dil, khelna pasand,\nRoz nayi cheez se hota buland.", urdu: "چھوٹا سا دل، کھیلنا پسند،\nروز نئی چیز سے ہوتا بلند۔", }, },{id: "bachpan", word: { baseRomanUrdu: "bachpan", baseUrdu: "بچپن", english: "childhood", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/bachpan.webp", riddles: { english: "The early days of games and fun,\nBefore the growing years have begun.", romanUrdu: "Khel kood ke pehle din,\nBari umar se pehle ka rangin waqt.", urdu: "کھیل کود کے پہلے دن،\nبڑی عمر سے پہلے کا رنگین وقت۔", }, },{id: "badal", word: { baseRomanUrdu: "badal", baseUrdu: "بادل", english: "cloud", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "badalon", urdu: "بادلوں", english: "clouds", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/badal.webp", riddles: { english: "Soft gray shapes that float up high,\nSometimes they cover the blue roof.", romanUrdu: "Naram dhundlay tukray upar jaayen,\nKabhi neeli chhat ko chhupa jaayen.", urdu: "نرم دھندلے ٹکڑے اوپر جائیں،\nکبھی نیلی چھت کو چھپا جائیں۔", }, },{id: "badalna", word: { baseRomanUrdu: "badalna", baseUrdu: "بدلنا", english: "change", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "badla", urdu: "بدلا", english: "changed", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "badli", urdu: "بدلی", english: "changed", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "badlay", urdu: "بدلے", english: "changed", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "badalni", urdu: "بدلنی", english: "to change", gender: "feminine", number: "singular", form: "infinitive", }], image: "/qr/assets/images/badalna.webp", riddles: { english: "When something becomes not quite the same,\nA new look, color, shape, or name.", romanUrdu: "Jab cheez pehli jaisi na rahe,\nNaya rang ya roop le le.", urdu: "جب چیز پہلی جیسی نہ رہے،\nنیا رنگ یا روپ لے لے۔", }, },{id: "badam", word: { baseRomanUrdu: "badam", baseUrdu: "بادام", english: "almond", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/badam.webp", riddles: { english: "A crunchy little nut to eat,\nIn kheer or milk it tastes so sweet.", romanUrdu: "Chhota mewa karara sa,\nDoodh ya kheer mein pyara sa.", urdu: "چھوٹا میوہ کرارا سا،\nدودھ یا کھیر میں پیارا سا۔", }, },{id: "baen", word: { baseRomanUrdu: "baen", baseUrdu: "بائیں", english: "left", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/baen.webp", riddles: { english: "One side of your body or road,\nOpposite where the other hand showed.", romanUrdu: "Jism ya raaste ki aik taraf,\nDoosri taraf ka ulta rukh.", urdu: "جسم یا راستے کی ایک طرف،\nدوسری طرف کا الٹا رخ۔", }, },{id: "bahar", word: { baseRomanUrdu: "bahar", baseUrdu: "باہر", english: "outside", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/bahar.webp", riddles: { english: "Not within the room or door,\nThis is beyond the inside floor.", romanUrdu: "Kamray ya dar ke beech nahi,\nDehleez se pare jagah yahi.", urdu: "کمرے یا در کے بیچ نہیں،\nدہلیز سے پرے جگہ یہی۔", }, },{id: "baigan", word: { baseRomanUrdu: "baigan", baseUrdu: "بینگن", english: "eggplant", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "baigan", urdu: "بینگن", english: "eggplants", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/baigan.webp", riddles: { english: "Purple outside, soft inside,\nIn curry or bharta, I do not hide!", romanUrdu: "Bahar se jamni, andar se naram,\nSalan mein aaun to lagun garam garam!", urdu: "باہر سے جامنی، اندر سے نرم،\nسالن میں آؤں تو لگوں گرم گرم!", }, },{id: "baithna", word: { baseRomanUrdu: "baithna", baseUrdu: "بیٹھنا", english: "sit", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "baitha", urdu: "بیٹھا", english: "sat", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "baithi", urdu: "بیٹھی", english: "sat", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "baithay", urdu: "بیٹھے", english: "sat", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "baith gayin", urdu: "بیٹھ گئیں", english: "sat down", gender: "feminine", number: "plural", form: "past compound", }, { romanUrdu: "baith raha", urdu: "بیٹھ رہا", english: "is sitting", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "baith rahi", urdu: "بیٹھ رہی", english: "is sitting", gender: "feminine", number: "singular", form: "continuous", }, { romanUrdu: "baith rahay", urdu: "بیٹھ رہے", english: "are sitting", gender: "masculine", number: "plural", form: "continuous", }, { romanUrdu: "baith gaye", urdu: "بیٹھ گئے", english: "sat down", gender: "masculine", number: "plural", form: "past compound", }, { romanUrdu: "baitho", urdu: "بیٹھو", english: "sit down", gender: null, number: null, form: "command", }, { romanUrdu: "baithega", urdu: "بیٹھے گا", english: "will sit", gender: "masculine", number: "singular", form: "future", }], image: "/qr/assets/images/baithna.webp", riddles: { english: "Bend your knees and take a rest,\nOn a chair or floor is best.", romanUrdu: "Ghutnay mor kar aram pao,\nKursi ya farsh par tik jao.", urdu: "گھٹنے موڑ کر آرام پاؤ،\nکرسی یا فرش پر ٹک جاؤ۔", }, },{id: "bakra", word: { baseRomanUrdu: "bakra", baseUrdu: "بکرا", english: "goat", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "bakri", urdu: "بکری", english: "female goat", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "bakray", urdu: "بکرے", english: "goats", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "bakron", urdu: "بکروں", english: "goat", gender: null, number: "plural", form: "plural oblique", }], image: "/qr/assets/images/bakra.webp", riddles: { english: "With small horns and a meh-meh sound,\nOn Eid this animal may be found.", romanUrdu: "Chotay se seeng aur meh meh awaaz,\nEid ke din iska hota andaaz.", urdu: "چھوٹے سے سینگ اور مے مے آواز،\nعید کے دن اس کا ہوتا انداز۔", }, },{id: "banana", word: { baseRomanUrdu: "banana", baseUrdu: "بنانا", english: "make", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "banaya", urdu: "بنایا", english: "made", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "banayi", urdu: "بنائی", english: "made", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "banaye", urdu: "بنائے", english: "made", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "banao", urdu: "بناؤ", english: "make", gender: null, number: null, form: "command", }], image: "/qr/assets/images/banana.webp", riddles: { english: "Use your hands and ideas too,\nSomething new is made by you.", romanUrdu: "Haath aur soch dono lagao,\nNayi cheez tayyar kar jao.", urdu: "ہاتھ اور سوچ دونوں لگاؤ،\nنئی چیز تیار کر جاؤ۔", }, },{id: "band", word: { baseRomanUrdu: "band", baseUrdu: "بند", english: "closed", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/band.webp", riddles: { english: "A door like this won't let you through,\nIt's shut until someone opens it for you.", romanUrdu: "Darwaza aisa ho to andar na jao,\nPehle koi khole, phir aao.", urdu: "دروازہ ایسا ہو تو اندر نہ جاؤ،\nپہلے کوئی کھولے، پھر آؤ۔", }, },{id: "banna", word: { baseRomanUrdu: "banna", baseUrdu: "بننا", english: "become/be made", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "bana", urdu: "بنا", english: "became/was made", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "bani", urdu: "بنی", english: "became/was made", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "bane", urdu: "بنے", english: "became/were made", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "banta", urdu: "بنتا", english: "becomes/is made", gender: "masculine", number: "singular", form: "present", }, { romanUrdu: "banti", urdu: "بنتی", english: "becomes/is made", gender: "feminine", number: "singular", form: "present", }], image: "/qr/assets/images/banna.webp", riddles: { english: "Something changes into a new way, like clay becoming art one day.", romanUrdu: "Cheez naya roop apnaye, mitti bhi khilona ban jaye.", urdu: "چیز نیا روپ اپنائے، مٹی بھی کھلونا بن جائے۔", }, },{id: "barabar", word: { baseRomanUrdu: "barabar", baseUrdu: "برابر", english: "equal/properly", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/barabar.webp", riddles: { english: "Both sides match and line up right, neat and even in your sight.", romanUrdu: "Dono taraf jab aik si ho, seedhi saaf aur sahi si ho.", urdu: "دونوں طرف جب ایک سی ہو، سیدھی صاف اور صحیح سی ہو۔", }, },{id: "barhana", word: { baseRomanUrdu: "barhana", baseUrdu: "بڑھانا", english: "increase", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "barhaya", urdu: "بڑھایا", english: "increased", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "barhayi", urdu: "بڑھائی", english: "increased", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "barhaye", urdu: "بڑھائے", english: "increased", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/barhana.webp", riddles: { english: "A little more, then more again,\nNumbers or size begin to gain.", romanUrdu: "Thora aur, phir us se zyada,\nCheez ho jaye aur bhi bara.", urdu: "تھوڑا اور، پھر اس سے زیادہ،\nچیز ہو جائے اور بھی بڑا۔", }, },{id: "barsaat", word: { baseRomanUrdu: "barsaat", baseUrdu: "برسات", english: "rainfall", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/barsaat.webp", riddles: { english: "A wet season, clouds all around,\nDrops keep tapping on the ground.", romanUrdu: "Geela mausam, badal chhaye,\nBoonden zameen par taal bajaye.", urdu: "گیلا موسم، بادل چھائے،\nبوندیں زمین پر تال بجائیں۔", }, },{id: "basta", word: { baseRomanUrdu: "basta", baseUrdu: "بستہ", english: "school bag", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "bastay", urdu: "بستے", english: "school bags", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/basta.webp", riddles: { english: "Books and pencils sit inside,\nOn school mornings it comes for the ride.", romanUrdu: "Kitabein aur pencils is mein jayein,\nSchool ke din saath nibhayein.", urdu: "کتابیں اور پینسلیں اس میں جائیں،\nاسکول کے دن ساتھ نبھائیں۔", }, },{id: "batana", word: { baseRomanUrdu: "batana", baseUrdu: "بتانا", english: "tell", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "bataya", urdu: "بتایا", english: "told", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "batayi", urdu: "بتائی", english: "told", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "bataye", urdu: "بتائے", english: "told", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/batana.webp", riddles: { english: "Share the news or explain a thing,\nWords from your mouth can meaning bring.", romanUrdu: "Khabar do ya samjhao baat,\nMunh ke lafz kholain raaz.", urdu: "خبر دو یا سمجھاؤ بات،\nمنہ کے لفظ کھولیں راز۔", }, },{id: "beech", word: { baseRomanUrdu: "beech", baseUrdu: "بیچ", english: "middle", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/beech.webp", riddles: { english: "Not the start and not the end,\nI'm where both sides meet, my friend.", romanUrdu: "Na shuru, na aakhir mein,\nMain hoon dono ke darmiyaan mein.", urdu: "نہ شروع، نہ آخر میں،\nمیں ہوں دونوں کے درمیان میں۔", }, },
{id: "beta", word: { baseRomanUrdu: "beta", baseUrdu: "بیٹا", english: "son", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "beti", urdu: "بیٹی", english: "daughter", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "betay", urdu: "بیٹے", english: "sons", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "beton", urdu: "بیٹوں", english: "sons", gender: "masculine", number: "plural", form: "plural oblique", }, { romanUrdu: "betiyon", urdu: "بیٹیوں", english: "daughters", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/beta.webp", riddles: { english: "A boy loved by his family dear,\nParents smile when he is near.", romanUrdu: "Ghar ka larka pyara sa,\nWalidain ka dulara sa.", urdu: "گھر کا لڑکا پیارا سا،\nوالدین کا دلارا سا۔", }, },{id: "bhaagna", word: { baseRomanUrdu: "bhaagna", baseUrdu: "بھاگنا", english: "run", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "bhaaga", urdu: "بھاگا", english: "ran", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "bhaagi", urdu: "بھاگی", english: "ran", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "bhaagay", urdu: "بھاگے", english: "ran", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "bhaagain", urdu: "بھاگیں", english: "run", gender: null, number: "plural", form: "command", }, { romanUrdu: "bhaagne", urdu: "بھاگنے", english: "to run", gender: null, number: null, form: "oblique infinitive", }], image: "/qr/assets/images/bhaagna.webp", riddles: { english: "Feet move quickly when you hurry,\nYou may do this in a race or worry.", romanUrdu: "Pair tez chalain jab jaldi ho,\nRace mein bhi yeh kaam hota ho.", urdu: "پاؤں تیزی سے چلیں جب جلدی ہو،\nدوڑ کے کھیل میں بھی یہی کام ہو۔", }, },{id: "bharna", word: { baseRomanUrdu: "bharna", baseUrdu: "بھرنا", english: "fill", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "bhara", urdu: "بھرا", english: "filled", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "bhari", urdu: "بھری", english: "filled", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "bharay", urdu: "بھرے", english: "filled", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "bhar gaya", urdu: "بھر گیا", english: "became full", gender: "masculine", number: "singular", form: "past compound", }], image: "/qr/assets/images/bharna.webp", riddles: { english: "An empty cup gets more and more,\nUntil it has no space to pour.", romanUrdu: "Khali bartan dheere dheere,\nItna ho jaye ke jagah na rahe.", urdu: "خالی برتن دھیرے دھیرے،\nاتنا ہو جائے کہ جگہ نہ رہے۔", }, },{id: "bheir", word: { baseRomanUrdu: "bheir", baseUrdu: "بھیڑ", english: "sheep", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "bheirein", urdu: "بھیڑیں", english: "sheep", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "bheiron", urdu: "بھیڑوں", english: "sheep", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/bheir.webp", riddles: { english: "Soft wool covers this farm friend,\nIt walks in groups around the bend.", romanUrdu: "Naram oon se badan dhaka ho,\nJhund ke saath chalna acha ho.", urdu: "نرم اون سے بدن ڈھکا ہو،\nجھنڈ کے ساتھ چلنا اچھا ہو۔", }, },{id: "bhoot", word: { baseRomanUrdu: "bhoot", baseUrdu: "بھوت", english: "ghost", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "bhooton", urdu: "بھوتوں", english: "of ghosts", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/bhoot.webp", riddles: { english: "In spooky stories I float in white,\nBut I'm only make-believe at night!", romanUrdu: "Kahaniyon mein safaid sa urta hoon,\nAsal mein to bas khayal hi hoon!", urdu: "کہانیوں میں سفید سا اڑتا ہوں،\nاصل میں تو بس خیال ہی ہوں!", }, },{id: "bijli", word: { baseRomanUrdu: "bijli", baseUrdu: "بجلی", english: "electricity", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/bijli.webp", riddles: { english: "I make lights and fans run bright, But I can vanish in the night.", romanUrdu: "Batti aur pankha chalaun, Kabhi achanak chali jaun.", urdu: "بتی اور پنکھا چلاؤں، کبھی اچانک چلی جاؤں۔", }, },{id: "bikharna", word: { baseRomanUrdu: "bikharna", baseUrdu: "بکھرنا", english: "scatter / be scattered", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "bikhra", urdu: "بکھرا", english: "scattered", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "bikhri", urdu: "بکھری", english: "scattered", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "bikhray", urdu: "بکھرے", english: "scattered", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/bikharna.webp", riddles: { english: "Things once neat, now everywhere,\nSpread around without a care.", romanUrdu: "Cheezein jagah se hat jayen,\nHar taraf phail jayen.", urdu: "چیزیں جگہ سے ہٹ جائیں،\nہر طرف پھیل جائیں۔", }, },{id: "bistar", word: { baseRomanUrdu: "bistar", baseUrdu: "بستر", english: "bed", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "bistaron", urdu: "بستروں", english: "beds", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/bistar.webp", riddles: { english: "Soft place waiting every night,\nFor dreams and sleep till morning light.", romanUrdu: "Raat ko narm jagah bulaye,\nNeend aur khwab le kar aaye.", urdu: "رات کو نرم جگہ بلائے،\nنیند اور خواب لے کر آئے۔", }, },{id: "bolna", word: { baseRomanUrdu: "bolna", baseUrdu: "بولنا", english: "speak", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "bola", urdu: "بولا", english: "spoke/said", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "boli", urdu: "بولی", english: "spoke/said", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "bole", urdu: "بولے", english: "spoke/said", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "bolo", urdu: "بولو", english: "speak/say", gender: null, number: null, form: "command", }, { romanUrdu: "bolte", urdu: "بولتے", english: "speaking", gender: "masculine", number: "plural", form: "habitual", }], image: "/qr/assets/images/bolna.webp", riddles: { english: "Words come out so others hear, soft or loud, far or near.", romanUrdu: "Lafz zuban se bahar aayen, dheere ya zor se sunai de jaayen.", urdu: "لفظ زبان سے باہر آئیں، دھیرے یا زور سے سنائی دے جائیں۔", }, },{id: "boond", word: { baseRomanUrdu: "boond", baseUrdu: "بوند", english: "raindrop", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "boonden", urdu: "بوندیں", english: "raindrops", gender: "feminine", number: "plural", form: "plural", }], image: "/qr/assets/images/boond.webp", riddles: { english: "A tiny drop from clouds can fall,\nSmall by itself, with many it is tall.", romanUrdu: "Badal se chhota qatra aaye,\nMil kar geeli raah banaye.", urdu: "بادل سے چھوٹا قطرہ آئے،\nمل کر گیلی راہ بنائے۔", }, },{id: "chaabi", word: { baseRomanUrdu: "chaabi", baseUrdu: "چابی", english: "key", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "chaabiyan", urdu: "چابیاں", english: "keys", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "chaabiyon", urdu: "چابیوں", english: "keys", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/chaabi.webp", riddles: { english: "A tiny metal helper in your hand,\nIt opens locks just as planned.", romanUrdu: "Chhoti dhatu ki madadgar cheez,\nTala kholay, karay asaan tareeq.", urdu: "چھوٹی دھات کی مددگار چیز،\nتالا کھولے، کرے آسان طریق۔", }, },{id: "chaand", word: { baseRomanUrdu: "chaand", baseUrdu: "چاند", english: "moon", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/chaand.webp", riddles: { english: "A silver face in the dark night,\nIt glows above with gentle light.", romanUrdu: "Raat mein chamakta chaandi sa chehra,\nUpar se de narm ujala gehra.", urdu: "رات میں چمکتا چاندی سا چہرہ،\nاوپر سے دے نرم اجالا گہرا۔", }, },{id: "chaar", word: { baseRomanUrdu: "chaar", baseUrdu: "چار", english: "four", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/chaar.webp", riddles: { english: "Count your fingers after three,\nThis number is what you will see.", romanUrdu: "Teen ke baad gintee mein aaye,\nHaath par is ko asani se paaye.", urdu: "تین کے بعد گنتی میں آئے،\nہاتھ پر اس کو آسانی سے پائے۔", }, },{id: "chacha", word: { baseRomanUrdu: "chacha", baseUrdu: "چاچا", english: "uncle", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "chachay", urdu: "چاچے", english: "uncles", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/chacha.webp", riddles: { english: "Your father’s brother, kind and fun,\nFamily love for everyone.", romanUrdu: "Abu ka bhai, pyara rishta,\nGhar mein laaye hansna basta.", urdu: "ابو کا بھائی، پیارا رشتہ،\nگھر میں لائے ہنسنا بستا۔", }, },{id: "chai", word: { baseRomanUrdu: "chai", baseUrdu: "چائے", english: "tea", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/chai.webp", riddles: { english: "Hot and brown in cups I flow,\nEvery gathering needs me so.", romanUrdu: "Garam pyali mein aati hoon,\nHar mehfil mein bhaati hoon.", urdu: "گرم پیالی میں آتی ہوں،\nہر محفل میں بھاتی ہوں۔", }, },{id: "chalna", word: { baseRomanUrdu: "chalna", baseUrdu: "چلنا", english: "move", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "chala", urdu: "چلا", english: "moved", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "chali", urdu: "چلی", english: "moved", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "chalay", urdu: "چلے", english: "moved", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "chalta", urdu: "چلتا", english: "moves", gender: "masculine", number: "singular", form: "present", }, { romanUrdu: "chalti", urdu: "چلتی", english: "moves", gender: "feminine", number: "singular", form: "present", }, { romanUrdu: "chal raha", urdu: "چل رہا", english: "is moving", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "chal rahi", urdu: "چل رہی", english: "is moving", gender: "feminine", number: "singular", form: "continuous", }, { romanUrdu: "chal rahay", urdu: "چل رہے", english: "are moving", gender: "masculine", number: "plural", form: "continuous", }], image: "/qr/assets/images/chalna.webp", riddles: { english: "Feet or wheels do this each day,\nFrom one place to another way.", romanUrdu: "Pair ya pahiye roz yeh karen,\nAik jagah se doosri taraf chal paren.", urdu: "پیر یا پہیے روز یہ کریں،\nایک جگہ سے دوسری طرف چل پڑیں۔", }, },{id: "chamakna", word: { baseRomanUrdu: "chamakna", baseUrdu: "چمکنا", english: "shine", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "chamka", urdu: "چمکا", english: "shone", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "chamki", urdu: "چمکی", english: "shone", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "chamkay", urdu: "چمکے", english: "shone", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "chamak", urdu: "چمک", english: "shine", gender: "feminine", number: "singular", form: "noun form", }, { romanUrdu: "chamkeela", urdu: "چمکیلا", english: "shiny", gender: "masculine", number: "singular", form: "adjective", }, { romanUrdu: "chamkeeli", urdu: "چمکیلی", english: "shiny", gender: "feminine", number: "singular", form: "adjective", }, { romanUrdu: "chamkeelay", urdu: "چمکیلے", english: "shiny", gender: "masculine", number: "plural", form: "adjective plural", }, { romanUrdu: "chamakti", urdu: "چمکتی", english: "shines", gender: "feminine", number: "singular", form: "present", }, { romanUrdu: "chamakne", urdu: "چمکنے", english: "to shine", gender: null, number: null, form: "oblique infinitive", }], image: "/qr/assets/images/chamakna.webp", riddles: { english: "Bright like stars or polished gold,\nLight jumps out for eyes to hold.", romanUrdu: "Sitaron ya sona jaisa ujala,\nAankhon ko lagay pyara pyara.", urdu: "ستاروں یا سونا جیسا اجالا،\nآنکھوں کو لگے پیارا پیارا۔", }, },{id: "chandi", word: { baseRomanUrdu: "chandi", baseUrdu: "چاندی", english: "silver", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/chandi.webp", riddles: { english: "White and shiny, not quite gold,\nIn rings and bangles I am sold.", romanUrdu: "Safaid chamak, sona nahi,\nChooriyon mein dhalti sahi.", urdu: "سفید چمک، سونا نہیں،\nچوڑیوں میں ڈھلتی صحیح۔", }, },{id: "chara", word: { baseRomanUrdu: "chara", baseUrdu: "چارہ", english: "animal feed", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/chara.webp", riddles: { english: "Green bites for animals to eat,\nFarm friends think it is a treat.", romanUrdu: "Janwar is se pait bharte hain,\nKhet ki cheez maze se khate hain.", urdu: "جانور اس سے پیٹ بھرتے ہیں،\nکھیت کی چیز مزے سے کھاتے ہیں۔", }, },{id: "charhna", word: { baseRomanUrdu: "charhna", baseUrdu: "چڑھنا", english: "climb", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "charha", urdu: "چڑھا", english: "climbed", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "charhi", urdu: "چڑھی", english: "climbed", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "charhe", urdu: "چڑھے", english: "climbed", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "charho", urdu: "چڑھو", english: "climb", gender: null, number: null, form: "command", }, { romanUrdu: "charhne", urdu: "چڑھنے", english: "to climb / climbing", gender: null, number: null, form: "oblique infinitive", }, { romanUrdu: "charh raha", urdu: "چڑھ رہا", english: "is climbing", gender: "masculine", number: "singular", form: "continuous", }], image: "/qr/assets/images/charhna.webp", riddles: { english: "Step by step you go up high,\nOn stairs or trees toward the sky.", romanUrdu: "Seerhi seerhi upar jao,\nDarakht pe bhi pohanch dikhao.", urdu: "سیڑھی سیڑھی اوپر جاؤ،\nدرخت پہ بھی پہنچ دکھاؤ۔", }, },{id: "charpai", word: { baseRomanUrdu: "charpai", baseUrdu: "چارپائی", english: "woven cot", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "charpaiyan", urdu: "چارپائیاں", english: "woven cots", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "charpaiyon", urdu: "چارپائیوں", english: "woven cots", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/charpai.webp", riddles: { english: "Four wooden legs and ropes woven tight,\nYou rest on me in the courtyard at night.", romanUrdu: "Chaar paaon aur bunay huay dhaagay,\nSehan mein so jao, phir subah jaagay.", urdu: "چار پاؤں اور بُنے ہوئے دھاگے،\nصحن میں سو جاؤ، پھر صبح جاگے۔", }, },{id: "cheekhna", word: { baseRomanUrdu: "cheekhna", baseUrdu: "چیخنا", english: "scream", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "cheekha", urdu: "چیخا", english: "screamed", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "cheekhi", urdu: "چیخی", english: "screamed", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "cheekhay", urdu: "چیخے", english: "screamed", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "cheekh", urdu: "چیخ", english: "scream", gender: "feminine", number: "singular", form: "noun form", }], image: "/qr/assets/images/cheekhna.webp", riddles: { english: "A very loud voice when feelings rise,\nIt may come out in fear or surprise.", romanUrdu: "Bohat buland boli nikal aaye,\nDarr ya hairani mein sunai jaye.", urdu: "بہت بلند بولی نکل آئے،\nڈر یا حیرانی میں سنائی جائے۔", }, },{id: "chehra", word: { baseRomanUrdu: "chehra", baseUrdu: "چہرہ", english: "face", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "chehray", urdu: "چہرے", english: "faces", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "chehron", urdu: "چہروں", english: "faces / of faces", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/chehra.webp", riddles: { english: "Eyes and smile are found on me, I show how you feel clearly.", romanUrdu: "Aankh aur muskan mujh par aaye, Dil ka haal nazar dikhaye.", urdu: "آنکھ اور مسکان مجھ پر آئے، دل کا حال نظر دکھائے۔", }, },{id: "chhat", word: { baseRomanUrdu: "chhat", baseUrdu: "چھت", english: "rooftop", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "chhaton", urdu: "چھتوں", english: "rooftops", gender: "feminine", number: "plural", form: "plural oblique", }, { romanUrdu: "chhatein", urdu: "چھتیں", english: "rooftops", gender: "feminine", number: "plural", form: "plural", }], image: "/qr/assets/images/chhat.webp", riddles: { english: "The top of a home where breezes meet,\nSometimes kites fly above your feet.", romanUrdu: "Ghar ka upar wala hissa,\nJahan patang aur hawa ka qissa.", urdu: "گھر کا اوپر والا حصہ،\nجہاں پتنگ اور ہوا کا قصہ۔", }, },{id: "chhota", word: { baseRomanUrdu: "chhota", baseUrdu: "چھوٹا", english: "small", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "chhoti", urdu: "چھوٹی", english: "small", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "chhotay", urdu: "چھوٹے", english: "small", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/chhota.webp", riddles: { english: "Not big at all, it fits your hand,\nThe littlest thing in all the land.", romanUrdu: "Bara nahi yeh nanha sa,\nHaath mein aa jaye poora sa.", urdu: "بڑا نہیں یہ ننھا سا،\nہاتھ میں آ جائے پورا سا۔", }, },{id: "chhupna", word: { baseRomanUrdu: "chhupna", baseUrdu: "چھپنا", english: "hide", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "chhupa", urdu: "چھپا", english: "hid", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "chhupi", urdu: "چھپی", english: "hid", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "chhup gaye", urdu: "چھپ گئے", english: "hid", gender: "masculine", number: "plural", form: "compound past", }, { romanUrdu: "chhupo", urdu: "چھپو", english: "hide", gender: null, number: null, form: "command", }], image: "/qr/assets/images/chhupna.webp", riddles: { english: "Behind a curtain, under a bed,\nNo one can find you, it is said.", romanUrdu: "Parde ke peeche, palang ke neeche,\nKoi na dhoonde, koi na kheenche.", urdu: "پردے کے پیچھے، پلنگ کے نیچے،\nکوئی نہ ڈھونڈے، کوئی نہ کھینچے۔", }, },{id: "chhutti", word: { baseRomanUrdu: "chhutti", baseUrdu: "چھٹی", english: "holiday / day off", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "chhuttiyan", urdu: "چھٹیاں", english: "holidays", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "chhuttiyon", urdu: "چھٹیوں", english: "holidays", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/chhutti.webp", riddles: { english: "No lessons and no work today,\nJust rest and fun and time to play.", romanUrdu: "Na parhai na koi kaam,\nAaj sirf aaram hi aaram.", urdu: "نہ پڑھائی نہ کوئی کام،\nآج صرف آرام ہی آرام۔", }, },{id: "chikna", word: { baseRomanUrdu: "chikna", baseUrdu: "چکنا", english: "smooth", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "chikni", urdu: "چکنی", english: "smooth", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "chikne", urdu: "چکنے", english: "smooth", gender: "masculine", number: "plural", form: "plural / oblique form", }], image: "/qr/assets/images/chikna.webp", riddles: { english: "Like glass, with not a bump in sight,\nYour hand slides over it just right.", romanUrdu: "Sheeshay jaisa, koi ubhaar nahi,\nHaath phisle, koi rukawat nahi.", urdu: "شیشے جیسا، کوئی ابھار نہیں،\nہاتھ پھسلے، کوئی رکاوٹ نہیں۔", }, },
{id: "chipakna", word: { baseRomanUrdu: "chipakna", baseUrdu: "چپکنا", english: "stick", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "chipka", urdu: "چپکا", english: "stuck", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "chipki", urdu: "چپکی", english: "stuck", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "chipke", urdu: "چپکے", english: "stuck", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "chipak gaya", urdu: "چپک گیا", english: "got stuck", gender: "masculine", number: "singular", form: "past compound", }, { romanUrdu: "chipak gayi", urdu: "چپک گئی", english: "got stuck", gender: "feminine", number: "singular", form: "past compound", }], image: "/qr/assets/images/chipakna.webp", riddles: { english: "Two things hold close and stay, even when you pull away.", romanUrdu: "Do cheezen saath lag jaayen, kheenchne par bhi na chhoot paayen.", urdu: "دو چیزیں ساتھ لگ جائیں، کھینچنے پر بھی نہ چھوٹ پائیں۔", }, },{id: "choori", word: { baseRomanUrdu: "choori", baseUrdu: "چوڑی", english: "bangle", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "chooriyan", urdu: "چوڑیاں", english: "bangles", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "chooriyon", urdu: "چوڑیوں", english: "bangles / of bangles", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/choori.webp", riddles: { english: "Round and bright around the hand, It can make a tiny sound.", romanUrdu: "Haath ke gird sajaun main, Chan chan kar ke sunaun main.", urdu: "ہاتھ کے گرد سجاؤں میں، چھن چھن کر کے سناؤں میں۔", }, },{id: "chup", word: { baseRomanUrdu: "chup", baseUrdu: "چپ", english: "quiet", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/chup.webp", riddles: { english: "No loud sound, no noisy cheer, Peaceful moments settle here.", romanUrdu: "Shor na ho, awaaz thami, Sukoon ki ho pyari ghari.", urdu: "شور نہ ہو، آواز تھمی، سکون کی ہو پیاری گھڑی۔", }, },{id: "dabba", word: { baseRomanUrdu: "dabba", baseUrdu: "ڈبہ", english: "box", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "dabbay", urdu: "ڈبے", english: "boxes", gender: "masculine", number: "plural", form: "plural / oblique", }, { romanUrdu: "dabbon", urdu: "ڈبوں", english: "boxes", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/dabba.webp", riddles: { english: "Open my lid and look inside,\nTreats or treasures I can hide.", romanUrdu: "Dhakkan kholo, jhaank ke dekho,\nAndar kuch bhi rakh ke dekho.", urdu: "ڈھکن کھولو، جھانک کے دیکھو،\nاندر کچھ بھی رکھ کے دیکھو۔", }, },{id: "dada", word: { baseRomanUrdu: "dada", baseUrdu: "دادا", english: "grandfather", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "daday", urdu: "دادے", english: "grandfathers", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/dada.webp", riddles: { english: "Your father’s father, wise and dear,\nOld stories are lovely to hear.", romanUrdu: "Abu ke abu, pyaray buzurg,\nUnki kahaniyan hoti hain pur-lutf.", urdu: "ابو کے ابو، پیارے بزرگ،\nان کی کہانیاں ہوتی ہیں پر لطف۔", }, },{id: "dadi", word: { baseRomanUrdu: "dadi", baseUrdu: "دادی", english: "grandmother", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "dadiyan", urdu: "دادیاں", english: "grandmothers", gender: "feminine", number: "plural", form: "plural", }], image: "/qr/assets/images/dadi.webp", riddles: { english: "Your father’s mother, soft and sweet,\nHer stories make the day complete.", romanUrdu: "Abu ki ami, meethi si jaan,\nKahani sunayen shaam ya subah.", urdu: "ابو کی امی، میٹھی سی جان،\nکہانی سنائیں شام یا صبح۔", }, },{id: "daen", word: { baseRomanUrdu: "daen", baseUrdu: "دائیں", english: "right", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/daen.webp", riddles: { english: "One side of your body or street,\nOpposite the other side you meet.", romanUrdu: "Jism ya gali ki aik taraf,\nDoosri simt ka ulta rukh.", urdu: "جسم یا گلی کی ایک طرف،\nدوسری سمت کا الٹا رخ۔", }, },{id: "dafa", word: { baseRomanUrdu: "dafa", baseUrdu: "دفعہ", english: "time/occasion", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "dafay", urdu: "دفعے", english: "time/occasions", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/dafa.webp", riddles: { english: "One moment, one turn, one try,\nIt counts an occasion passing by.", romanUrdu: "Ek mauqa, ek baari aaye,\nGinti mein yeh kaam bataye.", urdu: "ایک موقع، ایک باری آئے،\nگنتی میں یہ کام بتائے۔", }, },{id: "darna", word: { baseRomanUrdu: "darna", baseUrdu: "ڈرنا", english: "fear", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "dara", urdu: "ڈرا", english: "got scared", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "dari", urdu: "ڈری", english: "got scared", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "dare", urdu: "ڈرے", english: "got scared", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "daro", urdu: "ڈرو", english: "be scared", gender: null, number: null, form: "command", }], image: "/qr/assets/images/darna.webp", riddles: { english: "When the dark feels loud and near,\nYour heart beats fast because of this feeling here.", romanUrdu: "Jab andhera qareeb sa lage,\nDil tez dhadke, yeh ehsaas jage.", urdu: "جب اندھیرا قریب سا لگے،\nدل تیز دھڑکے، یہ احساس جاگے۔", }, },{id: "darwaza", word: { baseRomanUrdu: "darwaza", baseUrdu: "دروازہ", english: "door", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "darwaze", urdu: "دروازے", english: "doors / door (oblique)", gender: "masculine", number: "plural", form: "plural / oblique", }, { romanUrdu: "darwazon", urdu: "دروازوں", english: "of doors", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/darwaza.webp", riddles: { english: "Knock on me before you come in,\nOpen me wide to let friends in.", romanUrdu: "Andar aana ho to mujhe khatkhatao,\nKhol kar mujhe mehmaan bulao.", urdu: "اندر آنا ہو تو مجھے کھٹکھٹاؤ،\nکھول کر مجھے مہمان بلاؤ۔", }, },{id: "dastarkhan", word: { baseRomanUrdu: "dastarkhan", baseUrdu: "دسترخوان", english: "tablecloth", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/dastarkhan.webp", riddles: { english: "Spread it out before you eat,\nIt makes the meal look clean and neat.", romanUrdu: "Khanay se pehle isay bichhao,\nSuthra sa mahaul banao.", urdu: "کھانے سے پہلے اسے بچھاؤ،\nستھرا سا ماحول بناؤ۔", }, },{id: "daurna", word: { baseRomanUrdu: "daurna", baseUrdu: "دوڑنا", english: "run", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "daura", urdu: "دوڑا", english: "ran", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "dauri", urdu: "دوڑی", english: "ran", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "dauray", urdu: "دوڑے", english: "ran", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/daurna.webp", riddles: { english: "Fast feet hurry across the ground,\nBreath gets quick with every bound.", romanUrdu: "Tez qadam zameen par jaayen,\nSaans bhi foran tez ho jaayen.", urdu: "تیز قدم زمین پر جائیں،\nسانس بھی فوراً تیز ہو جائے۔", }, },{id: "deewar", word: { baseRomanUrdu: "deewar", baseUrdu: "دیوار", english: "wall", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "deewarein", urdu: "دیواریں", english: "walls", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "deewaron", urdu: "دیواروں", english: "of walls", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/deewar.webp", riddles: { english: "I stand around every room,\nHolding the roof up like a broom.", romanUrdu: "Har kamray ke chaaron taraf khari,\nChhat ko uthaye rakhti hoon bari.", urdu: "ہر کمرے کے چاروں طرف کھڑی،\nچھت کو اٹھائے رکھتی ہوں بڑی۔", }, },{id: "dekhna", word: { baseRomanUrdu: "dekhna", baseUrdu: "دیکھنا", english: "see", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "dekha", urdu: "دیکھا", english: "saw", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "dekhi", urdu: "دیکھی", english: "saw", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "dekhay", urdu: "دیکھے", english: "saw", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "dekho", urdu: "دیکھو", english: "look", gender: null, number: null, form: "command", }, { romanUrdu: "dekh raha", urdu: "دیکھ رہا", english: "is seeing", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "dekh rahi", urdu: "دیکھ رہی", english: "is seeing", gender: "feminine", number: "singular", form: "continuous", }, { romanUrdu: "dekhti", urdu: "دیکھتی", english: "seeing", gender: "feminine", number: "singular", form: "habitual", }], image: "/qr/assets/images/dekhna.webp", riddles: { english: "Use your eyes to know what is near,\nColors and shapes become clear.", romanUrdu: "Apni nazar se pehchan pao,\nRang aur shaklen samajh jao.", urdu: "اپنی نظر سے پہچان پاؤ،\nرنگ اور شکلیں سمجھ جاؤ۔", }, },{id: "dena", word: { baseRomanUrdu: "dena", baseUrdu: "دینا", english: "give", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "diya", urdu: "دیا", english: "gave", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "di", urdu: "دی", english: "gave", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "diye", urdu: "دیے", english: "gave", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/dena.webp", riddles: { english: "Something goes from me to you,\nA kind action people do.", romanUrdu: "Mere paas se tum tak aaye,\nNeki ka kaam dil ko bhaaye.", urdu: "میرے پاس سے تم تک آئے،\nنیکی کا کام دل کو بھائے۔", }, },{id: "der", word: { baseRomanUrdu: "der", baseUrdu: "دیر", english: "late", pos: "adverb", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/der.webp", riddles: { english: "The time has passed, you did not arrive,\nEveryone waited for you to drive.", romanUrdu: "Waqt guzar gaya, tum na aaye,\nSab intezar mein baithay rahay.", urdu: "وقت گزر گیا، تم نہ آئے،\nسب انتظار میں بیٹھے رہے۔", }, },{id: "dhadakna", word: { baseRomanUrdu: "dhadakna", baseUrdu: "دھڑکنا", english: "beat", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "dhadka", urdu: "دھڑکا", english: "beat", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "dhadki", urdu: "دھڑکی", english: "beat", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "dhadkay", urdu: "دھڑکے", english: "beat", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "dhadak raha", urdu: "دھڑک رہا", english: "is beating", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "dhadak rahi", urdu: "دھڑک رہی", english: "is beating", gender: "feminine", number: "singular", form: "continuous", }, { romanUrdu: "dhadakne", urdu: "دھڑکنے", english: "to beat / beating", gender: null, number: null, form: "oblique infinitive (alternate spelling)", }], image: "/qr/assets/images/dhadakna.webp", riddles: { english: "Inside the chest I tap away, Faster when feelings come to play.", romanUrdu: "Seene ke andar awaaz banaun, Jazba aaye to tez ho jaun.", urdu: "سینے کے اندر آواز بناؤں، جذبہ آئے تو تیز ہو جاؤں۔", }, },{id: "dheela", word: { baseRomanUrdu: "dheela", baseUrdu: "ڈھیلا", english: "loose", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "dheeli", urdu: "ڈھیلی", english: "loose", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "dheelay", urdu: "ڈھیلے", english: "loose", gender: "masculine", number: "plural", form: "plural / oblique form", }], image: "/qr/assets/images/dheela.webp", riddles: { english: "Not tight at all, I hang and sway,\nLike baggy clothes that slip away.", romanUrdu: "Tang nahi, khula khula,\nKapra latke jhoola jhoola.", urdu: "تنگ نہیں، کھلا کھلا،\nکپڑا لٹکے جھولا جھولا۔", }, },
{id: "dheere", word: { baseRomanUrdu: "dheere", baseUrdu: "دھیرے", english: "slowly", pos: "adverb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "dheere dheere", urdu: "دھیرے دھیرے", english: "very slowly / gradually", gender: null, number: null, form: "repeated form", }], image: "/qr/assets/images/dheere.webp", riddles: { english: "Not too fast, calm and light,\nSteps are soft and feel just right.", romanUrdu: "Na tez qadam, na jaldi ka kaam,\nAahista andaaz, bilkul araam.", urdu: "نہ تیز قدم، نہ جلدی کا کام،\nآہستہ انداز، بالکل آرام۔", }, },{id: "dhoop", word: { baseRomanUrdu: "dhoop", baseUrdu: "دھوپ", english: "sunlight", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/dhoop.webp", riddles: { english: "Warm bright rays from high above,\nPlants and mornings often love.", romanUrdu: "Upar se garam ujala aaye,\nSubah aur poday muskuraaye.", urdu: "اوپر سے گرم اجالا آئے،\nصبح اور پودے مسکرائیں۔", }, },{id: "dhulna", word: { baseRomanUrdu: "dhulna", baseUrdu: "دھلنا", english: "wash", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "dhula", urdu: "دھلا", english: "washed", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "dhuli", urdu: "دھلی", english: "washed", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "dhulay", urdu: "دھلے", english: "washed", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/dhulna.webp", riddles: { english: "Dust and dirt go far away,\nThings become clean for the day.", romanUrdu: "Mail aur gard door ho jaye,\nCheez saaf si nazar aaye.", urdu: "میل اور گرد دور ہو جائے،\nچیز صاف سی نظر آئے۔", }, },{id: "diggi", word: { baseRomanUrdu: "diggi", baseUrdu: "ڈگی", english: "car trunk", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "diggiyan", urdu: "ڈگیاں", english: "car trunk", gender: "feminine", number: "plural", form: "plural", }], image: "/qr/assets/images/diggi.webp", riddles: { english: "At the back of the car, things hide,\nBags and boxes take a ride.", romanUrdu: "Gaari ke peeche samaan chupaye,\nSafar mein cheezen saath le jaye.", urdu: "گاڑی کے پیچھے سامان چھپائے،\nسفر میں چیزیں ساتھ لے جائے۔", }, },{id: "dil", word: { baseRomanUrdu: "dil", baseUrdu: "دل", english: "heart", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "dilon", urdu: "دلوں", english: "hearts", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/dil.webp", riddles: { english: "It beats inside and feels things too,\nLove and courage live in you.", romanUrdu: "Seene mein dhak dhak karta jaye,\nPyar aur himmat yahin se aaye.", urdu: "سینے میں دھک دھک کرتا جائے،\nپیار اور ہمت یہیں سے آئے۔", }, },{id: "dilchasp", word: { baseRomanUrdu: "dilchasp", baseUrdu: "دلچسپ", english: "interesting", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/dilchasp.webp", riddles: { english: "I pull your mind and make you stare,\nA boring thing becomes rare.", romanUrdu: "Main zehan ko apni taraf bulaun,\nSaadi cheez ko mazaydar banaun.", urdu: "میں ذہن کو اپنی طرف بلاؤں،\nسادہ چیز کو مزے دار بناؤں۔", }, },{id: "din", word: { baseRomanUrdu: "din", baseUrdu: "دن", english: "day", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "dinoon", urdu: "دنوں", english: "days / of days", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/din.webp", riddles: { english: "The sun comes up, then fades away,\nWe count our life one bright stretch at a time.", romanUrdu: "Sooraj nikle, phir shaam ho jaye,\nIsi se waqt aage barhta jaye.", urdu: "سورج نکلے، پھر شام ہو جائے،\nاسی سے وقت آگے بڑھتا جائے۔", }, },{id: "do", word: { baseRomanUrdu: "do", baseUrdu: "دو", english: "two", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/do.webp", riddles: { english: "Not one, not three,\nJust a pair you can see.", romanUrdu: "Aik nahi, teen bhi nahi,\nBas jora sa samajh lo yahi.", urdu: "ایک نہیں، تین بھی نہیں،\nبس جوڑا سا سمجھ لو یہی۔", }, },{id: "door", word: { baseRomanUrdu: "door", baseUrdu: "دور", english: "far", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/door.webp", riddles: { english: "You can see it, but it is not near,\nSteps must travel to bring it here.", romanUrdu: "Nazar aaye magar paas na ho,\nQadam barhao to fasla kam ho.", urdu: "نظر آئے مگر پاس نہ ہو،\nقدم بڑھاؤ تو فاصلہ کم ہو۔", }, },{id: "dopahar", word: { baseRomanUrdu: "dopahar", baseUrdu: "دوپہر", english: "afternoon / noon", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/dopahar.webp", riddles: { english: "The sun is high, the day is bright,\nHalfway between morning and night.", romanUrdu: "Sooraj sar par aa jata hai,\nDin aadha ho jata hai.", urdu: "سورج سر پر آ جاتا ہے،\nدن آدھا ہو جاتا ہے۔", }, },{id: "dor", word: { baseRomanUrdu: "dor", baseUrdu: "ڈور", english: "string", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "dorein", urdu: "ڈوریں", english: "strings", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "doron", urdu: "ڈوروں", english: "of strings", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/dor.webp", riddles: { english: "It ties, pulls, and flies in the air,\nA kite may dance when I am there.", romanUrdu: "Bandhe, kheenche, patang uraye,\nHawa mein us ko nachwaye.", urdu: "باندھے، کھینچے، پتنگ اڑائے،\nہوا میں اس کو نچوائے۔", }, },{id: "dost", word: { baseRomanUrdu: "dost", baseUrdu: "دوست", english: "friend", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "doston", urdu: "دوستوں", english: "friends / of friends", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/dost.webp", riddles: { english: "Someone who laughs and shares with you,\nBy your side when skies turn blue.", romanUrdu: "Jo saath hase aur saath nibhaye,\nUdaasi mein bhi paas aa jaye.", urdu: "جو ساتھ ہنسے اور ساتھ نبھائے،\nاداسی میں بھی پاس آ جائے۔", }, },{id: "dua", word: { baseRomanUrdu: "dua", baseUrdu: "دعا", english: "prayer", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "duaein", urdu: "دعائیں", english: "prayers", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "duaon", urdu: "دعاؤں", english: "of prayers", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/dua.webp", riddles: { english: "Hands rise softly, hearts feel light,\nQuiet words reach beyond sight.", romanUrdu: "Haath uthte, dil halka ho jaye,\nChup alfaaz upar tak jayein.", urdu: "ہاتھ اٹھتے، دل ہلکا ہو جائے،\nچپ الفاظ اوپر تک جائیں۔", }, },{id: "dupatta", word: { baseRomanUrdu: "dupatta", baseUrdu: "دوپٹہ", english: "scarf", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "dupattay", urdu: "دوپٹے", english: "scarves", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "dupatton", urdu: "دوپٹوں", english: "scarves / of scarves", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/dupatta.webp", riddles: { english: "Soft cloth rests around the head, On shoulders it may gently spread.", romanUrdu: "Narm kapra sar par aaye, Kandhon par bhi phelta jaye.", urdu: "نرم کپڑا سر پر آئے، کندھوں پر بھی پھیلتا جائے۔", }, },{id: "ehsas", word: { baseRomanUrdu: "ehsas", baseUrdu: "احساس", english: "feeling", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/ehsas.webp", riddles: { english: "Inside your heart, I quietly grow,\nI help you understand what you know.", romanUrdu: "Dil ke andar chup sa rehta,\nAndar ki baat tumhein kehta.", urdu: "دل کے اندر چپ سا رہتا،\nاندر کی بات تمہیں کہتا۔", }, },{id: "eidi", word: { baseRomanUrdu: "eidi", baseUrdu: "عیدی", english: "gift", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "eidiyan", urdu: "عیدیاں", english: "gifts", gender: "feminine", number: "plural", form: "plural", }], image: "/qr/assets/images/eidi.webp", riddles: { english: "On Eid, a small surprise may come,\nChildren smile when they get some.", romanUrdu: "Eid par milti pyari si cheez,\nBachon ke chehray par aaye tameez.", urdu: "عید پر ملتی پیاری سی چیز،\nبچوں کے چہرے پر خوشی کی تمیز۔", }, },{id: "faisla", word: { baseRomanUrdu: "faisla", baseUrdu: "فیصلہ", english: "decision", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "faislay", urdu: "فیصلے", english: "decisions", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "faisla karna", urdu: "فیصلہ کرنا", english: "to decide", gender: null, number: null, form: "phrase", }], image: "/qr/assets/images/faisla.webp", riddles: { english: "After thinking, one path is chosen,\nThe mind says this way is open.", romanUrdu: "Soch ke ek raasta chuna jaye,\nDil aur dimagh keh dein, yahi sahi aaye.", urdu: "سوچ کے ایک راستہ چنا جائے،\nدل اور دماغ کہہ دیں، یہی صحیح آئے۔", }, },{id: "fakhr", word: { baseRomanUrdu: "fakhr", baseUrdu: "فخر", english: "pride", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/fakhr.webp", riddles: { english: "Your heart stands tall when you do right,\nA warm glow grows inside so bright.", romanUrdu: "Achha kaam ho to seena bhar jaye,\nDil andar se roshan ho jaye.", urdu: "اچھا کام ہو تو سینہ بھر جائے،\nدل اندر سے روشن ہو جائے۔", }, },{id: "gaari", word: { baseRomanUrdu: "gaari", baseUrdu: "گاڑی", english: "car", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "gaariyan", urdu: "گاڑیاں", english: "cars", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "gaariyon", urdu: "گاڑیوں", english: "of cars", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/gaari.webp", riddles: { english: "Four wheels roll along the way,\nTaking families out each day.", romanUrdu: "Chaar pahiye raste par chalein,\nGhar walon ko saath le chalein.", urdu: "چار پہیے راستے پر چلیں،\nگھر والوں کو ساتھ لے چلیں۔", }, },{id: "gaaye", word: { baseRomanUrdu: "gaaye", baseUrdu: "گائے", english: "cow", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "gaayein", urdu: "گائیں", english: "cows", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "gaayon", urdu: "گایوں", english: "cows", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/gaaye.webp", riddles: { english: "A big gentle farm friend gives milk,\nMoves slowly, soft as silk.", romanUrdu: "Bari si dost doodh bhi de,\nAahista chalti sab ke liye.", urdu: "بڑی سی دوست دودھ بھی دے،\nآہستہ چلتی سب کے لیے۔", }, },{id: "gaind", word: { baseRomanUrdu: "gaind", baseUrdu: "گیند", english: "ball", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "gaindein", urdu: "گیندیں", english: "balls", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "gaindon", urdu: "گیندوں", english: "of balls", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/gaind.webp", riddles: { english: "Round and bouncy, tossed in play,\nCatch me fast before I roll away.", romanUrdu: "Gol si cheez uchhalti jaye,\nPakro warna door nikal jaye.", urdu: "گول سی چیز اچھلتی جائے،\nپکڑو ورنہ دور نکل جائے۔", }, },{id: "gajar", word: { baseRomanUrdu: "gajar", baseUrdu: "گاجر", english: "carrot", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "gajrein", urdu: "گاجریں", english: "carrots", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "gajron", urdu: "گاجروں", english: "carrots", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/gajar.webp", riddles: { english: "Orange and crunchy, long and sweet,\nIn salad or halwa, I am fun to eat!", romanUrdu: "Narangi, karari, lambi aur meethi,\nSalad ya halway mein lagun badi pyari!", urdu: "نارنجی، کراری، لمبی اور میٹھی،\nسلاد یا حلوے میں لگوں بڑی پیاری!", }, },{id: "gali", word: { baseRomanUrdu: "gali", baseUrdu: "گلی", english: "street", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "galiyan", urdu: "گلیاں", english: "streets", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "galiyon", urdu: "گلیوں", english: "of streets", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/gali.webp", riddles: { english: "Between homes I make a way,\nChildren may run through me and play.", romanUrdu: "Gharon ke beech mera rasta,\nBachon ka hota aana jaana.", urdu: "گھروں کے بیچ میرا راستہ،\nبچوں کا ہوتا آنا جانا۔", }, },{id: "garam", word: { baseRomanUrdu: "garam", baseUrdu: "گرم", english: "hot", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/garam.webp", riddles: { english: "I can warm your hands or tea, But too much of me makes you flee.", romanUrdu: "Haath ya chai ko garam banaun, Zyada ho jaun to pasina laun.", urdu: "ہاتھ یا چائے کو گرم بناؤں، زیادہ ہو جاؤں تو پسینہ لاؤں۔", }, },{id: "garmi", word: { baseRomanUrdu: "garmi", baseUrdu: "گرمی", english: "heat", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "garmiyan", urdu: "گرمیاں", english: "summers", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "garmiyon", urdu: "گرمیوں", english: "summers", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/garmi.webp", riddles: { english: "When the day feels much too hot, I make you search a cooler spot.", romanUrdu: "Din ko zyada garam banaun, Thandi jagah ki yaad dilaun.", urdu: "دن کو زیادہ گرم بناؤں، ٹھنڈی جگہ کی یاد دلاؤں۔", }, },{id: "ghabrana", word: { baseRomanUrdu: "ghabrana", baseUrdu: "گھبرانا", english: "worry", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "ghabraya", urdu: "گھبرایا", english: "worried", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "ghabrayi", urdu: "گھبرائی", english: "worried", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "ghabraye", urdu: "گھبرائے", english: "worried", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/ghabrana.webp", riddles: { english: "When the heart beats fast with fear,\nSlow breaths help calm it here.", romanUrdu: "Dil tez dhadke, fikr barh jaye,\nAhista saans lo, sukoon aa jaye.", urdu: "دل تیز دھڑکے، فکر بڑھ جائے،\nآہستہ سانس لو، سکون آ جائے۔", }, },{id: "ghanti", word: { baseRomanUrdu: "ghanti", baseUrdu: "گھنٹی", english: "bell", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "ghantiyan", urdu: "گھنٹیاں", english: "bell", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "ghantiyon", urdu: "گھنٹیوں", english: "of bells", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/ghanti.webp", riddles: { english: "A ringing sound calls everyone near,\nTing ting tells you something to hear.", romanUrdu: "Tan tan awaaz sab ko bulaye,\nDarwaze ya school mein sunai aaye.", urdu: "ٹن ٹن آواز سب کو بلائے،\nدروازے یا اسکول میں سنائی آئے۔", }, },{id: "ghar", word: { baseRomanUrdu: "ghar", baseUrdu: "گھر", english: "home", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "gharon", urdu: "گھروں", english: "homes / of homes", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/ghar.webp", riddles: { english: "A place where shoes come off with ease,\nFamily gathers and hearts feel peace.", romanUrdu: "Jahan apne sab mil baithte,\nThakay qadam bhi araam paate.", urdu: "جہاں اپنے سب مل بیٹھتے،\nتھکے قدم بھی آرام پاتے۔", }, },{id: "ghoomna", word: { baseRomanUrdu: "ghoomna", baseUrdu: "گھومنا", english: "spin", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "ghooma", urdu: "گھوما", english: "spun", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "ghoomi", urdu: "گھومی", english: "spun", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "ghoome", urdu: "گھومے", english: "spun", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/ghoomna.webp", riddles: { english: "Round and round, I turn with flair,\nLike a top dancing in the air.", romanUrdu: "Gol gol chakkar khaun,\nLattu ki tarah ghoomta jaun.", urdu: "گول گول چکر کھاؤں،\nلٹو کی طرح گھومتا جاؤں۔", }, },{id: "ghussa", word: { baseRomanUrdu: "ghussa", baseUrdu: "غصہ", english: "anger", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/ghussa.webp", riddles: { english: "A hot feeling in the heart,\nIt can make kind words fall apart.", romanUrdu: "Dil mein garam sa ehsaas aaye,\nMeethi baat bhi door ho jaye.", urdu: "دل میں گرم سا احساس آئے،\nمیٹھی بات بھی دور ہو جائے۔", }, },{id: "goonj", word: { baseRomanUrdu: "goonj", baseUrdu: "گونج", english: "echo", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/goonj.webp", riddles: { english: "A sound that bounces back to you,\nFrom walls and valleys, old and new.", romanUrdu: "Awaaz jo wapas aa jaye,\nDeewaron se takra jaye.", urdu: "آواز جو واپس آ جائے،\nدیواروں سے ٹکرا جائے۔", }, },{id: "goonjana", word: { baseRomanUrdu: "goonjana", baseUrdu: "گونجنا", english: "echo", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "goonja", urdu: "گونجا", english: "echoed", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "goonji", urdu: "گونجی", english: "echoed", gender: "feminine", number: "singular", form: "past", }], image: "/qr/assets/images/goonjana.webp", riddles: { english: "A sound goes out and comes once more,\nLike a voice bouncing from a door.", romanUrdu: "Awaaz ja kar wapas aaye,\nDeewar se takra kar sunai de jaye.", urdu: "آواز جا کر واپس آئے،\nدیوار سے ٹکرا کر سنائی دے جائے۔", }, },{id: "gulabi", word: { baseRomanUrdu: "gulabi", baseUrdu: "گلابی", english: "pink", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/gulabi.webp", riddles: { english: "Soft like roses, sweet and bright,\nA color gentle in the light.", romanUrdu: "Phoolon jaisa narm sa rang,\nDekho to lage pyaara sang.", urdu: "پھولوں جیسا نرم سا رنگ،\nدیکھو تو لگے پیارا سنگ۔", }, },{id: "gutli", word: { baseRomanUrdu: "gutli", baseUrdu: "گٹھلی", english: "mango seed", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "gutliyan", urdu: "گٹھلیاں", english: "mango seed", gender: "feminine", number: "plural", form: "plural", }], image: "/qr/assets/images/gutli.webp", riddles: { english: "Inside the fruit, hard and round,\nAfter eating, it is found.", romanUrdu: "Phal ke andar sakht cheez aaye,\nKha kar akhir haath mein aaye.", urdu: "پھل کے اندر سخت چیز آئے،\nکھا کر آخر ہاتھ میں آئے۔", }, },{id: "haar", word: { baseRomanUrdu: "haar", baseUrdu: "ہار", english: "loss", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/haar.webp", riddles: { english: "When the game is not your way,\nTry again another day.", romanUrdu: "Khel mein jab baari na aaye,\nPhir koshish dil ko mazboot banaye.", urdu: "کھیل میں جب باری نہ آئے،\nپھر کوشش دل کو مضبوط بنائے۔", }, },{id: "haar_maanna", word: { baseRomanUrdu: "haar maanna", baseUrdu: "ہار ماننا", english: "give up", pos: "phrase", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "haar maan li", urdu: "ہار مان لی", english: "gave up", gender: "feminine", number: "singular", form: "past compound", }, { romanUrdu: "haar maan liya", urdu: "ہار مان لیا", english: "gave up", gender: "masculine", number: "singular", form: "past compound", }, { romanUrdu: "haar mat maano", urdu: "ہار مت مانو", english: "don't give up", gender: null, number: null, form: "negative command", }], image: "/qr/assets/images/haar_maanna.webp", riddles: { english: "When a task is hard to do,\nDon't do this, keep pushing through!", romanUrdu: "Kaam mushkil ho to bhi,\nYeh na karna, koshish karo abhi.", urdu: "کام مشکل ہو تو بھی،\nیہ نہ کرنا، کوشش کرو ابھی۔", }, },
{id: "haath", word: { baseRomanUrdu: "haath", baseUrdu: "ہاتھ", english: "hand", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "haathon", urdu: "ہاتھوں", english: "hands", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/haath.webp", riddles: { english: "Five fingers help you hold and share,\nWave hello in the air.", romanUrdu: "Paanch ungliyan kaam banayein,\nSalam ke liye hil jayein.", urdu: "پانچ انگلیاں کام بنائیں،\nسلام کے لیے ہل جائیں۔", }, },{id: "hal", word: { baseRomanUrdu: "hal", baseUrdu: "حل", english: "solution", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "hal karna", urdu: "حل کرنا", english: "to solve", gender: null, number: null, form: "phrase", }], image: "/qr/assets/images/hal.webp", riddles: { english: "A problem waits for this one key,\nThen the hard thing becomes easy.", romanUrdu: "Mushkil ka jab raasta mil jaye,\nUlji baat asaan ho jaye.", urdu: "مشکل کا جب راستہ مل جائے،\nالجھی بات آسان ہو جائے۔", }, },{id: "halka", word: { baseRomanUrdu: "halka", baseUrdu: "ہلکا", english: "light", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "halki", urdu: "ہلکی", english: "light", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "halkay", urdu: "ہلکے", english: "light", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/halka.webp", riddles: { english: "Easy to lift, not heavy to hold,\nSoft as a feather, gentle not bold.", romanUrdu: "Uthana aasaan, bojh na lage,\nPar ki tarah narm sa lage.", urdu: "اٹھانا آسان، بوجھ نہ لگے،\nپر کی طرح نرم سا لگے۔", }, },{id: "hansna", word: { baseRomanUrdu: "hansna", baseUrdu: "ہنسنا", english: "laugh", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "hansa", urdu: "ہنسا", english: "laughed", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "hansi", urdu: "ہنسی", english: "laughed", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "hans raha", urdu: "ہنس رہا", english: "is laughing", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "hans rahi", urdu: "ہنس رہی", english: "is laughing", gender: "feminine", number: "singular", form: "continuous", }, { romanUrdu: "hansay", urdu: "ہنسے", english: "laughed", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "hanstay", urdu: "ہنستے", english: "laughing", gender: "masculine", number: "plural", form: "habitual", }, { romanUrdu: "hans paray", urdu: "ہنس پڑے", english: "burst out laughing", gender: "masculine", number: "plural", form: "past compound", }, { romanUrdu: "hanso", urdu: "ہنسو", english: "laugh", gender: null, number: null, form: "command", }, ], image: "/qr/assets/images/hansna.webp", riddles: { english: "A funny joke makes me appear,\nA happy sound for all to hear.", romanUrdu: "Mazay ki baat sun kar aaun,\nKhushi ki awaaz ban jaun.", urdu: "مزے کی بات سن کر آؤں،\nخوشی کی آواز بن جاؤں۔", }, },{id: "harna", word: { baseRomanUrdu: "harna", baseUrdu: "ہارنا", english: "lose", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "hara", urdu: "ہارا", english: "lost", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "hari", urdu: "ہاری", english: "lost", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "hare", urdu: "ہارے", english: "lost", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/harna.webp", riddles: { english: "You did not win this time around,\nBut courage can still be found.", romanUrdu: "Is dafa jeet haath na aaye,\nPhir bhi himmat kaam aa jaye.", urdu: "اس دفعہ جیت ہاتھ نہ آئے،\nپھر بھی ہمت کام آ جائے۔", }, },{id: "haveli", word: { baseRomanUrdu: "haveli", baseUrdu: "حویلی", english: "mansion / ancestral house", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "haveliyan", urdu: "حویلیاں", english: "mansions", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "haveliyon", urdu: "حویلیوں", english: "of mansions", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/haveli.webp", riddles: { english: "A big old home with a courtyard wide,\nMany family stories live inside.", romanUrdu: "Bara sa purana ghar, beech mein sehan,\nKai naslon ki kahaniyan yahan.", urdu: "بڑا سا پرانا گھر، بیچ میں صحن،\nکئی نسلوں کی کہانیاں یہاں۔", }, },{id: "hawa", word: { baseRomanUrdu: "hawa", baseUrdu: "ہوا", english: "wind", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "hawaein", urdu: "ہوائیں", english: "winds", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "hawaon", urdu: "ہواؤں", english: "winds", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/hawa.webp", riddles: { english: "You cannot see me, but I blow,\nLeaves and kites move when I go.", romanUrdu: "Nazar na aaun, phir bhi chalun,\nPatton ko hilata phirun.", urdu: "نظر نہ آؤں، پھر بھی چلوں،\nپتوں کو ہلاتا پھروں۔", }, },{id: "hilana", word: { baseRomanUrdu: "hilana", baseUrdu: "ہلانا", english: "shake", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "hilaya", urdu: "ہلایا", english: "shook", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "hilayi", urdu: "ہلائی", english: "shook", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "hilaye", urdu: "ہلائے", english: "shook", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "hila", urdu: "ہلا", english: "shake", gender: null, number: null, form: "stem (with kar)", }, { romanUrdu: "hilao", urdu: "ہلاؤ", english: "shake", gender: null, number: null, form: "command", }, { romanUrdu: "hila raha", urdu: "ہلا رہا", english: "is shaking", gender: "masculine", number: "singular", form: "continuous", }], image: "/qr/assets/images/hilana.webp", riddles: { english: "Quickly move it to and fro,\nA rattle sings when you do so.", romanUrdu: "Jaldi jaldi aage peeche,\nJhunjhuna bole oonche neeche.", urdu: "جلدی جلدی آگے پیچھے،\nجھنجھنا بولے اونچے نیچے۔", }, },
{id: "hissa", word: { baseRomanUrdu: "hissa", baseUrdu: "حصہ", english: "part", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "hissay", urdu: "حصے", english: "parts", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "hisson", urdu: "حصوں", english: "of parts", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/hissa.webp", riddles: { english: "A whole can split and I appear,\nOne small piece becomes clear.", romanUrdu: "Poori cheez jab bant jaye,\nMera chhota tukra nazar aaye.", urdu: "پوری چیز جب بٹ جائے،\nمیرا چھوٹا ٹکڑا نظر آئے۔", }, },{id: "intizaar", word: { baseRomanUrdu: "intizaar", baseUrdu: "انتظار", english: "waiting", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "intizaar karna", urdu: "انتظار کرنا", english: "to wait", gender: null, number: null, form: "phrase", }, { romanUrdu: "intizaar kiya", urdu: "انتظار کیا", english: "waited", gender: "masculine", number: "singular", form: "past", }], image: "/qr/assets/images/intizaar.webp", riddles: { english: "You stand and hope someone will come,\nThe clock feels slow for everyone.", romanUrdu: "Ruk kar kisi ka raasta dekho,\nWaqt ko dheere chalte dekho.", urdu: "رک کر کسی کا راستہ دیکھو،\nوقت کو دھیرے چلتے دیکھو۔", }, },{id: "istri", word: { baseRomanUrdu: "istri", baseUrdu: "استری", english: "iron", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "istriyan", urdu: "استریاں", english: "irons", gender: "feminine", number: "plural", form: "plural", }], image: "/qr/assets/images/istri.webp", riddles: { english: "I make wrinkled cloth look neat,\nWarm and flat from gentle heat.", romanUrdu: "Kapray ki silwat door karaun,\nGarmi se us ko seedha banaun.", urdu: "کپڑے کی سلوٹ دور کراؤں،\nگرمی سے اس کو سیدھا بناؤں۔", }, },{id: "jaagna", word: { baseRomanUrdu: "jaagna", baseUrdu: "جاگنا", english: "awaken", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "jaaga", urdu: "جاگا", english: "woke up", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "jaagi", urdu: "جاگی", english: "woke up", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "jaage", urdu: "جاگے", english: "woke up", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "jaagte", urdu: "جاگتے", english: "awake / waking", gender: "masculine", number: "plural", form: "continuous", }], image: "/qr/assets/images/jaagna.webp", riddles: { english: "Sleep goes away, eyes open wide,\nMorning comes and you rise inside.", romanUrdu: "Neend chali jaye, aankh khul jaye,\nSubah ke saath banda uth jaye.", urdu: "نیند چلی جائے، آنکھ کھل جائے،\nصبح کے ساتھ بندہ اٹھ جائے۔", }, },{id: "jagah", word: { baseRomanUrdu: "jagah", baseUrdu: "جگہ", english: "place", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "jagahein", urdu: "جگہیں", english: "places", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "jagahon", urdu: "جگہوں", english: "places", gender: "feminine", number: "plural", form: "plural oblique", }, ], image: "/qr/assets/images/jagah.webp", riddles: { english: "Every thing needs one little space,\nFind me for a proper place.", romanUrdu: "Har cheez ko chahiye apni si jagah,\nDhoondo mujhe to mile sahi panah.", urdu: "ہر چیز کو چاہیے اپنی سی جگہ،\nڈھونڈو مجھے تو ملے صحیح پناہ۔", }, },{id: "jaldi", word: { baseRomanUrdu: "jaldi", baseUrdu: "جلدی", english: "quickly", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/jaldi.webp", riddles: { english: "No slow steps, no long delay,\nMove with speed and finish today.", romanUrdu: "Dheere nahi, waqt bachao,\nTezi se kaam niptao.", urdu: "دھیرے نہیں، وقت بچاؤ،\nتیزی سے کام نپٹاؤ۔", }, },{id: "jama", word: { baseRomanUrdu: "jama", baseUrdu: "جمع", english: "gather", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "jama", urdu: "جمع", english: "gathered / collected", gender: null, number: null, form: "needs review", }, { romanUrdu: "juma", urdu: "جمعہ", english: "Friday", gender: "masculine", number: "singular", form: "needs review", }], image: "/qr/assets/images/jama.webp", riddles: { english: "Many things come to one spot,\nTogether they make a bigger lot.", romanUrdu: "Kai cheezen aik taraf aa jayein,\nMil kar zyada ban jayein.", urdu: "کئی چیزیں ایک طرف آ جائیں،\nمل کر زیادہ بن جائیں۔", }, },{id: "jana", word: { baseRomanUrdu: "jana", baseUrdu: "جانا", english: "go", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "gaya", urdu: "گیا", english: "went", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "gayi", urdu: "گئی", english: "went", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "gaye", urdu: "گئے", english: "went", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "jao", urdu: "جاؤ", english: "go!", gender: null, number: null, form: "command", }, { romanUrdu: "chala gaya", urdu: "چلا گیا", english: "went away", gender: "masculine", number: "singular", form: "past compound", }, { romanUrdu: "chali gayi", urdu: "چلی گئی", english: "went away", gender: "feminine", number: "singular", form: "past compound", }], image: "/qr/assets/images/jana.webp", riddles: { english: "Feet move away from here,\nA new place slowly comes near.", romanUrdu: "Qadam yahan se aage barhein,\nNayi manzil ki taraf chal parein.", urdu: "قدم یہاں سے آگے بڑھیں،\nنئی منزل کی طرف چل پڑیں۔", }, },{id: "jandaar", word: { baseRomanUrdu: "jandaar", baseUrdu: "جاندار", english: "lively", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/jandaar.webp", riddles: { english: "Full of energy, bright and strong,\nNothing feels dull for long.", romanUrdu: "Josh se bhara, roshan sa andaaz,\nHar cheez mein aaye naya sa raaz.", urdu: "جوش سے بھرا، روشن سا انداز،\nہر چیز میں آئے نیا سا راز۔", }, },{id: "janwar", word: { baseRomanUrdu: "janwar", baseUrdu: "جانور", english: "animal", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "janwaron", urdu: "جانوروں", english: "animal", gender: null, number: "plural", form: "plural oblique", }], image: "/qr/assets/images/janwar.webp", riddles: { english: "Not a person, but alive,\nIt may walk, swim, fly, or thrive.", romanUrdu: "Insaan nahi, magar jaan rakhta,\nChalta, tairta, ya urr sakta.", urdu: "انسان نہیں، مگر جان رکھتا،\nچلتا، تیرتا، یا اڑ سکتا۔", }, },{id: "jashn_manana", word: { baseRomanUrdu: "jashn_manana", baseUrdu: "جشن منانا", english: "celebrate", pos: "phrase", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "jashn manaya", urdu: "جشن منایا", english: "celebrated", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "jashn manayi", urdu: "جشن منائی", english: "celebrated", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "jashn manaye", urdu: "جشن منائے", english: "celebrated", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/jashn_manana.webp", riddles: { english: "Happy moments bring people near,\nFood and laughter fill the cheer.", romanUrdu: "Khushi ka mauqa sab ko bulaye,\nHansi aur khana rang jamaye.", urdu: "خوشی کا موقع سب کو بلائے،\nہنسی اور کھانا رنگ جمائے۔", }, },{id: "jeetna", word: { baseRomanUrdu: "jeetna", baseUrdu: "جیتنا", english: "win", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "jeeta", urdu: "جیتا", english: "won", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "jeeti", urdu: "جیتی", english: "won", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "jeete", urdu: "جیتے", english: "won", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "jeet", urdu: "جیت", english: "victory", gender: "feminine", number: "singular", form: "noun form", }], image: "/qr/assets/images/jeetna.webp", riddles: { english: "At the end, you come out first,\nPractice helped you do your best.", romanUrdu: "Aakhir mein sab se aage aao,\nMehnat ka phal tum pao.", urdu: "آخر میں سب سے آگے آؤ،\nمحنت کا پھل تم پاؤ۔", }, },{id: "jhanda", word: { baseRomanUrdu: "jhanda", baseUrdu: "جھنڈا", english: "flag", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "jhanday", urdu: "جھنڈے", english: "flags", gender: "masculine", number: "plural", form: "plural / oblique", }, { romanUrdu: "jhandon", urdu: "جھنڈوں", english: "flags", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/jhanda.webp", riddles: { english: "On a pole I rise and fly,\nWaving proudly in the sky.", romanUrdu: "Danday par charh kar lehraun,\nFakhr se aasman ko chhoo jaun.", urdu: "ڈنڈے پر چڑھ کر لہراؤں،\nفخر سے آسمان کو چھو جاؤں۔", }, },{id: "jhandi", word: { baseRomanUrdu: "jhandi", baseUrdu: "جھنڈی", english: "small flag", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "jhandiyan", urdu: "جھنڈیاں", english: "small flags", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "jhandiyon", urdu: "جھنڈیوں", english: "small flags", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/jhandi.webp", riddles: { english: "Small and bright on strings I sway,\nGreen and white for a special day.", romanUrdu: "Dori par chhoti si lehraun,\nSabz safaid rang dikhaun.", urdu: "ڈوری پر چھوٹی سی لہراؤں،\nسبز سفید رنگ دکھاؤں۔", }, },{id: "jhukna", word: { baseRomanUrdu: "jhukna", baseUrdu: "جھکنا", english: "bend", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "jhuka", urdu: "جھکا", english: "bent", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "jhuki", urdu: "جھکی", english: "bent", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "jhuk gayi", urdu: "جھک گئی", english: "bent down", gender: "feminine", number: "singular", form: "past compound", }, { romanUrdu: "jhuko", urdu: "جھکو", english: "bend", gender: null, number: null, form: "command", }], image: "/qr/assets/images/jhukna.webp", riddles: { english: "Like a branch heavy with fruit,\nLower your head down to your boot.", romanUrdu: "Phal se bhari shaakh ki tarah,\nSar neeche kar lo is jagah.", urdu: "پھل سے بھری شاخ کی طرح،\nسر نیچے کر لو اس جگہ۔", }, },
{id: "joota", word: { baseRomanUrdu: "joota", baseUrdu: "جوتا", english: "shoe", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "jootay", urdu: "جوتے", english: "shoes", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "jooton", urdu: "جوتوں", english: "of shoes", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/joota.webp", riddles: { english: "I cover feet when you go out,\nLeft and right, I walk about.", romanUrdu: "Paon ko bahar le kar jaun,\nJore mein tumhare saath nibhaun.", urdu: "پاؤں کو باہر لے کر جاؤں،\nجوڑے میں تمہارے ساتھ نبھاؤں۔", }, },{id: "jora", word: { baseRomanUrdu: "jora", baseUrdu: "جوڑا", english: "outfit", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "joray", urdu: "جوڑے", english: "outfits", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "joron", urdu: "جوڑوں", english: "of outfits", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/jora.webp", riddles: { english: "For Eid or school, you put me on,\nColors shine from dusk to dawn.", romanUrdu: "Eid ho ya school ka din,\nPehno mujhe, nikle rangin.", urdu: "عید ہو یا اسکول کا دن،\nپہنو مجھے، نکلے رنگین۔", }, },{id: "kaam", word: { baseRomanUrdu: "kaam", baseUrdu: "کام", english: "work", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "kaamon", urdu: "کاموں", english: "works / tasks", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/kaam.webp", riddles: { english: "A task to finish, big or small,\nDoing it well helps us all.", romanUrdu: "Chhota ho ya bara koi kaam,\nPura ho to milta araam.", urdu: "چھوٹا ہو یا بڑا کوئی کام،\nپورا ہو تو ملتا آرام۔", }, },{id: "kabhi", word: { baseRomanUrdu: "kabhi", baseUrdu: "کبھی", english: "sometimes", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/kabhi.webp", riddles: { english: "Not always, not never too,\nI happen only now and then for you.", romanUrdu: "Hamesha nahi, bilkul nahi bhi nahi,\nKabhi kabhar aaun main yahi.", urdu: "ہمیشہ نہیں، بالکل نہیں بھی نہیں،\nکبھی کبھار آؤں میں یہی۔", }, },{id: "kachay", word: { baseRomanUrdu: "kachay", baseUrdu: "کچے", english: "unripe", pos: "adjective", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "kacha", urdu: "کچا", english: "unripe", gender: "masculine", number: "singular", form: "masculine singular", }, { romanUrdu: "kachi", urdu: "کچی", english: "unripe", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "kachiyan", urdu: "کچیاں", english: "unripe", gender: "feminine", number: "plural", form: "feminine plural", }], image: "/qr/assets/images/kachay.webp", riddles: { english: "Not ready yet, still firm inside,\nNeeds more time before its pride.", romanUrdu: "Abhi poora tayyar na ho,\nThora waqt aur chahiye ho.", urdu: "ابھی پورا تیار نہ ہو،\nتھوڑا وقت اور چاہیے ہو۔", }, },{id: "kagaz", word: { baseRomanUrdu: "kagaz", baseUrdu: "کاغذ", english: "paper", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "kagazat", urdu: "کاغذات", english: "paper", gender: null, number: "plural", form: "plural", }], image: "/qr/assets/images/kagaz.webp", riddles: { english: "You can draw or write on me,\nI can become a note to see.", romanUrdu: "Is par likho ya tasveer banao,\nChoti si baat sab ko dikhao.", urdu: "اس پر لکھو یا تصویر بناؤ،\nچھوٹی سی بات سب کو دکھاؤ۔", }, },{id: "kahani", word: { baseRomanUrdu: "kahani", baseUrdu: "کہانی", english: "story", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "kahaniyan", urdu: "کہانیاں", english: "stories", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "kahaniyon", urdu: "کہانیوں", english: "stories", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/kahani.webp", riddles: { english: "It has a start, a middle, an end,\nListen closely, it is your friend.", romanUrdu: "Shuru se aakhir tak chalti hai,\nSunne walon ko pyari lagti hai.", urdu: "شروع سے آخر تک چلتی ہے،\nسننے والوں کو پیاری لگتی ہے۔", }, },{id: "kal", word: { baseRomanUrdu: "kal", baseUrdu: "کل", english: "tomorrow", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/kal.webp", riddles: { english: "It can point to another day,\nBefore or after, people may say.", romanUrdu: "Aik din ki taraf ishara kare,\nAage ya peeche matlab bhare.", urdu: "ایک دن کی طرف اشارہ کرے،\nآگے یا پیچھے مطلب بھرے۔", }, },{id: "kamra", word: { baseRomanUrdu: "kamra", baseUrdu: "کمرہ", english: "room", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "kamray", urdu: "کمرے", english: "rooms", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "kamron", urdu: "کمروں", english: "of rooms", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/kamra.webp", riddles: { english: "Walls around and a door to close,\nA bed or books may live in those.", romanUrdu: "Deewaren, darwaza, apni si jagah,\nAndar rehta samaan ya panah.", urdu: "دیواریں، دروازہ، اپنی سی جگہ،\nاندر رہتا سامان یا پناہ۔", }, },{id: "kapra", word: { baseRomanUrdu: "kapra", baseUrdu: "کپڑا", english: "clothes", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "kapray", urdu: "کپڑے", english: "clothes", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "kapron", urdu: "کپڑوں", english: "of clothes", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/kapra.webp", riddles: { english: "Soft fabric covers you each day,\nFold me neatly after play.", romanUrdu: "Narm kapra badan dhakaye,\nDhula ho to almari mein jaye.", urdu: "نرم کپڑا بدن ڈھکائے،\nدھلا ہو تو الماری میں جائے۔", }, },{id: "kat", word: { baseRomanUrdu: "kat", baseUrdu: "کٹ", english: "cut", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/kat.webp", riddles: { english: "A small mark where something split,\nCareful hands should handle it.", romanUrdu: "Jahan cheez thori si toot jaye,\nHifazat se phir kaam banaye.", urdu: "جہاں چیز تھوڑی سی ٹوٹ جائے،\nحفاظت سے پھر کام بنائے۔", }, },{id: "keera", word: { baseRomanUrdu: "keera", baseUrdu: "کیڑا", english: "insect", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "keere", urdu: "کیڑے", english: "insects", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "keeron", urdu: "کیڑوں", english: "insects", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/keera.webp", riddles: { english: "Tiny legs, tiny crawl,\nYou may spot me on a leaf or wall.", romanUrdu: "Chhoti taangein, chhoti chaal,\nPattay ya deewar par aaun nazar kabhi haal.", urdu: "چھوٹی ٹانگیں، چھوٹی چال،\nپتے یا دیوار پر آؤں نظر کبھی حال۔", }, },{id: "kehna", word: { baseRomanUrdu: "kehna", baseUrdu: "کہنا", english: "say", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "kaha", urdu: "کہا", english: "said", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "kahi", urdu: "کہی", english: "said", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "kaho", urdu: "کہو", english: "say", gender: null, number: null, form: "command", }, { romanUrdu: "keh raha", urdu: "کہہ رہا", english: "is saying", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "keh rahi", urdu: "کہہ رہی", english: "is saying", gender: "feminine", number: "singular", form: "continuous", }, { romanUrdu: "kahay", urdu: "کہے", english: "said", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/kehna.webp", riddles: { english: "Words leave your mouth to share,\nA thought travels through the air.", romanUrdu: "Alfaaz zuban se bahar aayein,\nDil ki baat dusron tak jaye.", urdu: "الفاظ زبان سے باہر آئیں،\nدل کی بات دوسروں تک جائے۔", }, },{id: "khaali", word: { baseRomanUrdu: "khaali", baseUrdu: "خالی", english: "empty", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/khaali.webp", riddles: { english: "Nothing inside, not even one,\nA box like this has none, not one.", romanUrdu: "Andar kuch bhi nahi hai bhai,\nDabba dekho, safaai hi safaai.", urdu: "اندر کچھ بھی نہیں ہے بھائی،\nڈبہ دیکھو، صفائی ہی صفائی۔", }, },{id: "khaas", word: { baseRomanUrdu: "khaas", baseUrdu: "خاص", english: "special", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/khaas.webp", riddles: { english: "Not ordinary, not the same,\nChosen with a brighter name.", romanUrdu: "Aam nahi, kuch alag si baat,\nDil mein banaye apni jagah khaas.", urdu: "عام نہیں، کچھ الگ سی بات،\nدل میں بنائے اپنی جگہ خاص۔", }, },{id: "khabar", word: { baseRomanUrdu: "khabar", baseUrdu: "خبر", english: "news", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "khabrein", urdu: "خبریں", english: "news items", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "khabron", urdu: "خبروں", english: "of news items", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/khabar.webp", riddles: { english: "Something happened, now you know,\nWords can make the story show.", romanUrdu: "Kuch hua to baat bataye,\nDuniya ki halat samjhaye.", urdu: "کچھ ہوا تو بات بتائے،\nدنیا کی حالت سمجھائے۔", }, },{id: "khajoor", word: { baseRomanUrdu: "khajoor", baseUrdu: "کھجور", english: "dates", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "khajoorein", urdu: "کھجوریں", english: "dates", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "khajooron", urdu: "کھجوروں", english: "of dates", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/khajoor.webp", riddles: { english: "Sweet and brown, often at iftar,\nA tiny fruit loved near and far.", romanUrdu: "Bhuri meethi chhoti si cheez,\nIftar mein milti bari azeez.", urdu: "بھوری میٹھی چھوٹی سی چیز،\nافطار میں ملتی بڑی عزیز۔", }, },{id: "khamosh", word: { baseRomanUrdu: "khamosh", baseUrdu: "خاموش", english: "quiet", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/khamosh.webp", riddles: { english: "No loud sound, no noisy cheer,\nPeaceful moments settle here.", romanUrdu: "Shor na ho, awaaz thami,\nSukoon ki ho pyari ghari.", urdu: "شور نہ ہو، آواز تھمی،\nسکون کی ہو پیاری گھڑی۔", }, },{id: "khamoshi", word: { baseRomanUrdu: "khamoshi", baseUrdu: "خاموشی", english: "silence", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/khamoshi.webp", riddles: { english: "No talking, no music, not a sound,\nOnly stillness all around.", romanUrdu: "Na baat, na gaana, na koi awaaz,\nSirf sukoon ka hai yeh andaaz.", urdu: "نہ بات، نہ گانا، نہ کوئی آواز،\nصرف سکون کا ہے یہ انداز۔", }, },{id: "khara", word: { baseRomanUrdu: "khara", baseUrdu: "کھڑا", english: "standing", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "khari", urdu: "کھڑی", english: "standing", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "kharay", urdu: "کھڑے", english: "standing plural", gender: "masculine", number: "plural", form: "plural form", }], image: "/qr/assets/images/khara.webp", riddles: { english: "Feet stay firm, body is tall,\nNot sitting down at all.", romanUrdu: "Paon zameen par, badan seedha,\nNa baitha hua, na leeta.", urdu: "پاؤں زمین پر، بدن سیدھا،\nنہ بیٹھا ہوا، نہ لیٹا۔", }, },{id: "khareedna", word: { baseRomanUrdu: "khareedna", baseUrdu: "خریدنا", english: "buy", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "khareeda", urdu: "خریدا", english: "bought", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "khareedi", urdu: "خریدی", english: "bought", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "khareedni", urdu: "خریدنی", english: "to buy", gender: "feminine", number: "singular", form: "infinitive", }, { romanUrdu: "khareedo", urdu: "خریدو", english: "buy", gender: null, number: null, form: "command", }], image: "/qr/assets/images/khareedna.webp", riddles: { english: "At the shop, you pay and say,\n\"I'll take this home with me today.\"", romanUrdu: "Dukaan pe paise de kar aao,\nPasand ki cheez ghar le jao.", urdu: "دکان پہ پیسے دے کر آؤ،\nپسند کی چیز گھر لے جاؤ۔", }, },
{id: "khat", word: { baseRomanUrdu: "khat", baseUrdu: "خط", english: "letter", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "khaton", urdu: "خطوں", english: "of letters", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/khat.webp", riddles: { english: "Written by hand and folded with care,\nI carry your words from here to there.", romanUrdu: "Haath se likha, tah kar ke bheja,\nDoor tak dil ka paighaam pohanchaya.", urdu: "ہاتھ سے لکھا، تہہ کر کے بھیجا،\nدور تک دل کا پیغام پہنچایا۔", }, },{id: "khayal", word: { baseRomanUrdu: "khayal", baseUrdu: "خیال", english: "care/thought", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "khayalon", urdu: "خیالوں", english: "care/thought", gender: null, number: "plural", form: "plural oblique", }, { romanUrdu: "khayal rakhna", urdu: "خیال رکھنا", english: "to take care", gender: null, number: null, form: "phrase", }], image: "/qr/assets/images/khayal.webp", riddles: { english: "A thought in mind or care in heart,\nIt can make kindness start.", romanUrdu: "Dimagh ki baat ya dil ki parwah,\nIs se banti achi raah.", urdu: "دماغ کی بات یا دل کی پرواہ،\nاس سے بنتی اچھی راہ۔", }, },{id: "kheenchna", word: { baseRomanUrdu: "kheenchna", baseUrdu: "کھینچنا", english: "pull", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "kheencha", urdu: "کھینچا", english: "pulled", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "kheenchi", urdu: "کھینچی", english: "pulled", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "kheenchay", urdu: "کھینچے", english: "pulled", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "kheencho", urdu: "کھینچو", english: "pull", gender: null, number: null, form: "command", }, { romanUrdu: "kheench raha", urdu: "کھینچ رہا", english: "is pulling", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "kheench rahi", urdu: "کھینچ رہی", english: "is pulling", gender: "feminine", number: "singular", form: "continuous", }], image: "/qr/assets/images/kheenchna.webp", riddles: { english: "Not a push, the other way,\nBring it closer, tug away!", romanUrdu: "Dhakka nahi, ulta kaam,\nApni taraf laao tamaam.", urdu: "دھکا نہیں، الٹا کام،\nاپنی طرف لاؤ تمام۔", }, },
{id: "khel", word: { baseRomanUrdu: "khel", baseUrdu: "کھیل", english: "game", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/khel.webp", riddles: { english: "Rules and turns make fun begin,\nEveryone tries their best to win.", romanUrdu: "Baari aaye, qawaid chalein,\nSab mil kar khushi se khelen.", urdu: "باری آئے، قواعد چلیں،\nسب مل کر خوشی سے کھیلیں۔", }, },{id: "khelna", word: { baseRomanUrdu: "khelna", baseUrdu: "کھیلنا", english: "play", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "khela", urdu: "کھیلا", english: "played", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "kheli", urdu: "کھیلی", english: "played", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "khele", urdu: "کھیلے", english: "played", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/khelna.webp", riddles: { english: "Run, laugh, take turns, and try,\nFun can make the time fly.", romanUrdu: "Daudo, hanso, baari nibhao,\nMazay se waqt guzar jao.", urdu: "دوڑو، ہنسو، باری نبھاؤ،\nمزے سے وقت گزر جاؤ۔", }, },{id: "khet", word: { baseRomanUrdu: "khet", baseUrdu: "کھیت", english: "field", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "kheton", urdu: "کھیتوں", english: "fields / of fields", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/khet.webp", riddles: { english: "Seeds grow here under the sky,\nGreen plants wave as winds pass by.", romanUrdu: "Beej yahan zameen mein boye jayein,\nSabz poday hawa mein lehrayein.", urdu: "بیج یہاں زمین میں بوئے جائیں،\nسبز پودے ہوا میں لہرائیں۔", }, },{id: "khilana", word: { baseRomanUrdu: "khilana", baseUrdu: "کھلانا", english: "feed", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "khilaya", urdu: "کھلایا", english: "fed", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "khilayi", urdu: "کھلائی", english: "fed", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "khilaye", urdu: "کھلائے", english: "fed", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/khilana.webp", riddles: { english: "You give food with loving care,\nSomeone eats what you prepare.", romanUrdu: "Pyar se khana aage karo,\nDoosre ka pait bhar do.", urdu: "پیار سے کھانا آگے کرو،\nدوسرے کا پیٹ بھر دو۔", }, },{id: "khirki", word: { baseRomanUrdu: "khirki", baseUrdu: "کھڑکی", english: "window", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "khirkiyan", urdu: "کھڑکیاں", english: "windows", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "khirkiyon", urdu: "کھڑکیوں", english: "of windows", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/khirki.webp", riddles: { english: "Open me to see outside,\nLight and breeze can come inside.", romanUrdu: "Mujh se bahar ka manzar aaye,\nRoshni aur thandi hawa bhi aaye.", urdu: "مجھ سے باہر کا منظر آئے،\nروشنی اور ٹھنڈی ہوا بھی آئے۔", }, },{id: "kholna", word: { baseRomanUrdu: "kholna", baseUrdu: "کھولنا", english: "open", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "khola", urdu: "کھولا", english: "opened", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "kholi", urdu: "کھولی", english: "opened", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "kholay", urdu: "کھولے", english: "opened", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "kholo", urdu: "کھولو", english: "open", gender: null, number: null, form: "command", }], image: "/qr/assets/images/kholna.webp", riddles: { english: "Turn the lock or lift the lid,\nSee what is inside, once hid.", romanUrdu: "Tala ghumao ya dhakkan hatao,\nAndar ki cheez samne lao.", urdu: "تالا گھماؤ یا ڈھکن ہٹاؤ،\nاندر کی چیز سامنے لاؤ۔", }, },{id: "khoobsurat", word: { baseRomanUrdu: "khoobsurat", baseUrdu: "خوبصورت", english: "beautiful", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/khoobsurat.webp", riddles: { english: "Your eyes enjoy what they see,\nLovely colors make hearts agree.", romanUrdu: "Nazar ko achha lagta manzar,\nDil keh de kitna pyara andar.", urdu: "نظر کو اچھا لگتا منظر،\nدل کہہ دے کتنا پیارا اندر۔", }, },{id: "khurdura", word: { baseRomanUrdu: "khurdura", baseUrdu: "کھردرا", english: "rough", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "khurduri", urdu: "کھردری", english: "rough", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "khurduray", urdu: "کھردرے", english: "rough", gender: "masculine", number: "plural", form: "plural / oblique form", }], image: "/qr/assets/images/khurdura.webp", riddles: { english: "Touch the bark of an old tree,\nNot soft at all, that's what I'll be!", romanUrdu: "Purane darakht ki chhaal chhoo lo,\nNaram nahi, yeh baat na bhoolo.", urdu: "پرانے درخت کی چھال چھو لو،\nنرم نہیں، یہ بات نہ بھولو۔", }, },
{id: "khush", word: { baseRomanUrdu: "khush", baseUrdu: "خوش", english: "happy", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/khush.webp", riddles: { english: "A bright feeling fills your face,\nSadness leaves without a trace.", romanUrdu: "Dil halka, chehra roshan ho,\nGham ka saya door kahin ho.", urdu: "دل ہلکا، چہرہ روشن ہو،\nغم کا سایہ دور کہیں ہو۔", }, },{id: "khushboo", word: { baseRomanUrdu: "khushboo", baseUrdu: "خوشبو", english: "scent", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "khushbooein", urdu: "خوشبوئیں", english: "fragrances", gender: "feminine", number: "plural", form: "plural", }], image: "/qr/assets/images/khushboo.webp", riddles: { english: "You know I am near through your nose,\nFrom food or flowers, softly I rose.", romanUrdu: "Naak bataye main paas hoon,\nPhool ya khanay se mehsoos hoon.", urdu: "ناک بتائے میں پاس ہوں،\nپھول یا کھانے سے محسوس ہوں۔", }, },{id: "khushi", word: { baseRomanUrdu: "khushi", baseUrdu: "خوشی", english: "happiness", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "khushiyan", urdu: "خوشیاں", english: "happy moments", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "khushiyon", urdu: "خوشیوں", english: "of happy moments", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/khush.webp", riddles: { english: "A warm feeling lights the heart,\nSmiles and laughter often start.", romanUrdu: "Dil mein roshni si aa jaye,\nChehra apne aap khil jaye.", urdu: "دل میں روشنی سی آ جائے،\nچہرہ اپنے آپ کھل جائے۔", }, },{id: "kinaara", word: { baseRomanUrdu: "kinaara", baseUrdu: "کنارا", english: "edge", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "kinaare", urdu: "کنارے", english: "edge", gender: "masculine", number: "singular", form: "oblique", }, { romanUrdu: "kinaaron", urdu: "کناروں", english: "edges", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/kinaara.webp", riddles: { english: "Where a table or a road must end,\nThat is where you'll find me, friend.", romanUrdu: "Jahan cheez khatam ho jaaye,\nWahin mera naam aa jaaye.", urdu: "جہاں چیز ختم ہو جائے،\nوہیں میرا نام آ جائے۔", }, },
{id: "kitaab", word: { baseRomanUrdu: "kitaab", baseUrdu: "کتاب", english: "book", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "kitaabein", urdu: "کتابیں", english: "books", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "kitaabon", urdu: "کتابوں", english: "of books", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/kitaab.webp", riddles: { english: "I have pages, words and more,\nOpen me up to learn and explore.", romanUrdu: "Safhe mere, lafz hazaar,\nKholo mujhe, seekho har baar.", urdu: "صفحے میرے، لفظ ہزار،\nکھولو مجھے، سیکھو ہر بار۔", }, },{id: "laal", word: { baseRomanUrdu: "laal", baseUrdu: "لال", english: "red", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/laal.webp", riddles: { english: "A bright color, bold and deep,\nLike roses, apples, or a jeep.", romanUrdu: "Gehra rang jo door se chamke,\nPhool aur seb mein bhi damke.", urdu: "گہرا رنگ جو دور سے چمکے،\nپھول اور سیب میں بھی دمکے۔", }, },{id: "laaltain", word: { baseRomanUrdu: "laaltain", baseUrdu: "لالٹین", english: "lantern", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "laaltainein", urdu: "لالٹینیں", english: "lanterns", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "laaltainon", urdu: "لالٹینوں", english: "of lanterns", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/laaltain.webp", riddles: { english: "Carry me by my handle at night,\nMy little flame gives you light.", romanUrdu: "Haath mein pakro raat ke waqt,\nMeri lau de roshni har waqt.", urdu: "ہاتھ میں پکڑو رات کے وقت،\nمیری لو دے روشنی ہر وقت۔", }, },{id: "laat", word: { baseRomanUrdu: "laat", baseUrdu: "لات", english: "kick", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "laatein", urdu: "لاتیں", english: "kicks", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "laaton", urdu: "لاتوں", english: "kicks", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/laat.webp", riddles: { english: "A foot moves fast with a little flick,\nIn games or anger, it makes a quick hit.", romanUrdu: "Paon chale zor se, foran lagey thokar,\nKhel mein ho to ban jaye chhota sa jhatka.", urdu: "پاؤں چلے زور سے، فوراً لگے ٹھوکر،\nکھیل میں ہو تو بن جائے چھوٹا سا جھٹکا۔", }, },{id: "lafz", word: { baseRomanUrdu: "lafz", baseUrdu: "لفظ", english: "word", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "lafzon", urdu: "لفظوں", english: "words", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/lafz.webp", riddles: { english: "Letters join and make me whole,\nI carry meaning, thought, and soul.", romanUrdu: "Harf milein to ban jaun,\nMatlab dil tak pohanchaun.", urdu: "حرف ملیں تو بن جاؤں،\nمطلب دل تک پہنچاؤں۔", }, },{id: "lagana", word: { baseRomanUrdu: "lagana", baseUrdu: "لگانا", english: "apply", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "lagaya", urdu: "لگایا", english: "applied", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "lagayi", urdu: "لگائی", english: "applied", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "lagaye", urdu: "لگائے", english: "applied", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/lagana.webp", riddles: { english: "Put something on with careful care,\nPaint, henna, stickers — here or there.", romanUrdu: "Aahista se cheez chadhayein,\nMehndi ya rang ko sajaayein.", urdu: "آہستہ سے چیز چڑھائیں،\nمہندی یا رنگ کو سجائیں۔", }, },{id: "lagbhag", word: { baseRomanUrdu: "lagbhag", baseUrdu: "لگ بھگ", english: "about", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/lagbhag.webp", riddles: { english: "Not exact, but close enough,\nA guess when counting gets tough.", romanUrdu: "Bilkul sahi nahi, qareeb qareeb,\nAndaza ho to baat ajeeb.", urdu: "بالکل صحیح نہیں، قریب قریب،\nاندازہ ہو تو بات عجیب۔", }, },{id: "lagna", word: { baseRomanUrdu: "lagna", baseUrdu: "لگنا", english: "seem/feel", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "laga", urdu: "لگا", english: "seemed/felt", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "lagi", urdu: "لگی", english: "seemed/felt", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "lage", urdu: "لگے", english: "seemed/felt", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "lag raha", urdu: "لگ رہا", english: "is seeming/feeling", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "lag rahi", urdu: "لگ رہی", english: "is seeming/feeling", gender: "feminine", number: "singular", form: "continuous", }, { romanUrdu: "lag gaya", urdu: "لگ گیا", english: "got applied/started", gender: "masculine", number: "singular", form: "past compound", }, { romanUrdu: "lag gayi", urdu: "لگ گئی", english: "got applied/started", gender: "feminine", number: "singular", form: "past compound", }], image: "/qr/assets/images/lagna.webp", riddles: { english: "It tells how something feels to you, maybe right, strange, or new.", romanUrdu: "Cheez kaisi mehsoos ho, yeh baat dil ko bata de jo.", urdu: "چیز کیسی محسوس ہو، یہ بات دل کو بتا دے جو۔", }, },{id: "lakri", word: { baseRomanUrdu: "lakri", baseUrdu: "لکڑی", english: "wood", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "lakriyan", urdu: "لکڑیاں", english: "pieces of wood", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "lakriyon", urdu: "لکڑیوں", english: "pieces of wood", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/lakri.webp", riddles: { english: "I come from trees, so strong and brown,\nDoors and tables from me are found.", romanUrdu: "Darakht se aaun, bhoori mazboot,\nMujh se banay darwaze aur sandook.", urdu: "درخت سے آؤں، بھوری مضبوط،\nمجھ سے بنے دروازے اور صندوق۔", }, },{id: "lana", word: { baseRomanUrdu: "lana", baseUrdu: "لانا", english: "bring", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "laya", urdu: "لایا", english: "brought", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "layi", urdu: "لائی", english: "brought", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "laye", urdu: "لائے", english: "brought", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "lao", urdu: "لاؤ", english: "bring", gender: null, number: null, form: "command", }, { romanUrdu: "la kar", urdu: "لا کر", english: "bringing / after bringing", gender: null, number: null, form: "compound", }], image: "/qr/assets/images/lana.webp", riddles: { english: "You go away and come back near, carrying something over here.", romanUrdu: "Door se cheez utha kar lao, apnon ke paas le aao.", urdu: "دور سے چیز اٹھا کر لاؤ، اپنوں کے پاس لے آؤ۔", }, },{id: "lapetay", word: { baseRomanUrdu: "lapetay", baseUrdu: "لپیٹے", english: "wrapped", pos: "phrase", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "lapetna", urdu: "لپیٹنا", english: "to wrap", gender: null, number: null, form: "infinitive", }, { romanUrdu: "lapeta", urdu: "لپیٹا", english: "wrapped", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "lapeti", urdu: "لپیٹی", english: "wrapped", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "lapetain", urdu: "لپیٹیں", english: "wrapped plural/command", gender: null, number: "plural", form: "command", }], image: "/qr/assets/images/lapetay.webp", riddles: { english: "Covered around from side to side,\nSomething sits tucked safe inside.", romanUrdu: "Idhar udhar se dhaank diya jaye,\nAndar cheez mehfooz ban jaye.", urdu: "ادھر ادھر سے ڈھانک دیا جائے،\nاندر چیز محفوظ بن جائے۔", }, },{id: "larai", word: { baseRomanUrdu: "larai", baseUrdu: "لڑائی", english: "fight", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "laraiyan", urdu: "لڑائیاں", english: "fight", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "laraiyon", urdu: "لڑائیوں", english: "fight", gender: null, number: "plural", form: "plural oblique", }], image: "/qr/assets/images/larai.webp", riddles: { english: "Angry words or pushing too,\nIt happens when peace is not with you.", romanUrdu: "Jab baat bigar kar takra jaye,\nSukoon door kahin chala jaye.", urdu: "جب بات بگڑ کر ٹکرا جائے،\nسکون دور کہیں چلا جائے۔", }, },{id: "lassi", word: { baseRomanUrdu: "lassi", baseUrdu: "لسی", english: "yogurt drink", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/lassi.webp", riddles: { english: "Cool and creamy in a glass,\nA desi drink for summer days.", romanUrdu: "Thandi malai jaisi pyali,\nGarmi mein lage sab se nirali.", urdu: "ٹھنڈی ملائی جیسی پیالی،\nگرمی میں لگے سب سے نرالی۔", }, },{id: "latkana", word: { baseRomanUrdu: "latkana", baseUrdu: "لٹکانا", english: "hang", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "latkaya", urdu: "لٹکایا", english: "hung", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "latkayi", urdu: "لٹکائی", english: "hung", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "latkaye", urdu: "لٹکائے", english: "hung", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/latkana.webp", riddles: { english: "From a hook or rope I stay,\nNot on the floor, but up away.", romanUrdu: "Kundi ya rassi se tik jaun,\nNeeche na girun, upar latkaun.", urdu: "کنڈی یا رسی سے ٹک جاؤں،\nنیچے نہ گروں، اوپر لٹکاؤں۔", }, },{id: "le_jaana", word: { baseRomanUrdu: "le jaana", baseUrdu: "لے جانا", english: "take along", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "le gaya", urdu: "لے گیا", english: "took along", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "le gayi", urdu: "لے گئی", english: "took along", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "le gaye", urdu: "لے گئے", english: "took along", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "le jao", urdu: "لے جاؤ", english: "take along", gender: null, number: null, form: "command", }, { romanUrdu: "le ja", urdu: "لے جا", english: "take along", gender: null, number: null, form: "command (stem)", }], image: "/qr/assets/images/le_jaana.webp", riddles: { english: "Take something with you as you leave,\nCarry it along with care and ease.", romanUrdu: "Saath utha kar chalna ho,\nCheez ko apne sang rakhna ho.", urdu: "ساتھ اٹھا کر چلنا ہو،\nچیز کو اپنے سنگ رکھنا ہو۔", }, },{id: "lehja", word: { baseRomanUrdu: "lehja", baseUrdu: "لہجہ", english: "accent / tone", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "lehjay", urdu: "لہجے", english: "accents / accent oblique", gender: "masculine", number: "plural", form: "plural / oblique", }], image: "/qr/assets/images/lehja.webp", riddles: { english: "Not the words but how they sound,\nIn every voice I can be found.", romanUrdu: "Lafz nahi, andaaz hoon main,\nHar awaaz ka raaz hoon main.", urdu: "لفظ نہیں، انداز ہوں میں،\nہر آواز کا راز ہوں میں۔", }, },{id: "lena", word: { baseRomanUrdu: "lena", baseUrdu: "لینا", english: "take", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "liya", urdu: "لیا", english: "took", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "li", urdu: "لی", english: "took", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "liye", urdu: "لیے", english: "took", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/lena.webp", riddles: { english: "Reach your hand and bring it near,\nNow the thing is yours right here.", romanUrdu: "Haath barhao, cheez paas lao,\nApne saath us ko le jao.", urdu: "ہاتھ بڑھاؤ، چیز پاس لاؤ،\nاپنے ساتھ اس کو لے جاؤ۔", }, },{id: "likhna", word: { baseRomanUrdu: "likhna", baseUrdu: "لکھنا", english: "write", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "likha", urdu: "لکھا", english: "wrote", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "likhi", urdu: "لکھی", english: "wrote", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "likhay", urdu: "لکھے", english: "wrote", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "likho", urdu: "لکھو", english: "write!", gender: null, number: null, form: "command", }], image: "/qr/assets/images/likhna.webp", riddles: { english: "Letters flow from hand to page,\nWords are saved at any age.", romanUrdu: "Haath se harf kagaz par aayein,\nBaat ko mehfooz banayein.", urdu: "ہاتھ سے حرف کاغذ پر آئیں،\nبات کو محفوظ بنائیں۔", }, },{id: "log", word: { baseRomanUrdu: "log", baseUrdu: "لوگ", english: "people", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "logon", urdu: "لوگوں", english: "people / of people", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/log.webp", riddles: { english: "Many persons gathered there,\nFaces, voices everywhere.", romanUrdu: "Bahut se chehre aik jagah aayein,\nAwaazein mil kar sunai dein.", urdu: "بہت سے چہرے ایک جگہ آئیں،\nآوازیں مل کر سنائی دیں۔", }, },{id: "maan", word: { baseRomanUrdu: "maan", baseUrdu: "مان", english: "accept", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "mana", urdu: "مانا", english: "accepted", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "mani", urdu: "مانی", english: "accepted", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "mane", urdu: "مانے", english: "accepted", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/maan.webp", riddles: { english: "You agree and say okay,\nA stubborn no can move away.", romanUrdu: "Dil razi ho, haan keh do,\nInkaar ko halka sa rehne do.", urdu: "دل راضی ہو، ہاں کہہ دو،\nانکار کو ہلکا سا رہنے دو۔", }, },{id: "maarna", word: { baseRomanUrdu: "maarna", baseUrdu: "مارنا", english: "hit", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "mara", urdu: "مارا", english: "hit", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "maari", urdu: "ماری", english: "hit", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "maare", urdu: "مارے", english: "hit", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/maarna.webp", riddles: { english: "A hand or thing strikes with force,\nBetter choose a gentle course.", romanUrdu: "Zor se koi cheez lage,\nBehtar hai narmi saath chale.", urdu: "زور سے کوئی چیز لگے،\nبہتر ہے نرمی ساتھ چلے۔", }, },{id: "maatha", word: { baseRomanUrdu: "maatha", baseUrdu: "ماتھا", english: "forehead", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "maathay", urdu: "ماتھے", english: "foreheads", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/maatha.webp", riddles: { english: "Above the eyes, below the hair,\nA kiss or mark can rest right there.", romanUrdu: "Aankhon ke upar jagah yeh aaye,\nPyar ka bosa yahin lag jaye.", urdu: "آنکھوں کے اوپر جگہ یہ آئے،\nپیار کا بوسہ یہیں لگ جائے۔", }, },{id: "madad", word: { baseRomanUrdu: "madad", baseUrdu: "مدد", english: "help", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/madad.webp", riddles: { english: "When someone struggles, you step near,\nKind hands can remove their fear.", romanUrdu: "Mushkil mein koi saath aa jaye,\nNarmi se rasta dikhlaye.", urdu: "مشکل میں کوئی ساتھ آ جائے،\nنرمی سے راستہ دکھلائے۔", }, },{id: "maheena", word: { baseRomanUrdu: "maheena", baseUrdu: "مہینہ", english: "month", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "maheenay", urdu: "مہینے", english: "months", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "maheenon", urdu: "مہینوں", english: "of months", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/maheena.webp", riddles: { english: "Weeks join hands and time moves on,\nNew dates come from dusk to dawn.", romanUrdu: "Haftay mil kar waqt banayein,\nCalendar ke panne badalte jayein.", urdu: "ہفتے مل کر وقت بنائیں،\nکیلنڈر کے پنے بدلتے جائیں۔", }, },{id: "manana", word: { baseRomanUrdu: "manana", baseUrdu: "منانا", english: "persuade", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "manaya", urdu: "منایا", english: "persuaded", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "manayi", urdu: "منائی", english: "persuaded", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "manaye", urdu: "منائے", english: "persuaded", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/manana.webp", riddles: { english: "Soft words help a heart agree,\nA no may turn to yes gently.", romanUrdu: "Narm alfaaz dil ko manayein,\nNa ko haan mein badal jayein.", urdu: "نرم الفاظ دل کو منائیں،\nنہ کو ہاں میں بدل جائیں۔", }, },{id: "mandi", word: { baseRomanUrdu: "mandi", baseUrdu: "منڈی", english: "market", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "mandiyan", urdu: "منڈیاں", english: "market", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "mandiyon", urdu: "منڈیوں", english: "market", gender: null, number: "plural", form: "plural oblique", }], image: "/qr/assets/images/mandi.webp", riddles: { english: "A busy place where people buy,\nAnimals or fruit piled high.", romanUrdu: "Bheed bhara bazaar sa ho,\nKharidari ka kaam yahan ho.", urdu: "بھیڑ بھرا بازار سا ہو،\nخریداری کا کام یہاں ہو۔", }, },{id: "matar", word: { baseRomanUrdu: "matar", baseUrdu: "مٹر", english: "peas", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/matar.webp", riddles: { english: "Small green pearls in a pod so neat,\nIn rice or curry, I taste sweet.", romanUrdu: "Chhote harey moti, chilkay mein chupay,\nChawal ya salan mein maze se pakay.", urdu: "چھوٹے ہرے موتی، چھلکے میں چھپے،\nچاول یا سالن میں مزے سے پکے۔", }, },{id: "mausam", word: { baseRomanUrdu: "mausam", baseUrdu: "موسم", english: "weather", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/mausam.webp", riddles: { english: "Rain, sun, clouds, or breeze,\nI tell what the sky will be.", romanUrdu: "Dhoop, badal, barish, hawa,\nAasman ka haal bataun sada.", urdu: "دھوپ، بادل، بارش، ہوا،\nآسمان کا حال بتاؤں سدا۔", }, },{id: "mazboot", word: { baseRomanUrdu: "mazboot", baseUrdu: "مضبوط", english: "strong", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/mazboot.webp", riddles: { english: "I do not break, I do not bend,\nOn me you always can depend.", romanUrdu: "Na tootoon, na jhukoon kabhi,\nMujh pe bharosa karein sabhi.", urdu: "نہ ٹوٹوں، نہ جھکوں کبھی،\nمجھ پہ بھروسا کریں سبھی۔", }, },
{id: "meetha", word: { baseRomanUrdu: "meetha", baseUrdu: "میٹھا", english: "sweet", pos: "adjective", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "meethi", urdu: "میٹھی", english: "sweet", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "meethay", urdu: "میٹھے", english: "sweet plural", gender: "masculine", number: "plural", form: "masculine plural", }, { romanUrdu: "meethiyan", urdu: "میٹھیاں", english: "sweet", gender: "feminine", number: "plural", form: "feminine plural", }], image: "/qr/assets/images/meetha.webp", riddles: { english: "Sugar-like taste on your tongue,\nDesserts and fruit can feel this fun.", romanUrdu: "Zubaan par shakkar jaisa aaye,\nMithai aur phal yaad dilaye.", urdu: "زبان پر شکر جیسا آئے،\nمٹھائی اور پھل یاد دلائے۔", }, },{id: "mehak", word: { baseRomanUrdu: "mehak", baseUrdu: "مہک", english: "fragrance", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/mehak.webp", riddles: { english: "A gentle smell floats through air,\nFood or flowers may be there.", romanUrdu: "Narm si boo hawa mein aaye,\nPhool ya khana yaad dilaye.", urdu: "نرم سی بو ہوا میں آئے،\nپھول یا کھانا یاد دلائے۔", }, },{id: "mehmaan", word: { baseRomanUrdu: "mehmaan", baseUrdu: "مہمان", english: "guest", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "mehmaanon", urdu: "مہمانوں", english: "guests", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/mehmaan.webp", riddles: { english: "I visit your home and you treat me well,\nI drink some chai, then say farewell.", romanUrdu: "Ghar mein aaun, izzat paaun,\nChai pi kar wapas jaaun.", urdu: "گھر میں آؤں، عزت پاؤں،\nچائے پی کر واپس جاؤں۔", }, },
{id: "mehndi", word: { baseRomanUrdu: "mehndi", baseUrdu: "مہندی", english: "henna", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/mehndi.webp", riddles: { english: "On hands it makes leafy art,\nChaand Raat joy can start.", romanUrdu: "Haathon par naqsh banaye,\nChaand Raat ko aur sajaye.", urdu: "ہاتھوں پر نقش بنائے،\nچاند رات کو اور سجائے۔", }, },{id: "mithai", word: { baseRomanUrdu: "mithai", baseUrdu: "مٹھائی", english: "sweets", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "mithaiyan", urdu: "مٹھائیاں", english: "sweets", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "mithaiyon", urdu: "مٹھائیوں", english: "of sweets", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/mithai.webp", riddles: { english: "Small treats, sugary and bright,\nShared with guests on a happy night.", romanUrdu: "Chhoti meethi cheezen aati,\nMehmanon ko khushi dilati.", urdu: "چھوٹی میٹھی چیزیں آتیں،\nمہمانوں کو خوشی دلاتیں۔", }, },{id: "mithas", word: { baseRomanUrdu: "mithas", baseUrdu: "مٹھاس", english: "sweetness", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/mithas.webp", riddles: { english: "Sugar-like taste, soft and nice,\nFound in mango, kheer, and rice.", romanUrdu: "Cheeni jaisa zayqa pyara,\nAam aur kheer mein lage nyara.", urdu: "چینی جیسا ذائقہ پیارا،\nآم اور کھیر میں لگے نیارا۔", }, },{id: "mohalla", word: { baseRomanUrdu: "mohalla", baseUrdu: "محلہ", english: "neighborhood", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "mohallay", urdu: "محلے", english: "neighborhoods", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "mohallon", urdu: "محلوں", english: "of neighborhoods", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/mohalla.webp", riddles: { english: "Homes sit close, people know each name,\nNeighbors share the everyday game.", romanUrdu: "Ghar qareeb aur log pehchane,\nPadosi mil kar din guzarein.", urdu: "گھر قریب اور لوگ پہچانے،\nپڑوسی مل کر دن گزاریں۔", }, },{id: "mubarak", word: { baseRomanUrdu: "mubarak", baseUrdu: "مبارک", english: "blessed", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/mubarak.webp", riddles: { english: "A good wish on a happy day,\nKind words people love to say.", romanUrdu: "Khushi ke din pyari si baat,\nLog kehte pyaar ke saath.", urdu: "خوشی کے دن پیاری سی بات،\nلوگ کہتے پیار کے ساتھ۔", }, },{id: "munh", word: { baseRomanUrdu: "munh", baseUrdu: "منہ", english: "mouth", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/munh.webp", riddles: { english: "You eat and talk and smile with me,\nRight below your nose I'll be.", romanUrdu: "Khana khao, baat karo, muskurao,\nNaak ke neeche mujhe pao.", urdu: "کھانا کھاؤ، بات کرو، مسکراؤ،\nناک کے نیچے مجھے پاؤ۔", }, },{id: "muskurana", word: { baseRomanUrdu: "muskurana", baseUrdu: "مسکرانا", english: "smile", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "muskuraya", urdu: "مسکرایا", english: "smiled", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "muskurayi", urdu: "مسکرائی", english: "smiled", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "muskuraye", urdu: "مسکرائے", english: "smiled", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "muskura", urdu: "مسکرا", english: "smile", gender: null, number: null, form: "command (stem)", }, { romanUrdu: "muskurao", urdu: "مسکراؤ", english: "smile", gender: null, number: null, form: "command", }, { romanUrdu: "muskurahat", urdu: "مسکراہٹ", english: "smile", gender: "feminine", number: "singular", form: "noun form", }], image: "/qr/assets/images/muskurana.webp", riddles: { english: "A happy face, so warm and bright,\nIt shows your joy in gentle light.", romanUrdu: "Chehra halka sa khil jaye,\nDil ki roshni nazar aa jaye.", urdu: "چہرہ ہلکا سا کھل جائے،\nدل کی روشنی نظر آ جائے۔", }, },{id: "naak", word: { baseRomanUrdu: "naak", baseUrdu: "ناک", english: "nose", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/naak.webp", riddles: { english: "In the middle of your face it stays,\nIt helps you smell in many ways.", romanUrdu: "Chehre ke beech yeh jagah banaye,\nKhushboo aur boo dono bataye.", urdu: "چہرے کے بیچ یہ جگہ بنائے،\nخوشبو اور بو دونوں بتائے۔", }, },{id: "naam", word: { baseRomanUrdu: "naam", baseUrdu: "نام", english: "name", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "naamon", urdu: "ناموں", english: "name", gender: null, number: "plural", form: "plural oblique", }], image: "/qr/assets/images/naam.webp", riddles: { english: "What people call you every day,\nIt helps them know just what to say.", romanUrdu: "Log tumhein jis se bulayein,\nPehchan tumhari sab ko batayein.", urdu: "لوگ تمہیں جس سے بلائیں،\nپہچان تمہاری سب کو بتائیں۔", }, },{id: "naghma", word: { baseRomanUrdu: "naghma", baseUrdu: "نغمہ", english: "song", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "naghmay", urdu: "نغمے", english: "songs", gender: "masculine", number: "plural", form: "plural / oblique", }, ], image: "/qr/assets/images/naghma.webp", riddles: { english: "Sweet words that float on air,\nA melody for all to share.", romanUrdu: "Meethay bol hawa mein aayen,\nSur mil kar dil ko bhayen.", urdu: "میٹھے بول ہوا میں آئیں،\nسر مل کر دل کو بھائیں۔", }, },{id: "namaaz", word: { baseRomanUrdu: "namaaz", baseUrdu: "نماز", english: "prayer", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "namaazein", urdu: "نمازیں", english: "prayers", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "namaazon", urdu: "نمازوں", english: "of prayers", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/namaaz.webp", riddles: { english: "A quiet time to stand and bow,\nHearts feel close and peaceful now.", romanUrdu: "Sukoon se kharay ho kar jhukna,\nDil ko Rab ke paas samajhna.", urdu: "سکون سے کھڑے ہو کر جھکنا،\nدل کو رب کے پاس سمجھنا۔", }, },{id: "nami", word: { baseRomanUrdu: "nami", baseUrdu: "نمی", english: "humidity", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/nami.webp", riddles: { english: "You feel me in sticky air, not quite rain but I am there.", romanUrdu: "Chipchipi hawa mein mehsoos hoon, baarish nahi magar paas hoon.", urdu: "چپچپی ہوا میں محسوس ہوں، بارش نہیں مگر پاس ہوں۔", }, },{id: "narangi", word: { baseRomanUrdu: "narangi", baseUrdu: "نارنگی", english: "orange", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "narangiyan", urdu: "نارنگیاں", english: "oranges", gender: "feminine", number: "plural", form: "plural", }], image: "/qr/assets/images/narangi.webp", riddles: { english: "Round and bright with citrus cheer,\nPeel me and my slices appear.", romanUrdu: "Gol si phal, chilka utaro,\nQatre qatre mazay se khao.", urdu: "گول سا پھل، چھلکا اتارو،\nقاش قاش مزے سے کھاؤ۔", }, },{id: "narm", word: { baseRomanUrdu: "narm", baseUrdu: "نرم", english: "soft/gentle", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/narm.webp", riddles: { english: "Soft to touch and kind in feel,\nLike a gentle hand that helps you heal.", romanUrdu: "Chhoone mein halka, dil ko bhaye,\nPyar bhara andaaz dikhaye.", urdu: "چھونے میں ہلکا، دل کو بھائے،\nپیار بھرا انداز دکھائے۔", }, },{id: "narmi", word: { baseRomanUrdu: "narmi", baseUrdu: "نرمی", english: "gentleness", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/narmi.webp", riddles: { english: "A gentle way, calm and mild,\nKind like hands with a little child.", romanUrdu: "Halka pyara andaaz ho,\nSakhti se bilkul door raaz ho.", urdu: "ہلکا پیارا انداز ہو،\nسختی سے بالکل دور راز ہو۔", }, },{id: "naya", word: { baseRomanUrdu: "naya", baseUrdu: "نیا", english: "new", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "nayi", urdu: "نئی", english: "new", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "naye", urdu: "نئے", english: "new", gender: "masculine", number: "plural", form: "plural form", }], image: "/qr/assets/images/naya.webp", riddles: { english: "Used for the first time, fresh and clean,\nNot old, not worn, recently seen.", romanUrdu: "Pehli dafa istemal mein aaye,\nPurana nahi, taaza lag jaye.", urdu: "پہلی دفعہ استعمال میں آئے،\nپرانا نہیں، تازہ لگ جائے۔", }, },{id: "nazar", word: { baseRomanUrdu: "nazar", baseUrdu: "نظر", english: "sight", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "nazrein", urdu: "نظریں", english: "glances / sights", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "nazron", urdu: "نظروں", english: "of glances", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/nazar.webp", riddles: { english: "Eyes turn and something is seen,\nA glance can be quick and keen.", romanUrdu: "Aankh uthe to manzar aaye,\nChhoti si dekhai baat bataye.", urdu: "آنکھ اٹھے تو منظر آئے،\nچھوٹی سی دکھائی بات بتائے۔", }, },{id: "neeche", word: { baseRomanUrdu: "neeche", baseUrdu: "نیچے", english: "down", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/neeche.webp", riddles: { english: "Not up high, closer to the ground,\nLook below and I am found.", romanUrdu: "Upar nahi, zameen ke paas,\nDekho talay to mile ehsaas.", urdu: "اوپر نہیں، زمین کے پاس،\nدیکھو تلے تو ملے احساس۔", }, },{id: "neela", word: { baseRomanUrdu: "neela", baseUrdu: "نیلا", english: "blue", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "neeli", urdu: "نیلی", english: "blue", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "neele", urdu: "نیلے", english: "blue", gender: "masculine", number: "plural", form: "plural form", }], image: "/qr/assets/images/neela.webp", riddles: { english: "The sky wears this shade up high,\nA cool soft shade for every eye!", romanUrdu: "Aasmaan par ye rang sajta hai,\nThanda sa ehsaas dilata hai!", urdu: "آسمان پر یہ رنگ سجتا ہے،\nٹھنڈا سا احساس دلاتا ہے!", }, },{id: "neki", word: { baseRomanUrdu: "neki", baseUrdu: "نیکی", english: "good deed", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "nekiyan", urdu: "نیکیاں", english: "good deed", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "nekiyon", urdu: "نیکیوں", english: "good deed", gender: null, number: "plural", form: "plural oblique", }], image: "/qr/assets/images/neki.webp", riddles: { english: "A kind action, pure and bright,\nIt brings goodness into sight.", romanUrdu: "Acha kaam dil se ho jaye,\nAllah ki raza yaad dilaye.", urdu: "اچھا کام دل سے ہو جائے،\nاللہ کی رضا یاد دلائے۔", }, },{id: "nikaalna", word: { baseRomanUrdu: "nikaalna", baseUrdu: "نکالنا", english: "take out", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "nikaala", urdu: "نکالا", english: "took out", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "nikaali", urdu: "نکالی", english: "took out", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "nikaale", urdu: "نکالے", english: "took out", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "nikaalo", urdu: "نکالو", english: "take out", gender: null, number: null, form: "command", }], image: "/qr/assets/images/nikaalna.webp", riddles: { english: "Reach inside and bring it out,\nFrom a box or bag, no doubt.", romanUrdu: "Andar haath daal ke laao,\nThailay se bahar le aao.", urdu: "اندر ہاتھ ڈال کے لاؤ،\nتھیلے سے باہر لے آؤ۔", }, },
{id: "nikalna", word: { baseRomanUrdu: "nikalna", baseUrdu: "نکلنا", english: "leave/come out", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "nikla", urdu: "نکلا", english: "came out/left", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "nikli", urdu: "نکلی", english: "came out/left", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "niklo", urdu: "نکلو", english: "come out/leave", gender: null, number: null, form: "command", }, { romanUrdu: "niklay", urdu: "نکلے", english: "came out/left", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/nikalna.webp", riddles: { english: "From inside to outside you go, leaving one place nice and slow.", romanUrdu: "Andar se bahar qadam barhao, aik jagah se nikal jao.", urdu: "اندر سے باہر قدم بڑھاؤ، ایک جگہ سے نکل جاؤ۔", }, },{id: "nishaan", word: { baseRomanUrdu: "nishaan", baseUrdu: "نشان", english: "mark", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "nishanon", urdu: "نشانوں", english: "mark", gender: null, number: "plural", form: "plural oblique", }], image: "/qr/assets/images/nishaan.webp", riddles: { english: "A spot or sign that helps you know,\nWhere something was or where to go.", romanUrdu: "Choti si pehchan nazar aaye,\nRaasta ya baat samjha jaye.", urdu: "چھوٹی سی پہچان نظر آئے،\nراستہ یا بات سمجھا جائے۔", }, },{id: "nishani", word: { baseRomanUrdu: "nishani", baseUrdu: "نشانی", english: "sign / keepsake", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "nishaniyan", urdu: "نشانیاں", english: "signs / keepsakes", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "nishaniyon", urdu: "نشانیوں", english: "of signs / keepsakes", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/nishani.webp", riddles: { english: "A little thing that helps you know,\nOr reminds you of someone long ago.", romanUrdu: "Chhoti si cheez jo pehchan karaye,\nYa kisi apne ki yaad dilaye.", urdu: "چھوٹی سی چیز جو پہچان کرائے،\nیا کسی اپنے کی یاد دلائے۔", }, },{id: "note", word: { baseRomanUrdu: "note", baseUrdu: "نوٹ", english: "bill", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "noton", urdu: "نوٹوں", english: "bills", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/note.webp", riddles: { english: "A small paper used to pay,\nPeople keep it safe each day!", romanUrdu: "Chhota kaghaz kaam mein aaye,\nLog is se cheezen khareed laaye!", urdu: "چھوٹا کاغذ کام میں آئے،\nلوگ اس سے چیزیں خرید لائیں!", }, },{id: "ooncha", word: { baseRomanUrdu: "ooncha", baseUrdu: "اونچا", english: "high", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "oonchi", urdu: "اونچی", english: "high", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "oonchay", urdu: "اونچے", english: "high", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/ooncha.webp", riddles: { english: "Mountains, shelves, and birds can be,\nFar above where eyes can see!", romanUrdu: "Jo cheez bohat oopar jaaye,\nDekho to gardan uth jaaye!", urdu: "جو چیز بہت اوپر جائے،\nدیکھو تو گردن اٹھ جائے!", }, },{id: "paanch", word: { baseRomanUrdu: "paanch", baseUrdu: "پانچ", english: "five", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/paanch.webp", riddles: { english: "Fingers on one little hand,\nCount them slowly where you stand!", romanUrdu: "Aik haath ki ungliyan gin lo,\nItni ginti foran sun lo!", urdu: "ایک ہاتھ کی انگلیاں گن لو،\nاتنی گنتی فوراً سن لو!", }, },{id: "paas", word: { baseRomanUrdu: "paas", baseUrdu: "پاس", english: "near", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/paas.webp", riddles: { english: "Not far away, close by your side,\nEasy to reach, no need to ride!", romanUrdu: "Door nahin, bilkul qareeb,\nHaath barhao, mil jaye naseeb!", urdu: "دور نہیں، بالکل قریب،\nہاتھ بڑھاؤ، مل جائے نصیب!", }, },{id: "paaya", word: { baseRomanUrdu: "paaya", baseUrdu: "پایہ", english: "leg", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "paaye", urdu: "پائے", english: "legs", gender: "masculine", number: "plural", form: "plural / oblique", }, { romanUrdu: "paayon", urdu: "پایوں", english: "legs", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/paaya.webp", riddles: { english: "A bed or table stands on me,\nFour of us keep it steady, see!", romanUrdu: "Mez ho ya palang, mujh par khara,\nChaar hon hum to kabhi na gira.", urdu: "میز ہو یا پلنگ، مجھ پر کھڑا،\nچار ہوں ہم تو کبھی نہ گرا۔", }, },
{id: "pachees", word: { baseRomanUrdu: "pachees", baseUrdu: "پچیس", english: "twenty-five", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/pachees.webp", riddles: { english: "After twenty-four it will arrive,\nCount by fives and feel alive!", romanUrdu: "Bees ke baad ginti barhao,\nPaanch aur jor kar jawab pao!", urdu: "بیس کے بعد گنتی بڑھاؤ،\nپانچ اور جوڑ کر جواب پاؤ!", }, },{id: "pahiya", word: { baseRomanUrdu: "pahiya", baseUrdu: "پہیہ", english: "wheel", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "pahiye", urdu: "پہیے", english: "wheels", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/pahiya.webp", riddles: { english: "Round and rolling on the street,\nIt helps a vehicle move its feet.", romanUrdu: "Gol gol ghoomta jaye,\nSawaari ko aage barhaye.", urdu: "گول گول گھومتا جائے،\nسواری کو آگے بڑھائے۔", }, },{id: "pakarna", word: { baseRomanUrdu: "pakarna", baseUrdu: "پکڑنا", english: "hold", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "pakra", urdu: "پکڑا", english: "held", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "pakri", urdu: "پکڑی", english: "held", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "pakar", urdu: "پکڑ", english: "hold/catch", gender: null, number: null, form: "command (stem)", }, { romanUrdu: "pakray", urdu: "پکڑے", english: "held", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "pakro", urdu: "پکڑو", english: "hold it", gender: null, number: null, form: "command", }], image: "/qr/assets/images/pakarna.webp", riddles: { english: "Use your hand and keep it tight,\nDo not let it fall from sight!", romanUrdu: "Haath se cheez sambhali jaye,\nNeeche girne se bach jaye!", urdu: "ہاتھ سے چیز سنبھالی جائے،\nنیچے گرنے سے بچ جائے!", }, },{id: "pani", word: { baseRomanUrdu: "pani", baseUrdu: "پانی", english: "water", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/pani.webp", riddles: { english: "Clear and cool, we drink each day,\nPlants and people need it to stay!", romanUrdu: "Saaf thanda hum peete hain,\nPaude bhi is se jeete hain!", urdu: "صاف ٹھنڈا ہم پیتے ہیں،\nپودے بھی اس سے جیتے ہیں!", }, },{id: "pankha", word: { baseRomanUrdu: "pankha", baseUrdu: "پنکھا", english: "fan", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "pankhay", urdu: "پنکھے", english: "fans", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "pankhon", urdu: "پنکھوں", english: "fans / of fans", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/pankha.webp", riddles: { english: "I spin around to move the air, On hot days I help with care.", romanUrdu: "Ghoom kar hawa chalata hoon, Garmi mein araam dilata hoon.", urdu: "گھوم کر ہوا چلاتا ہوں، گرمی میں آرام دلاتا ہوں۔", }, },{id: "paratha", word: { baseRomanUrdu: "paratha", baseUrdu: "پراٹھا", english: "paratha", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "parathay", urdu: "پراٹھے", english: "parathas", gender: "masculine", number: "plural", form: "plural / oblique", }, { romanUrdu: "parathon", urdu: "پراٹھوں", english: "parathas", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/paratha.webp", riddles: { english: "Round and warm, with ghee I shine,\nAt breakfast time I taste so fine.", romanUrdu: "Gol garam ghee mein tala,\nNashtay mein sab se pyara.", urdu: "گول گرم گھی میں تلا،\nناشتے میں سب سے پیارا۔", }, },{id: "pareshan", word: { baseRomanUrdu: "pareshan", baseUrdu: "پریشان", english: "worried", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/pareshan.webp", riddles: { english: "When thoughts feel tangled in your head, Calm words can help instead.", romanUrdu: "Sochen uljhi si ho jayein, Naram baatein araam dilayein.", urdu: "سوچیں الجھی سی ہو جائیں، نرم باتیں آرام دلائیں۔", }, },{id: "parhna", word: { baseRomanUrdu: "parhna", baseUrdu: "پڑھنا", english: "read", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "parha", urdu: "پڑھا", english: "read (past)", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "parhi", urdu: "پڑھی", english: "read (past)", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "parhne", urdu: "پڑھنے", english: "to read / reading", gender: null, number: null, form: "oblique infinitive", }, { romanUrdu: "parh rahe", urdu: "پڑھ رہے", english: "are reading", gender: "masculine", number: "plural", form: "continuous", }, { romanUrdu: "parho", urdu: "پڑھو", english: "read", gender: null, number: null, form: "command", }], image: "/qr/assets/images/parhna.webp", riddles: { english: "Your eyes move across each line,\nWords turn to stories, oh so fine!", romanUrdu: "Lafzon pe aankhen chalti jayen,\nKahaniyan dil mein utarti jayen.", urdu: "لفظوں پہ آنکھیں چلتی جائیں،\nکہانیاں دل میں اترتی جائیں۔", }, },{id: "parosi", word: { baseRomanUrdu: "parosi", baseUrdu: "پڑوسی", english: "neighbor", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "parosan", urdu: "پڑوسن", english: "female neighbor", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "parosiyon", urdu: "پڑوسیوں", english: "neighbors", gender: null, number: "plural", form: "plural oblique", }], image: "/qr/assets/images/parosi.webp", riddles: { english: "Lives close by, maybe next door,\nA friendly face you may see more!", romanUrdu: "Ghar ke qareeb jo rehta hai,\nKabhi salaam bhi kehta hai!", urdu: "گھر کے قریب جو رہتا ہے،\nکبھی سلام بھی کہتا ہے!", }, },{id: "paseena", word: { baseRomanUrdu: "paseena", baseUrdu: "پسینہ", english: "sweat", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/paseena.webp", riddles: { english: "Tiny drops come when you heat, On your face or hands and feet.", romanUrdu: "Garmi aaye to boonden aayen, Chehre par bhi chamak dikhayen.", urdu: "گرمی آئے تو بوندیں آئیں، چہرے پر بھی چمک دکھائیں۔", }, },{id: "pata", word: { baseRomanUrdu: "pata", baseUrdu: "پتہ", english: "address/leaf", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "patte", urdu: "پتے", english: "addresses/leaves", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "patton", urdu: "پتوں", english: "addresses/leaves", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/pata.webp", riddles: { english: "It may show where someone stays,\nOr grow green on tree-filled days!", romanUrdu: "Kabhi ghar ka raasta bataye,\nKabhi darakht par hara nazar aaye!", urdu: "کبھی گھر کا راستہ بتائے،\nکبھی درخت پر ہرا نظر آئے!", }, },{id: "pata_hona", word: { baseRomanUrdu: "pata hona", baseUrdu: "پتہ ہونا", english: "know", pos: "phrase", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "tha", urdu: "تھا", english: "knew", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "thi", urdu: "تھی", english: "knew", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "the", urdu: "تھے", english: "knew plural", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/pata_hona.webp", riddles: { english: "When the answer is clear inside,\nNo more guessing, no need to hide!", romanUrdu: "Jab baat dil mein saaf ho jaye,\nAndaza phir door chala jaye!", urdu: "جب بات دل میں صاف ہو جائے،\nاندازہ پھر دور چلا جائے!", }, },{id: "patakha", word: { baseRomanUrdu: "patakha", baseUrdu: "پٹاخا", english: "firecracker", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "patakhe", urdu: "پٹاخے", english: "firecrackers", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "patakhon", urdu: "پٹاخوں", english: "firecrackers", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/patakha.webp", riddles: { english: "A loud bright pop in the night,\nFlash and sound give everyone fright!", romanUrdu: "Raat mein zor se awaaz machaye,\nChamak kar sab ko chonka jaye!", urdu: "رات میں زور سے آواز مچائے،\nچمک کر سب کو چونکا جائے!", }, },{id: "patang", word: { baseRomanUrdu: "patang", baseUrdu: "پتنگ", english: "kite", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "patangein", urdu: "پتنگیں", english: "kites", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "patangon", urdu: "پتنگوں", english: "kites", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/patang.webp", riddles: { english: "Paper wings dance in the air,\nString below with colors fair!", romanUrdu: "Dori pakro, hawa mein chhoro,\nRangon wali cheez ko upar toro!", urdu: "ڈوری پکڑو، ہوا میں چھوڑو،\nرنگوں والی چیز کو اوپر دوڑو!", }, },{id: "peechay", word: { baseRomanUrdu: "peechay", baseUrdu: "پیچھے", english: "behind", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/peechay.webp", riddles: { english: "Not in front, but at the back,\nLook around and check the track!", romanUrdu: "Aage nahin, peeche taraf,\nMud kar dekho saaf saaf!", urdu: "آگے نہیں، پیچھے طرف،\nمڑ کر دیکھو صاف صاف!", }, },{id: "peela", word: { baseRomanUrdu: "peela", baseUrdu: "پیلا", english: "yellow", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "peeli", urdu: "پیلی", english: "yellow", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "peelay", urdu: "پیلے", english: "yellow", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/peela.webp", riddles: { english: "Bananas and sunshine share this glow,\nA happy shade that children know!", romanUrdu: "Kele aur dhoop mein ye rang aaye,\nKhushi se chehra chamak jaye!", urdu: "کیلے اور دھوپ میں یہ رنگ آئے،\nخوشی سے چہرہ چمک جائے!", }, },{id: "peena", word: { baseRomanUrdu: "peena", baseUrdu: "پینا", english: "drink", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "piya", urdu: "پیا", english: "drank", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "piyo", urdu: "پیو", english: "drink", gender: null, number: null, form: "command", }, { romanUrdu: "pee raha", urdu: "پی رہا", english: "is drinking", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "pee rahi", urdu: "پی رہی", english: "is drinking", gender: "feminine", number: "singular", form: "continuous", }, { romanUrdu: "piyenge", urdu: "پئیں گے", english: "will drink", gender: "masculine", number: "plural", form: "future", }], image: "/qr/assets/images/peena.webp", riddles: { english: "Water, milk, or chai so sweet,\nSip by sip, but not to eat.", romanUrdu: "Paani, doodh ya garam chai,\nGhoont ghoont andar jaaye bhai.", urdu: "پانی، دودھ یا گرم چائے،\nگھونٹ گھونٹ اندر جائے بھائی۔", }, },
{id: "pehenna", word: { baseRomanUrdu: "pehenna", baseUrdu: "پہننا", english: "wear", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "pehna", urdu: "پہنا", english: "wore", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "pehni", urdu: "پہنی", english: "wore", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "pehne", urdu: "پہنے", english: "wore", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/pehenna.webp", riddles: { english: "Clothes go on before you go,\nThis action helps your outfit show!", romanUrdu: "Kapre jism par saj jate hain,\nPhir hum bahar nikal jate hain!", urdu: "کپڑے جسم پر سج جاتے ہیں،\nپھر ہم باہر نکل جاتے ہیں!", }, },{id: "pehle", word: { baseRomanUrdu: "pehle", baseUrdu: "پہلے", english: "first", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/pehle.webp", riddles: { english: "Before the rest, at number one,\nThis is where things have begun!", romanUrdu: "Sab se aage jo aa jaye,\nGinti mein number aik ban jaye!", urdu: "سب سے آگے جو آ جائے،\nگنتی میں نمبر ایک بن جائے!", }, },{id: "peti", word: { baseRomanUrdu: "peti", baseUrdu: "پیٹی", english: "crate/box", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "petiyan", urdu: "پیٹیاں", english: "crate/box", gender: "feminine", number: "plural", form: "plural", }], image: "/qr/assets/images/peti.webp", riddles: { english: "A box for keeping many things tight,\nSometimes fruit is packed inside.", romanUrdu: "Dabba jaisa samaan sambhale,\nPhal bhi is mein rakhay jaaen.", urdu: "ڈبہ جیسا سامان سنبھالے،\nپھل بھی اس میں رکھے جائیں۔", }, },{id: "phailna", word: { baseRomanUrdu: "phailna", baseUrdu: "پھیلنا", english: "spread", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "phaila", urdu: "پھیلا", english: "spread", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "phaili", urdu: "پھیلی", english: "spread", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "phaile", urdu: "پھیلے", english: "spread", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "phail raha", urdu: "پھیل رہا", english: "is spreading", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "phail rahi", urdu: "پھیل رہی", english: "is spreading", gender: "feminine", number: "singular", form: "continuous", }], image: "/qr/assets/images/phailna.webp", riddles: { english: "Butter, light, or news can go,\nFar and wide, row by row!", romanUrdu: "Cheez dheere dheere fail jaye,\nHar taraf apni jagah banaye!", urdu: "چیز دھیرے دھیرے پھیل جائے،\nہر طرف اپنی جگہ بنائے!", }, },{id: "phir", word: { baseRomanUrdu: "phir", baseUrdu: "پھر", english: "again", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/phir.webp", riddles: { english: "One more time, repeat the play,\nDo the same another day!", romanUrdu: "Aik dafa aur kaam ho jaye,\nWohi baat dobara aa jaye!", urdu: "ایک دفعہ اور کام ہو جائے،\nوہی بات دوبارہ آ جائے!", }, },{id: "phisalna", word: { baseRomanUrdu: "phisalna", baseUrdu: "پھسلنا", english: "slip", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "phisla", urdu: "پھسلا", english: "slipped", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "phisli", urdu: "پھسلی", english: "slipped", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "phisle", urdu: "پھسلے", english: "slipped", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/phisalna.webp", riddles: { english: "Feet may slide and balance go,\nCareful steps help you stay slow!", romanUrdu: "Paon phisle to gir sakte ho,\nAhista chalo to bach sakte ho!", urdu: "پاؤں پھسلے تو گر سکتے ہو،\nآہستہ چلو تو بچ سکتے ہو!", }, },{id: "pista", word: { baseRomanUrdu: "pista", baseUrdu: "پستہ", english: "pistachio", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "piste", urdu: "پستے", english: "pistachios", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/pista.webp", riddles: { english: "Small green nut in sweets you see,\nOn mithai it sits happily!", romanUrdu: "Chhota sa mewa mithai sajaye,\nHara sa rang maza barhaye!", urdu: "چھوٹا سا میوہ مٹھائی سجائے،\nہرا سا رنگ مزہ بڑھائے!", }, },{id: "poochna", word: { baseRomanUrdu: "poochna", baseUrdu: "پوچھنا", english: "ask", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "poocha", urdu: "پوچھا", english: "asked", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "poochi", urdu: "پوچھی", english: "asked", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "pooche", urdu: "پوچھے", english: "asked", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/poochna.webp", riddles: { english: "When you want an answer clear,\nUse your words for others to hear!", romanUrdu: "Jab jawab ki zaroorat ho,\nBaat karo aur maloom karo!", urdu: "جب جواب کی ضرورت ہو،\nبات کرو اور معلوم کرو!", }, },{id: "poora", word: { baseRomanUrdu: "poora", baseUrdu: "پورا", english: "whole", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "poori", urdu: "پوری", english: "whole", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "poore", urdu: "پورے", english: "whole plural", gender: "masculine", number: "plural", form: "plural form", }], image: "/qr/assets/images/poora.webp", riddles: { english: "Not half, not little, fully done,\nEvery part is joined as one!", romanUrdu: "Adha nahin, sab kuch saath,\nPoora hissa aik hi baat!", urdu: "آدھا نہیں، سب کچھ ساتھ،\nپورا حصہ ایک ہی بات!", }, },{id: "purana", word: { baseRomanUrdu: "purana", baseUrdu: "پرانا", english: "old", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "purani", urdu: "پرانی", english: "old", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "puranay", urdu: "پرانے", english: "old", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/purana.webp", riddles: { english: "Not new, it has seen many days,\nFull of stories and old ways.", romanUrdu: "Naya nahi, barson ka saathi,\nKahaniyan is mein samati.", urdu: "نیا نہیں، برسوں کا ساتھی،\nکہانیاں اس میں سماتی۔", }, },{id: "pyaar", word: { baseRomanUrdu: "pyaar", baseUrdu: "پیار", english: "love", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/pyaar.webp", riddles: { english: "You feel it for family, friends, and home,\nIt keeps the heart from feeling alone.", romanUrdu: "Ghar walon aur doston ke liye dil mein aaye,\nYeh ehsaas insaan ko apna banaye.", urdu: "گھر والوں اور دوستوں کے لیے دل میں آئے،\nیہ احساس انسان کو اپنا بنائے۔", }, },{id: "pyali", word: { baseRomanUrdu: "pyali", baseUrdu: "پیالی", english: "cup", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "pyaliyan", urdu: "پیالیاں", english: "cups", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "pyaliyon", urdu: "پیالیوں", english: "of cups", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/pyali.webp", riddles: { english: "Small and round with chai so hot,\nSip from me, but spill me not!", romanUrdu: "Chhoti si, garam chai se bhari,\nDheere piyo, warna girey sari!", urdu: "چھوٹی سی، گرم چائے سے بھری،\nدھیرے پیو، ورنہ گرے ساری!", }, },{id: "pyara", word: { baseRomanUrdu: "pyara", baseUrdu: "پیارا", english: "beloved", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "pyari", urdu: "پیاری", english: "beloved", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "pyare", urdu: "پیارے", english: "beloved plural", gender: "masculine", number: "plural", form: "plural form", }, { romanUrdu: "pyariyan", urdu: "پیاریاں", english: "beloved", gender: "feminine", number: "plural", form: "plural form", }], image: "/qr/assets/images/pyara.webp", riddles: { english: "Someone sweet and dear to you,\nLoved by heart in all you do!", romanUrdu: "Jo dil ko bohat acha lagta,\nPyar ka rishta us se banta!", urdu: "جو دل کو بہت اچھا لگتا،\nپیار کا رشتہ اس سے بنتا!", }, },{id: "qadam", word: { baseRomanUrdu: "qadam", baseUrdu: "قدم", english: "step / footstep", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "qadmon", urdu: "قدموں", english: "footsteps / of steps", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/qadam.webp", riddles: { english: "One after another your feet go,\nTaking you places fast or slow.", romanUrdu: "Aik ke baad aik pair barhao,\nTez ya ahista manzil pao.", urdu: "ایک کے بعد ایک پیر بڑھاؤ،\nتیز یا آہستہ منزل پاؤ۔", }, },{id: "qameez", word: { baseRomanUrdu: "qameez", baseUrdu: "قمیض", english: "shirt", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "qameezein", urdu: "قمیضیں", english: "shirts", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "qameezon", urdu: "قمیضوں", english: "shirts", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/qameez.webp", riddles: { english: "A cloth you put on top each day,\nWith sleeves and buttons on display!", romanUrdu: "Kapra jo upar pehna jaye,\nBazu dhak kar acha lagaye!", urdu: "کپڑا جو اوپر پہنا جائے،\nبازو ڈھک کر اچھا لگائے!", }, },{id: "qareeb", word: { baseRomanUrdu: "qareeb", baseUrdu: "قریب", english: "near/close", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/qareeb.webp", riddles: { english: "Not far away, right by your side,\nEasy to reach, no need to hide.", romanUrdu: "Door nahi, bilkul paas ho,\nHaath barhao to saath ho.", urdu: "دور نہیں، بالکل پاس ہو،\nہاتھ بڑھاؤ تو ساتھ ہو۔", }, },{id: "qataar", word: { baseRomanUrdu: "qataar", baseUrdu: "قطار", english: "row", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "qataarein", urdu: "قطاریں", english: "rows", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "qataaron", urdu: "قطاروں", english: "rows", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/qataar.webp", riddles: { english: "One behind the other we stand,\nStraight and neat, just as planned.", romanUrdu: "Aik ke peechay aik kharay,\nSeedhay seedhay, chhotay baray.", urdu: "ایک کے پیچھے ایک کھڑے،\nسیدھے سیدھے، چھوٹے بڑے۔", }, },
{id: "qurbani", word: { baseRomanUrdu: "qurbani", baseUrdu: "قربانی", english: "sacrifice", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "qurbaniyan", urdu: "قربانیاں", english: "sacrifice", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "qurbaniyon", urdu: "قربانیوں", english: "sacrifice", gender: null, number: "plural", form: "plural oblique", }], image: "/qr/assets/images/qurbani.webp", riddles: { english: "On Eid, giving with love and faith,\nIt teaches sharing, care, and grace.", romanUrdu: "Eid par dena, niyyat saaf,\nBaantna seekho pyar ke saath.", urdu: "عید پر دینا، نیت صاف،\nبانٹنا سیکھو پیار کے ساتھ۔", }, },{id: "raat", word: { baseRomanUrdu: "raat", baseUrdu: "رات", english: "night", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "raatein", urdu: "راتیں", english: "nights", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "raaton", urdu: "راتوں", english: "nights", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/raat.webp", riddles: { english: "Stars come out and lights turn low,\nSleepy time begins to grow!", romanUrdu: "Tare chamken, andhera aaye,\nBachay neend mein kho jaye!", urdu: "تارے چمکیں، اندھیرا آئے،\nبچے نیند میں کھو جائیں!", }, },{id: "raaz", word: { baseRomanUrdu: "raaz", baseUrdu: "راز", english: "secret", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "raazon", urdu: "رازوں", english: "of secrets", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/raaz.webp", riddles: { english: "Something hidden, kept from view,\nOnly a few people know it's true.", romanUrdu: "Chhupi hui baat, sab se door,\nBas kuch log jaanein zaroor.", urdu: "چھپی ہوئی بات، سب سے دور،\nبس کچھ لوگ جانیں ضرور۔", }, },{id: "rakhna", word: { baseRomanUrdu: "rakhna", baseUrdu: "رکھنا", english: "place", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "rakha", urdu: "رکھا", english: "placed", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "rakhi", urdu: "رکھی", english: "placed", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "rakhe", urdu: "رکھے", english: "placed", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "rakheen", urdu: "رکھیں", english: "kept / placed", gender: "feminine", number: "plural", form: "past", }, { romanUrdu: "rakho", urdu: "رکھو", english: "keep / place", gender: null, number: null, form: "command", }, { romanUrdu: "rakh raha", urdu: "رکھ رہا", english: "is keeping", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "rakh rahi", urdu: "رکھ رہی", english: "is keeping", gender: "feminine", number: "singular", form: "continuous", }], image: "/qr/assets/images/rakhna.webp", riddles: { english: "Put it here and let it stay,\nKeep it safe in a careful way!", romanUrdu: "Cheez ko dhyan se idhar bithao,\nApni jagah par usay jamao!", urdu: "چیز کو دھیان سے ادھر بٹھاؤ،\nاپنی جگہ پر اسے جماؤ!", }, },{id: "rang", word: { baseRomanUrdu: "rang", baseUrdu: "رنگ", english: "color", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "rangon", urdu: "رنگوں", english: "colors", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/rang.webp", riddles: { english: "Red, green, yellow, and more,\nThey make the world less dull than before!", romanUrdu: "Laal hara aur peela saath,\nDuniya ko dete pyari baat!", urdu: "لال ہرا اور پیلا ساتھ،\nدنیا کو دیتے پیاری بات!", }, },{id: "rangbarangi", word: { baseRomanUrdu: "rangbarangi", baseUrdu: "رنگ برنگی", english: "colorful", pos: "adjective", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/rangbarangi.webp", riddles: { english: "Many shades together shine,\nBright and cheerful, line by line!", romanUrdu: "Bohat se rang saath aa jayein,\nHar cheez ko khubsurat banayein!", urdu: "بہت سے رنگ ساتھ آ جائیں،\nہر چیز کو خوبصورت بنائیں!", }, },{id: "ras", word: { baseRomanUrdu: "ras", baseUrdu: "رس", english: "juice", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/ras.webp", riddles: { english: "It drips from fruit, fresh and bright,\nA tasty sip full of delight.", romanUrdu: "Phal se niklay meetha sa pani,\nPeene mein aaye mazedar kahani.", urdu: "پھل سے نکلے میٹھا سا پانی،\nپینے میں آئے مزے دار کہانی۔", }, },{id: "rassi", word: { baseRomanUrdu: "rassi", baseUrdu: "رسی", english: "rope", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "rassiyan", urdu: "رسیاں", english: "ropes", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "rassiyon", urdu: "رسیوں", english: "ropes", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/rassi.webp", riddles: { english: "Long and thin, I tie and bind,\nPull me tight, I hold things fine.", romanUrdu: "Lambi patli, baandhoon sab ko,\nKheencho mujhe to thaamoon sab ko.", urdu: "لمبی پتلی، باندھوں سب کو،\nکھینچو مجھے تو تھاموں سب کو۔", }, },
{id: "raunak", word: { baseRomanUrdu: "raunak", baseUrdu: "رونق", english: "liveliness / festivity", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/raunak.webp", riddles: { english: "When people gather, lights aglow,\nI am the sparkle in the show.", romanUrdu: "Log milein to aa jaun,\nMehfil ko chamkaun.", urdu: "لوگ ملیں تو آ جاؤں،\nمحفل کو چمکاؤں۔", }, },{id: "rishtedaar", word: { baseRomanUrdu: "rishtedaar", baseUrdu: "رشتہ دار", english: "relative", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "rishtedaaron", urdu: "رشتہ داروں", english: "relatives", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/rishtedaar.webp", riddles: { english: "Not a stranger, part of your clan,\nFamily ties since life began.", romanUrdu: "Ajnabi nahi, apna hai,\nKhoon ke rishtay ka saathi hai.", urdu: "اجنبی نہیں، اپنا ہے،\nخون کے رشتے کا ساتھی ہے۔", }, },{id: "rokna", word: { baseRomanUrdu: "rokna", baseUrdu: "روکنا", english: "stop", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "roka", urdu: "روکا", english: "stopped", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "roki", urdu: "روکی", english: "stopped", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "roke", urdu: "روکے", english: "stopped", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/rokna.webp", riddles: { english: "Pause right there, do not go,\nThis word makes movement slow!", romanUrdu: "Yahin thehro, aage na jao,\nChalte qadam ko ab rok jao!", urdu: "یہیں ٹھہرو، آگے نہ جاؤ،\nچلتے قدم کو اب روک جاؤ!", }, },{id: "rona", word: { baseRomanUrdu: "rona", baseUrdu: "رونا", english: "cry", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "roya", urdu: "رویا", english: "cried", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "royi", urdu: "روئی", english: "cried", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "roye", urdu: "روئے", english: "cried", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "ro raha", urdu: "رو رہا", english: "is crying", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "ro rahi", urdu: "رو رہی", english: "is crying", gender: "feminine", number: "singular", form: "continuous", }], image: "/qr/assets/images/rona.webp", riddles: { english: "When sadness comes and eyes grow wet,\nTiny drops fall that we do not forget.", romanUrdu: "Jab dil udaas ho, aankh bhar aaye,\nChhote qatre gaalon par aa jayein.", urdu: "جب دل اداس ہو، آنکھ بھر آئے،\nچھوٹے قطرے گالوں پر آ جائیں۔", }, },{id: "roshan", word: { baseRomanUrdu: "roshan", baseUrdu: "روشن", english: "bright", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/roshan.webp", riddles: { english: "A lamp or smile can shine this way,\nMaking darkness fade away!", romanUrdu: "Chamak se andhera door bhagaye,\nChehra bhi noor se bhar jaye!", urdu: "چمک سے اندھیرا دور بھگائے،\nچہرہ بھی نور سے بھر جائے!", }, },{id: "roshni", word: { baseRomanUrdu: "roshni", baseUrdu: "روشنی", english: "light", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "roshniyan", urdu: "روشنیاں", english: "lights", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "roshniyon", urdu: "روشنیوں", english: "lights", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/roshni.webp", riddles: { english: "It helps us see when dark is near,\nA tiny lamp can make things clear!", romanUrdu: "Andhere mein raasta dikhaye,\nChhoti si chamak kaam aa jaye!", urdu: "اندھیرے میں راستہ دکھائے،\nچھوٹی سی چمک کام آ جائے!", }, },{id: "roti", word: { baseRomanUrdu: "roti", baseUrdu: "روٹی", english: "bread", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "rotian", urdu: "روٹیاں", english: "breads", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "rotiyon", urdu: "روٹیوں", english: "breads", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/roti.webp", riddles: { english: "Round and warm beside the meal,\nSoft in hand and nice to feel!", romanUrdu: "Garam gol khane ke saath,\nDaal salan se banti baat!", urdu: "گرم گول کھانے کے ساتھ،\nدال سالن سے بنتی بات!", }, },{id: "roza", word: { baseRomanUrdu: "roza", baseUrdu: "روزہ", english: "fast", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "roze", urdu: "روزے", english: "fasts", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "rozon", urdu: "روزوں", english: "fasts", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/roza.webp", riddles: { english: "Quick like wind, it moves away,\nNo slow steps in its play!", romanUrdu: "Hawa ki tarah jaldi jaye,\nDheema pan peeche reh jaye!", urdu: "ہوا کی طرح جلدی جائے،\nدھیما پن پیچھے رہ جائے!", }, },{id: "rukna", word: { baseRomanUrdu: "rukna", baseUrdu: "رکنا", english: "stop", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "ruka", urdu: "رکا", english: "stopped", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "ruki", urdu: "رکی", english: "stopped", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "rukay", urdu: "رکے", english: "stopped", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "ruk gaya", urdu: "رک گیا", english: "stopped", gender: "masculine", number: "singular", form: "past compound", }, { romanUrdu: "ruk gayi", urdu: "رک گئی", english: "stopped", gender: "feminine", number: "singular", form: "past compound", }, { romanUrdu: "ruk jao", urdu: "رک جاؤ", english: "stop", gender: null, number: null, form: "command", }, { romanUrdu: "ruko", urdu: "رکو", english: "stop", gender: null, number: null, form: "command", }, { romanUrdu: "ruk gaye", urdu: "رک گئے", english: "stopped", gender: "masculine", number: "plural", form: "past compound", }], image: "/qr/assets/images/rukna.webp", riddles: { english: "Moving ends and stillness stays, I pause the steps along the way.", romanUrdu: "Chalte chalte qadam tham jayein, Aage barhna band ho jaye.", urdu: "چلتے چلتے قدم تھم جائیں، آگے بڑھنا بند ہو جائے۔", }, },{id: "saaf", word: { baseRomanUrdu: "saaf", baseUrdu: "صاف", english: "clean", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/saaf.webp", riddles: { english: "No dust, no mess, all fresh and neat,\nEverything looks nice and sweet!", romanUrdu: "Mitti door, sab kuch pyara,\nGhar lagta hai saaf sitara!", urdu: "مٹی دور، سب کچھ پیارا،\nگھر لگتا ہے صاف ستھرا!", }, },{id: "saal", word: { baseRomanUrdu: "saal", baseUrdu: "سال", english: "year", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "saalon", urdu: "سالوں", english: "years", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/saal.webp", riddles: { english: "Twelve months make this time go by,\nBirthdays come as days fly!", romanUrdu: "Barah maheenay mil kar aayein,\nSaal bhar ke din banayein!", urdu: "بارہ مہینے مل کر آئیں،\nسال بھر کے دن بنائیں!", }, },{id: "saamne", word: { baseRomanUrdu: "saamne", baseUrdu: "سامنے", english: "front", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/saamne.webp", riddles: { english: "Look ahead, not to the back,\nThis direction stays on track!", romanUrdu: "Aankhon ke aage jo nazar aaye,\nSeedha dekho, wahi dikh jaye!", urdu: "آنکھوں کے آگے جو نظر آئے،\nسیدھا دیکھو، وہی دکھ جائے!", }, },{id: "saans", word: { baseRomanUrdu: "saans", baseUrdu: "سانس", english: "breath", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "saansein", urdu: "سانسیں", english: "breaths", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "saanson", urdu: "سانسوں", english: "breaths", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/saans.webp", riddles: { english: "In and out, soft and slow,\nIt helps your living body go!", romanUrdu: "Andar bahar hawa chalti,\nZindagi ki narmi palti!", urdu: "اندر باہر ہوا چلتی،\nزندگی کی نرمی پلتی!", }, },{id: "saath", word: { baseRomanUrdu: "saath", baseUrdu: "ساتھ", english: "with", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/saath.webp", riddles: { english: "Together close, side by side,\nNo one has to walk alone outside!", romanUrdu: "Mil kar chalna acha lagta,\nSaath ho to dil nahin darta!", urdu: "مل کر چلنا اچھا لگتا،\nساتھ ہو تو دل نہیں ڈرتا!", }, },{id: "sabr", word: { baseRomanUrdu: "sabr", baseUrdu: "صبر", english: "patience", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/sabr.webp", riddles: { english: "You stay calm and do not hurry,\nEven when waiting brings some worry.", romanUrdu: "Dil ko araam se rokna aaye,\nJaldi mein bhi sukoon banaye.", urdu: "دل کو آرام سے روکنا آئے،\nجلدی میں بھی سکون بنائے۔", }, },{id: "sabz", word: { baseRomanUrdu: "sabz", baseUrdu: "سبز", english: "green", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/sabz.webp", riddles: { english: "The color of leaves and grass so bright,\nOn the flag it stands with white.", romanUrdu: "Patton aur ghaas ka rang yahi,\nJhanday par bhi sajta wahi.", urdu: "پتوں اور گھاس کا رنگ یہی،\nجھنڈے پر بھی سجتا وہی۔", }, },{id: "sabzi", word: { baseRomanUrdu: "sabzi", baseUrdu: "سبزی", english: "vegetable", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "sabziyan", urdu: "سبزیاں", english: "vegetables", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "sabziyon", urdu: "سبزیوں", english: "vegetables", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/sabzi.webp", riddles: { english: "Green or orange, fresh and bright,\nCook me well and take a bite!", romanUrdu: "Kabhi hari, kabhi narangi,\nPaka ke khao, sehat laaye sang hi!", urdu: "کبھی ہری، کبھی نارنجی،\nپکا کے کھاؤ، صحت لائے سنگ ہی!", }, },{id: "safaid", word: { baseRomanUrdu: "safaid", baseUrdu: "سفید", english: "white", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/safaid.webp", riddles: { english: "Clouds and milk both wear this shade,\nThe brightest color ever made.", romanUrdu: "Doodh aur badal is mein rangay,\nSab rangon mein roshan lagay.", urdu: "دودھ اور بادل اس میں رنگے،\nسب رنگوں میں روشن لگے۔", }, },{id: "salaam", word: { baseRomanUrdu: "salaam", baseUrdu: "سلام", english: "greeting", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/salaam.webp", riddles: { english: "A kind word when people meet,\nWarm and respectful, soft and sweet!", romanUrdu: "Milte waqt pyar se keh do,\nAdab aur dua saath mein de do!", urdu: "ملتے وقت پیار سے کہہ دو،\nادب اور دعا ساتھ میں دے دو!", }, },{id: "samajh", word: { baseRomanUrdu: "samajh", baseUrdu: "سمجھ", english: "understand", pos: "verb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/samajh.webp", riddles: { english: "When meaning reaches mind and heart,\nA hard thing feels less apart!", romanUrdu: "Jab baat zehan mein aa jaye,\nMushkil cheez asaan ban jaye!", urdu: "جب بات ذہن میں آ جائے،\nمشکل چیز آسان بن جائے!", }, },{id: "samajhna", word: { baseRomanUrdu: "samajhna", baseUrdu: "سمجھنا", english: "understand", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "samjha", urdu: "سمجھا", english: "understood", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "samjhi", urdu: "سمجھی", english: "understood", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "samjhe", urdu: "سمجھے", english: "understood", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "samajh aaya", urdu: "سمجھ آیا", english: "understood", gender: "masculine", number: "singular", form: "past compound", }, { romanUrdu: "samajh aayi", urdu: "سمجھ آئی", english: "understood", gender: "feminine", number: "singular", form: "past compound", }, { romanUrdu: "samjho", urdu: "سمجھو", english: "understand", gender: null, number: null, form: "command", }, { romanUrdu: "samajh", urdu: "سمجھ", english: "understanding", gender: null, number: null, form: "stem / noun form", }], image: "/qr/assets/images/samajhna.webp", riddles: { english: "A thought becomes clear in your mind, like a hidden answer you can find.", romanUrdu: "Zehan mein baat saaf ho jaye, chhupa jawab nazar aa jaye.", urdu: "ذہن میں بات صاف ہو جائے، چھپا جواب نظر آ جائے۔", }, },{id: "samandar", word: { baseRomanUrdu: "samandar", baseUrdu: "سمندر", english: "ocean", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "samandaron", urdu: "سمندروں", english: "oceans", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/samandar.webp", riddles: { english: "Huge blue waves go far and wide,\nMany creatures live inside!", romanUrdu: "Bohat bara pani ka ghar,\nLehron ka hota hai safar!", urdu: "بہت بڑا پانی کا گھر،\nلہروں کا ہوتا ہے سفر!", }, },{id: "samjhana", word: { baseRomanUrdu: "samjhana", baseUrdu: "سمجھانا", english: "explain", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "samjhaya", urdu: "سمجھایا", english: "explained", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "samjhayi", urdu: "سمجھائی", english: "explained", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "samjhaye", urdu: "سمجھائے", english: "explained", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/samjhana.webp", riddles: { english: "You make a hard thing clear and bright,\nThen someone says, now I see it right.", romanUrdu: "Mushkil baat ko asaan banao,\nDoosre ko araam se batao.", urdu: "مشکل بات کو آسان بناؤ،\nدوسرے کو آرام سے بتاؤ۔", }, },{id: "samosa", word: { baseRomanUrdu: "samosa", baseUrdu: "سموسہ", english: "samosa", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "samosay", urdu: "سموسے", english: "samosas", gender: "masculine", number: "plural", form: "plural / oblique", }, { romanUrdu: "samoson", urdu: "سموسوں", english: "samosas", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/samosa.webp", riddles: { english: "A crispy triangle, hot inside,\nWith chutney I am often tried.", romanUrdu: "Teen konon wala karara,\nChatni ke saath sab ko pyara.", urdu: "تین کونوں والا کرارا،\nچٹنی کے ساتھ سب کو پیارا۔", }, },{id: "sandook", word: { baseRomanUrdu: "sandook", baseUrdu: "صندوق", english: "trunk / chest", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "sandookon", urdu: "صندوقوں", english: "of trunks", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/sandook.webp", riddles: { english: "A big old box with a heavy lid,\nTreasures and memories inside are hid.", romanUrdu: "Bara sa dabba, bhaari dhakkan,\nAndar chhupi yaadon ki dharkan.", urdu: "بڑا سا ڈبہ، بھاری ڈھکن،\nاندر چھپی یادوں کی دھڑکن۔", }, },{id: "sarak", word: { baseRomanUrdu: "sarak", baseUrdu: "سڑک", english: "road", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "sarakein", urdu: "سڑکیں", english: "roads", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "sarakon", urdu: "سڑکوں", english: "roads", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/sarak.webp", riddles: { english: "Cars and people use this way,\nIt helps us travel every day!", romanUrdu: "Gaariyan is par chalti hain,\nManzil tak rahein milti hain!", urdu: "گاڑیاں اس پر چلتی ہیں،\nمنزل تک راہیں ملتی ہیں!", }, },{id: "sawaal", word: { baseRomanUrdu: "sawaal", baseUrdu: "سوال", english: "question", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "sawalat", urdu: "سوالات", english: "questions", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "sawaalon", urdu: "سوالوں", english: "questions", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/sawaal.webp", riddles: { english: "It asks for answers, big or small,\nLearning starts when you use it all!", romanUrdu: "Jab maloom karna ho koi baat,\nIs se khulti ilm ki raat!", urdu: "جب معلوم کرنا ہو کوئی بات،\nاس سے کھلتی علم کی بات!", }, },{id: "seekhna", word: { baseRomanUrdu: "seekhna", baseUrdu: "سیکھنا", english: "learn", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "seekha", urdu: "سیکھا", english: "learned", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "seekhi", urdu: "سیکھی", english: "learned", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "seekhe", urdu: "سیکھے", english: "learned", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/seekhna.webp", riddles: { english: "New words grow inside your mind,\nPractice helps you be refined!", romanUrdu: "Nayi baatein zehan mein aayein,\nMashq se bachay aage jayein!", urdu: "نئی باتیں ذہن میں آئیں،\nمشق سے بچے آگے جائیں!", }, },{id: "seerhi", word: { baseRomanUrdu: "seerhi", baseUrdu: "سیڑھی", english: "ladder / stairs", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "seerhiyan", urdu: "سیڑھیاں", english: "ladders / stairs", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "seerhiyon", urdu: "سیڑھیوں", english: "ladders / stairs", gender: "feminine", number: "plural", form: "plural oblique", }, ], image: "/qr/assets/images/seerhi.webp", riddles: { english: "Step by step I take you high,\nUp towards the roof or sky.", romanUrdu: "Qadam qadam upar le jaun,\nChhat tak tumhein pohanchaun.", urdu: "قدم قدم اوپر لے جاؤں،\nچھت تک تمہیں پہنچاؤں۔", }, },{id: "sehan", word: { baseRomanUrdu: "sehan", baseUrdu: "صحن", english: "courtyard", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/sehan.webp", riddles: { english: "An open space inside the home,\nUnder the sky where children roam.", romanUrdu: "Ghar ke andar khuli si jagah,\nUpar aasmaan, bachon ke khel ki jagah.", urdu: "گھر کے اندر کھلی سی جگہ،\nاوپر آسمان، بچوں کے کھیل کی جگہ۔", }, },{id: "shaam", word: { baseRomanUrdu: "shaam", baseUrdu: "شام", english: "evening", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "shaamein", urdu: "شامیں", english: "evenings", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "shaamon", urdu: "شاموں", english: "evenings", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/shaam.webp", riddles: { english: "Sun goes down, the sky turns gold,\nDay becomes soft, calm, and old!", romanUrdu: "Sooraj dhalta, rang badalte,\nDin ke qissay dheere dhalte!", urdu: "سورج ڈھلتا، رنگ بدلتے،\nدن کے قصے دھیرے ڈھلتے!", }, },{id: "shayad", word: { baseRomanUrdu: "shayad", baseUrdu: "شاید", english: "maybe", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/shayad.webp", riddles: { english: "Not yes, not no, just wait and see,\nA little chance of what could be!", romanUrdu: "Na haan puri, na inkaar,\nHo bhi sakta hai is baar!", urdu: "نہ ہاں پوری، نہ انکار،\nہو بھی سکتا ہے اس بار!", }, },{id: "sheerkhurma", word: { baseRomanUrdu: "sheerkhurma", baseUrdu: "شیر خرما", english: "dessert", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/sheerkhurma.webp", riddles: { english: "Sweet Eid treat in a bowl,\nMilk and nuts make hearts feel whole!", romanUrdu: "Meethi meethi eid ki cheez,\nDoodh mewa laaye lazeez!", urdu: "میٹھی میٹھی عید کی چیز،\nدودھ میوہ لائے لذیذ!", }, },{id: "sheesha", word: { baseRomanUrdu: "sheesha", baseUrdu: "شیشہ", english: "glass", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "sheeshe", urdu: "شیشے", english: "glasses", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "sheeshon", urdu: "شیشوں", english: "glasses", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/sheesha.webp", riddles: { english: "Clear and shiny, easy to see,\nWindows and cups can this thing be!", romanUrdu: "Saaf chamakdar nazar bhi aaye,\nKabhi khidki kabhi pyala ban jaye!", urdu: "صاف چمکدار نظر بھی آئے،\nکبھی کھڑکی کبھی پیالہ بن جائے!", }, },{id: "shehar", word: { baseRomanUrdu: "shehar", baseUrdu: "شہر", english: "city", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "shehron", urdu: "شہروں", english: "cities", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/shehar.webp", riddles: { english: "Many homes and markets meet,\nCars and people fill each street!", romanUrdu: "Ghar bazar aur raste saath,\nLogon se bhari hoti har raat!", urdu: "گھر بازار اور راستے ساتھ،\nلوگوں سے بھری ہوتی ہر رات!", }, },{id: "shikayat", word: { baseRomanUrdu: "shikayat", baseUrdu: "شکایت", english: "complaint", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "shikayatein", urdu: "شکایتیں", english: "complaints", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "shikayaton", urdu: "شکایتوں", english: "complaints", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/shikayat.webp", riddles: { english: "When something's wrong, you let it out,\nYou grumble, frown, and maybe pout.", romanUrdu: "Kuch ghalat ho to batlao,\nMunh bana kar dukh sunao.", urdu: "کچھ غلط ہو تو بتلاؤ،\nمنہ بنا کر دکھ سناؤ۔", }, },
{id: "shor", word: { baseRomanUrdu: "shor", baseUrdu: "شور", english: "noise", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/shor.webp", riddles: { english: "Too many sounds can fill the air,\nCover your ears if it is there!", romanUrdu: "Bohat si awaazein mil kar aayein,\nKaan kabhi thak se jayein!", urdu: "بہت سی آوازیں مل کر آئیں،\nکان کبھی تھک سے جائیں!", }, },{id: "shukriya", word: { baseRomanUrdu: "shukriya", baseUrdu: "شکریہ", english: "thanks", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/shukriya.webp", riddles: { english: "A kind word after help is done,\nIt makes hearts warm like sun!", romanUrdu: "Madad mile to pyar se bolo,\nDil ko narmi se tum kholo!", urdu: "مدد ملے تو پیار سے بولو،\nدل کو نرمی سے تم کھولو!", }, },{id: "shuru", word: { baseRomanUrdu: "shuru", baseUrdu: "شروع", english: "begin", pos: "verb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/shuru.webp", riddles: { english: "At the start, the story grows,\nThis is where the first step goes!", romanUrdu: "Pehla qadam jab uth jaye,\nNayi kahani chalti jaye!", urdu: "پہلا قدم جب اٹھ جائے،\nنئی کہانی چلتی جائے!", }, },{id: "sochna", word: { baseRomanUrdu: "sochna", baseUrdu: "سوچنا", english: "think", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "socha", urdu: "سوچا", english: "thought", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "sochi", urdu: "سوچی", english: "thought", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "soche", urdu: "سوچے", english: "thought", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "soch raha", urdu: "سوچ رہا", english: "is thinking", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "soch rahi", urdu: "سوچ رہی", english: "is thinking", gender: "feminine", number: "singular", form: "continuous", }, { romanUrdu: "soch rahe", urdu: "سوچ رہے", english: "are thinking", gender: "masculine", number: "plural", form: "continuous", }], image: "/qr/assets/images/sochna.webp", riddles: { english: "Ideas move inside your head,\nBefore you speak or act instead!", romanUrdu: "Zehan mein baatein ghoomti jayein,\nPhir jawab hont par aayein!", urdu: "ذہن میں باتیں گھومتی جائیں،\nپھر جواب ہونٹ پر آئیں!", }, },{id: "sona", word: { baseRomanUrdu: "sona", baseUrdu: "سونا", english: "sleep", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "soya", urdu: "سویا", english: "slept", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "soyi", urdu: "سوئی", english: "slept", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "soye", urdu: "سوئے", english: "slept", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "so raha", urdu: "سو رہا", english: "is sleeping", gender: "masculine", number: "singular", form: "continuous", }, { romanUrdu: "so rahi", urdu: "سو رہی", english: "is sleeping", gender: "feminine", number: "singular", form: "continuous", }, { romanUrdu: "so rahe", urdu: "سو رہے", english: "are sleeping", gender: "masculine", number: "plural", form: "continuous", }], image: "/qr/assets/images/sona.webp", riddles: { english: "Eyes grow heavy, dreams arrive,\nRest helps little bodies thrive!", romanUrdu: "Aankhein band, khwab bhi aayein,\nAaram se bachay taqat paayein!", urdu: "آنکھیں بند، خواب بھی آئیں،\nآرام سے بچے طاقت پائیں!", }, },{id: "subah", word: { baseRomanUrdu: "subah", baseUrdu: "صبح", english: "morning", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/subah.webp", riddles: { english: "Sun comes up and day is new,\nBirds say hello to me and you!", romanUrdu: "Sooraj nikle, din muskuraye,\nNayi roshni ghar mein aaye!", urdu: "سورج نکلے، دن مسکرائے،\nنئی روشنی گھر میں آئے!", }, },{id: "sukoon", word: { baseRomanUrdu: "sukoon", baseUrdu: "سکون", english: "peace", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/sukoon.webp", riddles: { english: "Quiet heart and gentle mind,\nSoft calm feelings you can find!", romanUrdu: "Dil mein narmi, soch mein chain,\nHar taraf ho pyara sukoon!", urdu: "دل میں نرمی، سوچ میں چین،\nہر طرف ہو پیارا سکون!", }, },{id: "sunai", word: { baseRomanUrdu: "sunai", baseUrdu: "سنائی", english: "audible", pos: "adjective", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "sunai dena", urdu: "سنائی دینا", english: "to be heard", gender: null, number: null, form: "phrase", }], image: "/qr/assets/images/sunai.webp", riddles: { english: "A sound reaches your ear,\nNow the hidden thing is clear!", romanUrdu: "Awaaz jab kaan tak aaye,\nChhupi hui baat samajh mein aaye!", urdu: "آواز جب کان تک آئے،\nچھپی ہوئی بات سمجھ میں آئے!", }, },{id: "sunehra", word: { baseRomanUrdu: "sunehra", baseUrdu: "سنہرا", english: "golden", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "sunehri", urdu: "سنہری", english: "golden", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "sunehray", urdu: "سنہرے", english: "golden", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/sunehra.webp", riddles: { english: "The color of sunshine on a bright day,\nOn wedding clothes it shines this way.", romanUrdu: "Dhoop jaisa chamakta rang,\nShaadi ke kapron ke sang.", urdu: "دھوپ جیسا چمکتا رنگ،\nشادی کے کپڑوں کے سنگ۔", }, },{id: "sunana", word: { baseRomanUrdu: "sunana", baseUrdu: "سنانا", english: "tell", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "sunaya", urdu: "سنایا", english: "told", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "sunayi", urdu: "سنائی", english: "told", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "sunao", urdu: "سناؤ", english: "tell", gender: null, number: null, form: "command", }, { romanUrdu: "sunayein", urdu: "سنائیں", english: "tell", gender: null, number: null, form: "polite command", }], image: "/qr/assets/images/sunana.webp", riddles: { english: "Share a tale for all to hear,\nSo every listener lends an ear.", romanUrdu: "Kahani apni sab ko batao,\nDoosron ke kaanon tak pahunchao.", urdu: "کہانی اپنی سب کو بتاؤ،\nدوسروں کے کانوں تک پہنچاؤ۔", }, },
{id: "sunna", word: { baseRomanUrdu: "sunna", baseUrdu: "سننا", english: "hear", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "suna", urdu: "سنا", english: "heard", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "suni", urdu: "سنی", english: "heard", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "suno", urdu: "سنو", english: "listen", gender: null, number: null, form: "command", }, { romanUrdu: "sunay", urdu: "سنے", english: "heard", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/sunna.webp", riddles: { english: "Your ears catch sounds around,\nVoices, bells, and every sound!", romanUrdu: "Kaan se awaaz pakri jaye,\nBaat foran samajh mein aaye!", urdu: "کان سے آواز پکڑی جائے،\nبات فوراً سمجھ میں آئے!", }, },{id: "surmai", word: { baseRomanUrdu: "surmai", baseUrdu: "سرمئی", english: "gray", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/surmai.webp", riddles: { english: "Cloudy sky and smoky shade,\nNot quite black, not white displayed!", romanUrdu: "Badal jaisa halka rang,\nNa kala pura, na safed sang!", urdu: "بادل جیسا ہلکا رنگ،\nنہ کالا پورا، نہ سفید سنگ!", }, },{id: "taala", word: { baseRomanUrdu: "taala", baseUrdu: "تالا", english: "lock", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "taale", urdu: "تالے", english: "locks / lock (oblique)", gender: "masculine", number: "plural", form: "plural / oblique", }, { romanUrdu: "taalon", urdu: "تالوں", english: "of locks", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/taala.webp", riddles: { english: "I keep the door shut tight and strong,\nOnly my key can open me along.", romanUrdu: "Darwaza band rakhoon mazboot,\nChaabi ke baghair na khuloon kabhi.", urdu: "دروازہ بند رکھوں مضبوط،\nچابی کے بغیر نہ کھلوں کبھی۔", }, },{id: "tairna", word: { baseRomanUrdu: "tairna", baseUrdu: "تیرنا", english: "swim/float", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "taira", urdu: "تیرا", english: "swam/floated", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "tairi", urdu: "تیری", english: "swam/floated", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "taire", urdu: "تیرے", english: "swam/floated", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/tairna.webp", riddles: { english: "Move through water or stay on top,\nSplash and glide without a stop!", romanUrdu: "Pani mein chalna ya upar rehna,\nLehron ke saath halka behna!", urdu: "پانی میں چلنا یا اوپر رہنا،\nلہروں کے ساتھ ہلکا بہنا!", }, },{id: "tasveer", word: { baseRomanUrdu: "tasveer", baseUrdu: "تصویر", english: "picture / photograph", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "tasveerein", urdu: "تصویریں", english: "pictures", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "tasveeron", urdu: "تصویروں", english: "of pictures", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/tasveer.webp", riddles: { english: "I keep a moment, still and true,\nFaces from long ago look back at you.", romanUrdu: "Aik lamha qaid mein rakhti hoon,\nPuranay chehre tumhein dikhati hoon.", urdu: "ایک لمحہ قید میں رکھتی ہوں،\nپرانے چہرے تمہیں دکھاتی ہوں۔", }, },{id: "tayari", word: { baseRomanUrdu: "tayari", baseUrdu: "تیاری", english: "preparation", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "tayariyan", urdu: "تیاریاں", english: "preparations", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "tayariyon", urdu: "تیاریوں", english: "preparations", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/tayari.webp", riddles: { english: "Before a big day, work is done,\nPlans and lists make ready fun!", romanUrdu: "Bara din aaye to kaam sajayein,\nPehle se sab cheez banayein!", urdu: "بڑا دن آئے تو کام سجائیں،\nپہلے سے سب چیز بنائیں!", }, },{id: "tayyar", word: { baseRomanUrdu: "tayyar", baseUrdu: "تیار", english: "ready", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/tayyar.webp", riddles: { english: "Everything is set to go, No more waiting, now we know.", romanUrdu: "Sab kuch ho jaye jab poora, Phir na rahe koi adhoora.", urdu: "سب کچھ ہو جائے جب پورا، پھر نہ رہے کوئی ادھورا۔", }, },{id: "teen", word: { baseRomanUrdu: "teen", baseUrdu: "تین", english: "three", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/teen.webp", riddles: { english: "After two and before four,\nCount this number at your door!", romanUrdu: "Do ke baad aur chaar se pehle,\nGinti seekho dheere dheere!", urdu: "دو کے بعد اور چار سے پہلے،\nگنتی سیکھو دھیرے دھیرے!", }, },{id: "tez", word: { baseRomanUrdu: "tez", baseUrdu: "تیز", english: "fast", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/tez.webp", riddles: { english: "Quick like wind, it moves away,\nNo slow steps in its play!", romanUrdu: "Hawa ki tarah jaldi jaye,\nDheema pan peeche reh jaye!", urdu: "ہوا کی طرح جلدی جائے،\nدھیما پن پیچھے رہ جائے!", }, },{id: "thand", word: { baseRomanUrdu: "thand", baseUrdu: "ٹھنڈ", english: "cold", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/thand.webp", riddles: { english: "Ice and winter share this feel,\nWrap up warm from head to heel!", romanUrdu: "Baraf jaisa ehsaas aaye,\nGaram kapra kaam aa jaye!", urdu: "برف جیسا احساس آئے،\nگرم کپڑا کام آ جائے!", }, },{id: "thanday", word: { baseRomanUrdu: "thanday", baseUrdu: "ٹھنڈے", english: "cold", pos: "adjective", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "thanda", urdu: "ٹھنڈا", english: "cold", gender: "masculine", number: "singular", form: "masculine singular", }, { romanUrdu: "thandi", urdu: "ٹھنڈی", english: "cold", gender: "feminine", number: "singular", form: "feminine form", }, { romanUrdu: "thandiyan", urdu: "ٹھنڈیاں", english: "cold", gender: "feminine", number: "plural", form: "feminine plural", }], image: "/qr/assets/images/thanday.webp", riddles: { english: "Not warm at all, cool to touch,\nIn summer days we like it much.", romanUrdu: "Garam na ho, haath ko bhaye,\nGarmi mein sab is ko chahen.", urdu: "گرم نہ ہو، ہاتھ کو بھائے،\nگرمی میں سب اس کو چاہیں۔", }, },{id: "theek", word: { baseRomanUrdu: "theek", baseUrdu: "ٹھیک", english: "correct/fine", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/theek.webp", riddles: { english: "Not wrong, not broken, all is right and ready.", romanUrdu: "Ghalat nahi, sab sahi ho jaye, dil ko araam aa jaye.", urdu: "غلط نہیں، سب صحیح ہو جائے، دل کو آرام آ جائے۔", }, },{id: "tohfa", word: { baseRomanUrdu: "tohfa", baseUrdu: "تحفہ", english: "gift", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "tohfay", urdu: "تحفے", english: "gifts", gender: "masculine", number: "plural", form: "plural / oblique", }, { romanUrdu: "tohfon", urdu: "تحفوں", english: "gifts", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/tohfa.webp", riddles: { english: "Wrapped with love and given free,\nA happy surprise from you to me.", romanUrdu: "Pyar se de diya jaun,\nDil khush kar jaun.", urdu: "پیار سے دے دیا جاؤں،\nدل خوش کر جاؤں۔", }, },{id: "tokri", word: { baseRomanUrdu: "tokri", baseUrdu: "ٹوکری", english: "basket", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "tokriyan", urdu: "ٹوکریاں", english: "baskets", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "tokriyon", urdu: "ٹوکریوں", english: "baskets", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/tokri.webp", riddles: { english: "I hold fruit, flowers, or toys with care,\nCarry me gently from here to there!", romanUrdu: "Phal ho ya phool, main sambhal kar rakhun,\nMujhe utha kar idhar se udhar le jao tum!", urdu: "پھل ہو یا پھول، میں سنبھال کر رکھوں،\nمجھے اٹھا کر ادھر سے ادھر لے جاؤ تم!", }, },{id: "toofan", word: { baseRomanUrdu: "toofan", baseUrdu: "طوفان", english: "storm", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "toofanon", urdu: "طوفانوں", english: "storms / of storms", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/toofan.webp", riddles: { english: "Strong wind rushes with a roar, making trees shake more and more.", romanUrdu: "Tez hawa zor se aaye, darakhton ko hilati jaye.", urdu: "تیز ہوا زور سے آئے، درختوں کو ہلاتی جائے۔", }, },{id: "tootna", word: { baseRomanUrdu: "tootna", baseUrdu: "ٹوٹنا", english: "break", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "toota", urdu: "ٹوٹا", english: "broke", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "tooti", urdu: "ٹوٹی", english: "broke", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "tootay", urdu: "ٹوٹے", english: "broke", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "toot gaya", urdu: "ٹوٹ گیا", english: "broke", gender: "masculine", number: "singular", form: "past compound", }, { romanUrdu: "toot gayi", urdu: "ٹوٹ گئی", english: "broke", gender: "feminine", number: "singular", form: "past compound", }], image: "/qr/assets/images/tootna.webp", riddles: { english: "Drop a glass and hear the sound,\nLittle pieces on the ground.", romanUrdu: "Gilaas gire to chhan chhan ho,\nTukre tukre zameen pe ho.", urdu: "گلاس گرے تو چھن چھن ہو،\nٹکڑے ٹکڑے زمین پہ ہو۔", }, },
{id: "uchhalna", word: { baseRomanUrdu: "uchhalna", baseUrdu: "اچھلنا", english: "jump", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "uchhla", urdu: "اچھلا", english: "jumped", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "uchhli", urdu: "اچھلی", english: "jumped", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "uchhle", urdu: "اچھلے", english: "jumped", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/uchhalna.webp", riddles: { english: "Feet leave ground for just a beat,\nUp you go on happy feet!", romanUrdu: "Paon zameen se upar jaye,\nKhushi mein bacha uchal dikhaye!", urdu: "پاؤں زمین سے اوپر جائے،\nخوشی میں بچہ اچھل دکھائے!", }, },{id: "udaas", word: { baseRomanUrdu: "udaas", baseUrdu: "اُداس", english: "sad", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/udaas.webp", riddles: { english: "A heavy heart, a quiet face,\nSmiles may hide for a little space!", romanUrdu: "Dil halka sa bojhal ho jaye,\nChehra chup sa nazar aaye!", urdu: "دل ہلکا سا بوجھل ہو جائے،\nچہرہ چپ سا نظر آئے!", }, },{id: "udaasi", word: { baseRomanUrdu: "udaasi", baseUrdu: "اداسی", english: "sadness", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/udaas.webp", riddles: { english: "A heavy feeling, soft and gray,\nWhen smiles seem far away.", romanUrdu: "Dil par halka bojh sa chhaye,\nMuskaan kahin kho jaye.", urdu: "دل پر ہلکا بوجھ سا چھائے،\nمسکان کہیں کھو جائے۔", }, },{id: "ungli", word: { baseRomanUrdu: "ungli", baseUrdu: "انگلی", english: "finger", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "ungliyan", urdu: "انگلیاں", english: "fingers", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "ungliyon", urdu: "انگلیوں", english: "fingers", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/ungli.webp", riddles: { english: "Five on each hand, small and quick,\nWe point and write and hold a stick.", romanUrdu: "Har haath par paanch, chhoti si,\nIshaara karein aur likhein bhi.", urdu: "ہر ہاتھ پر پانچ، چھوٹی سی،\nاشارہ کریں اور لکھیں بھی۔", }, },
{id: "upar", word: { baseRomanUrdu: "upar", baseUrdu: "اوپر", english: "above", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/upar.webp", riddles: { english: "Look up high, not down below,\nThat is where this place will show!", romanUrdu: "Neeche nahin, upar dekho,\nSar uthao aur jagah dekho!", urdu: "نیچے نہیں، اوپر دیکھو،\nسر اٹھاؤ اور جگہ دیکھو!", }, },{id: "urana", word: { baseRomanUrdu: "urana", baseUrdu: "اُڑانا", english: "fly", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "uraya", urdu: "اُڑایا", english: "flew", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "urayi", urdu: "اُڑائی", english: "flew", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "uraye", urdu: "اُڑائے", english: "flew", gender: "masculine", number: "plural", form: "past", }], image: "/qr/assets/images/urana.webp", riddles: { english: "Birds and kites go through the sky,\nWings or string can help them rise!", romanUrdu: "Par ya dori aasman le jaye,\nHawa ke saath cheez uth jaye!", urdu: "پر یا ڈوری آسمان لے جائے،\nہوا کے ساتھ چیز اٹھ جائے!", }, },{id: "uthana", word: { baseRomanUrdu: "uthana", baseUrdu: "اٹھانا", english: "pick up / lift", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "uthaya", urdu: "اٹھایا", english: "picked up", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "uthayi", urdu: "اٹھائی", english: "picked up", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "uthaye", urdu: "اٹھائے", english: "picked up", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "uthao", urdu: "اٹھاؤ", english: "pick up", gender: null, number: null, form: "command", }, { romanUrdu: "utha raha", urdu: "اٹھا رہا", english: "is picking up", gender: "masculine", number: "singular", form: "continuous", }], image: "/qr/assets/images/uthana.webp", riddles: { english: "If something falls down on the floor,\nYou do this to hold it once more.", romanUrdu: "Zameen pe gire jo cheez kabhi,\nHaath barha kar karo yeh abhi.", urdu: "زمین پہ گرے جو چیز کبھی،\nہاتھ بڑھا کر کرو یہ ابھی۔", }, },{id: "wapas", word: { baseRomanUrdu: "wapas", baseUrdu: "واپس", english: "return", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/wapas.webp", riddles: { english: "Go away, then come back here,\nHome again feels warm and near!", romanUrdu: "Door ja kar phir laut aao,\nApni jagah wapas pao!", urdu: "دور جا کر پھر لوٹ آؤ،\nاپنی جگہ واپس پاؤ!", }, },{id: "yaad", word: { baseRomanUrdu: "yaad", baseUrdu: "یاد", english: "memory", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "yaadein", urdu: "یادیں", english: "memories", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "yaadgar", urdu: "یادگار", english: "memorable", gender: null, number: null, form: "related form", }, { romanUrdu: "yaadon", urdu: "یادوں", english: "memories / of memories", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/yaad.webp", riddles: { english: "Something kept inside the mind,\nOld sweet moments you can find!", romanUrdu: "Dil aur zehan mein baat bas jaye,\nPurana lamha yaad ban jaye!", urdu: "دل اور ذہن میں بات بس جائے،\nپرانا لمحہ یاد بن جائے!", }, },{id: "zabaan", word: { baseRomanUrdu: "zabaan", baseUrdu: "زبان", english: "tongue / language", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [{ romanUrdu: "zabaanein", urdu: "زبانیں", english: "languages", gender: "feminine", number: "plural", form: "plural", }, { romanUrdu: "zabaanon", urdu: "زبانوں", english: "languages", gender: "feminine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/zabaan.webp", riddles: { english: "It lives inside your mouth to taste,\nWith it your words are shaped and placed.", romanUrdu: "Munh ke andar rehti hai,\nBaat bana kar kehti hai.", urdu: "منہ کے اندر رہتی ہے،\nبات بنا کر کہتی ہے۔", }, },{id: "zaika", word: { baseRomanUrdu: "zaika", baseUrdu: "ذائقہ", english: "flavor", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "zaike", urdu: "ذائقے", english: "flavors", gender: "masculine", number: "plural", form: "plural", }, { romanUrdu: "zaikon", urdu: "ذائقوں", english: "flavors", gender: "masculine", number: "plural", form: "plural oblique", }], image: "/qr/assets/images/zaika.webp", riddles: { english: "Sweet or spicy, sour or mild,\nIt makes food fun for every child!", romanUrdu: "Meetha khatta ya tikha lage,\nKhana is se mazedar bane!", urdu: "میٹھا کھٹا یا تیکھا لگے،\nکھانا اس سے مزے دار بنے!", }, },{id: "zameen", word: { baseRomanUrdu: "zameen", baseUrdu: "زمین", english: "ground / floor", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/zameen.webp", riddles: { english: "Under your feet, wherever you go,\nI hold you up from down below.", romanUrdu: "Jahan bhi jao, pairon ke neeche,\nSab ko thaame rakhti hoon neeche.", urdu: "جہاں بھی جاؤ، پیروں کے نیچے،\nسب کو تھامے رکھتی ہوں نیچے۔", }, },{id: "zaroori", word: { baseRomanUrdu: "zaroori", baseUrdu: "ضروری", english: "necessary", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/zaroori.webp", riddles: { english: "Something important you must do,\nNot extra, but needed too!", romanUrdu: "Jo kaam bohat aham ho jaye,\nUs ke bina baat na ban paye!", urdu: "جو کام بہت اہم ہو جائے،\nاس کے بنا بات نہ بن پائے!", }, },{id: "zyada", word: { baseRomanUrdu: "zyada", baseUrdu: "زیادہ", english: "more", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/zyada.webp", riddles: { english: "Add some extra, make it grow,\nA little bit beyond what you know!", romanUrdu: "Thora aur jab saath lagao,\nMiqdar ko tum barha jao!", urdu: "تھوڑا اور جب ساتھ لگاؤ،\nمقدار کو تم بڑھا جاؤ!", }, },{id: "chooha", word: { baseRomanUrdu: "chooha", baseUrdu: "چوہا", english: "mouse", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/chooha.webp", riddles: { english: "I am small and I love eating cheese. Who am I?", romanUrdu: "Main chhota sa hoon aur mujhe cheese khana bohat pasand hai. Main kaun hoon?", urdu: "میں چھوٹا سا ہوں اور مجھے چیز کھانا بہت پسند ہے۔ میں کون ہوں؟", }, },{id: "ghari", word: { baseRomanUrdu: "ghari", baseUrdu: "گھڑی", english: "clock", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/ghari.webp", riddles: { english: "I tick and I tock, I live on the wall,\nI help you know when to run or to stall.", romanUrdu: "Main tick aur tock karti hoon, deewar pe hoon latki,\nMain batati hoon waqt, na ho jaaye der bhatki.", urdu: "میں ٹک اور ٹاک کرتی ہوں، دیوار پر ہوں لٹکی،\nمیں بتاتی ہوں وقت، نہ ہو جائے دیر بھٹکی۔", }, },{id: "naachna", word: { baseRomanUrdu: "naachna", baseUrdu: "ناچنا", english: "dance", pos: "verb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/naachna.webp", riddles: { english: "I twirl and I hop with a smile on my face,\nI move to the music and spin in my space!", romanUrdu: "Main ghoomti hoon aur uchhalti hoon, chehre pe muskaan,\nGeet bajay to chalu main, ho jaaye meri shaan!", urdu: "میں گھومتی ہوں اور اچھلتی ہوں، چہرے پہ مسکان،\nگیت بجے تو چلوں میں، ہو جائے میری شان!", }, },{id: "shaadi", word: { baseRomanUrdu: "shaadi", baseUrdu: "شادی", english: "wedding", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/shaadi.webp", riddles: { english: "Lots of colors, sweets, and song, Everyone smiles and sings along.", romanUrdu: "Rang birangi hoti hai shaam, Sab hanstay hain, bajta hai daam.", urdu: "رنگ برنگی ہوتی ہے شام،\nسب ہنستے ہیں، بجتا ہے دھام۔", }, },{id: "bulava", word: { baseRomanUrdu: "bulava", baseUrdu: "بلاوا", english: "invitation", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/bulava.webp", riddles: { english: "I come in the mail or with a smile,\nI ask you to visit and stay for a while.", romanUrdu: "Kabhi daakiya laye, kabhi koi dost,\nKeh do ‘aao’, main hoon sab se khoobsoort.", urdu: "کبھی ڈاکیہ لائے، کبھی کوئی دوست،\nکہہ دو 'آؤ'، میں ہوں سب سے خوبصورت۔", }, },{id: "bunna", word: { baseRomanUrdu: "bunna", baseUrdu: "بُننا", english: "weave", pos: "verb", }, grammar: { baseGender: null }, variants: [{ romanUrdu: "buna", urdu: "بُنا", english: "wove", gender: "masculine", number: "singular", form: "past", }, { romanUrdu: "buni", urdu: "بُنی", english: "wove", gender: "feminine", number: "singular", form: "past", }, { romanUrdu: "bunay", urdu: "بُنے", english: "wove", gender: "masculine", number: "plural", form: "past", }, { romanUrdu: "buneen", urdu: "بُنیں", english: "wove", gender: "feminine", number: "plural", form: "past", }, { romanUrdu: "buno", urdu: "بُنو", english: "weave", gender: null, number: null, form: "command", }, { romanUrdu: "bun rahi", urdu: "بُن رہی", english: "is weaving", gender: "feminine", number: "singular", form: "continuous", }], image: "/qr/assets/images/bunna.webp", riddles: { english: "Thread goes over, thread goes under,\nCloth and baskets made with wonder.", romanUrdu: "Dhaaga upar, dhaaga neeche,\nKapra banta aage peeche.", urdu: "دھاگا اوپر، دھاگا نیچے،\nکپڑا بنتا آگے پیچھے۔", }, },
{id: "khaana", word: { baseRomanUrdu: "khaana", baseUrdu: "کھانا", english: "to eat", pos: "verb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/khaana.webp", riddles: { english: "I open wide and take a bite, yummy food is pure delight!", romanUrdu: "Moo kholoon aur bite loon tight, mazedaar khaana hai delight!", urdu: "منہ کھولوں اور بائٹ لوں ٹائٹ، مزے دار کھانا ہے ڈیلائٹ!", }, },{id: "aaj", word: { baseRomanUrdu: "aaj", baseUrdu: "آج", english: "today", pos: "adverb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/aaj.webp", riddles: { english: "Not tomorrow, not yesterday, I’m the one you have today!", romanUrdu: "Kal nahi, guzra kal bhi nahi, main hoon 'aaj' — bilkul yahi!", urdu: "کل نہیں، گزرا کل بھی نہیں، میں ہوں 'آج' — بالکل یہی!", }, },{id: "khoob", word: { baseRomanUrdu: "khoob", baseUrdu: "خوب", english: "very / a lot", pos: "", }, grammar: { baseGender: null }, variants: [], image: "/qr/book/naaniterimorni-p7zbp9/images/khoob.webp", riddles: { english: "When there’s plenty, more than a few, I’m the word that sticks like glue!", romanUrdu: "Jab ho zyada, bohat sa kuch, main hoon lafz jo lagta hai touch!", urdu: "جب ہو زیادہ، بہت سا کچھ، میں ہوں لفظ جو لگتا ہے ٹچ!", }, },{id: "mota", word: { baseRomanUrdu: "mota", baseUrdu: "موٹا", english: "fat / chubby", pos: "adjective", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "motay", urdu: "موٹے", english: "fat / chubby (plural)", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/book/naaniterimorni-p7zbp9/images/motay.webp", riddles: { english: "I’m round and soft, like a teddy bear, with chubby cheeks and fluffy hair!", romanUrdu: "Gol aur naram, teddy bear jaisa, mote gaal aur mulayam baal waisa!", urdu: "گول اور نرم، ٹیڈی بیئر جیسا، موٹے گال اور ملائم بال ویسا!", }, },{id: "kutta", word: { baseRomanUrdu: "kutta", baseUrdu: "کتا", english: "dog", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/kutta.webp", riddles: { english: "I am a loyal friend who barks. Who am I?", romanUrdu: "Main wafadar aur bhonknay wala dost hoon. Main kaun hoon?", urdu: "میں وفادار اور بھونکنے والا دوست ہوں۔ میں کون ہوں؟", }, },{id: "billi", word: { baseRomanUrdu: "billi", baseUrdu: "بلی", english: "cat", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/billi.webp", riddles: { english: "I am small and say 'meow'. Who am I?", romanUrdu: "Main chhoti hoon aur meow karti hoon. Main kaun hoon?", urdu: "میں چھوٹی ہوں اور میاؤں کرتی ہوں۔ میں کون ہوں؟", }, },{id: "oont", word: { baseRomanUrdu: "oont", baseUrdu: "اونٹ", english: "camel", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/oont.webp", riddles: { english: "I have a hump on my back and live in the desert. Who am I?", romanUrdu: "Meri peeth par kohan hota hai, aur main registan mein rehta hoon. Main kaun hoon?", urdu: "میری پیٹھ پر کوہان ہوتا ہے، اور میں ریگستان میں رہتا ہوں۔ میں کون ہوں؟", }, },{id: "hans", word: { baseRomanUrdu: "hans", baseUrdu: "ہنس", english: "goose", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/hans.webp", riddles: { english: "I honk and strut beside the lake,\nMy long white neck makes hearts awake.", romanUrdu: "Taalaab ke paas honk karta hun,\nLambi gardan se sabko heran karta hun.", urdu: "تالاب کے پاس ہونک کرتا ہوں،\nلمبی گردن سے سب کو حیران کرتا ہوں۔", }, },{id: "gadha", word: { baseRomanUrdu: "gadha", baseUrdu: "گدھا", english: "donkey", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/gadha.webp", riddles: { english: "I carry loads and walk slowly. Who am I?", romanUrdu: "Main bojh uthata hoon aur ahista chalta hoon. Main kaun hoon?", urdu: "میں بوجھ اٹھاتا ہوں اور آہستہ چلتا ہوں۔ میں کون ہوں؟", }, },{id: "khargosh", word: { baseRomanUrdu: "khargosh", baseUrdu: "خرگوش", english: "rabbit", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/khargosh.webp", riddles: { english: "I am small, run fast, and thump with my feet. Who am I?", romanUrdu: "Main chhota hoon, taiz bhagta hoon, aur apne pair se zor zor se thapthapata hoon. Main kaun hoon?", urdu: "میں چھوٹا ہوں، تیز بھاگتا ہوں، اور اپنے پیر سے زور زور سے تھپتھپاتا ہوں۔ میں کون ہوں؟", }, },{id: "turkey", word: { baseRomanUrdu: "turkey", baseUrdu: "ٹرکی", english: "turkey", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/turkey.webp", riddles: { english: "I gobble and strut around the farm,\nMy tail spreads wide, I mean no harm.", romanUrdu: "Khet mein gobble gobble karta hun,\nApni dum failaata, khulkar ghoomta hun.", urdu: "کھیت میں گوبل گوبل کرتا ہوں،\nاپنی دم پھیلاتا، کھل کر گھومتا ہوں۔", }, },{id: "ghora", word: { baseRomanUrdu: "ghora", baseUrdu: "گھوڑا", english: "horse", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/ghora.webp", riddles: { english: "I can run fast, and people use me for riding. Who am I?", romanUrdu: "Main taiz daur sakta hoon aur log mujhe sawari ke liye istemal karte hain. Main kaun hoon?", urdu: "میں تیز دوڑ سکتا ہوں اور لوگ مجھے سواری کے لئے استعمال کرتے ہیں۔ میں کون ہوں؟", }, },{id: "chooza", word: { baseRomanUrdu: "chooza", baseUrdu: "چوزہ", english: "chick", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [{ romanUrdu: "choozay", urdu: "چوزے", english: "chicks", gender: "masculine", number: "plural", form: "plural", }], image: "/qr/assets/images/choozay.webp", riddles: { english: "I am small and hatch from an egg. Who am I?", romanUrdu: "Main chhota hoon aur anday se nikalta hoon. Main kaun hoon?", urdu: "میں چھوٹا ہوں اور انڈے سے نکلتا ہوں۔ میں کون ہوں؟", }, },{id: "sewr", word: { baseRomanUrdu: "sewr", baseUrdu: "سور", english: "pig", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/sewr.webp", riddles: { english: "I am round and chubby, roll in mud, and say 'oink oink.' Who am I?", romanUrdu: "Main gol matol hoon, mitti mein lotta hoon, aur oink oink karta hoon. Main kaun hoon?", urdu: "میں گول مٹول ہوں، مٹی میں لوٹتا ہوں، اور اوئنک اوئنک کرتا ہوں۔ میں کون ہوں؟", }, },{id: "murghi", word: { baseRomanUrdu: "murghi", baseUrdu: "مرغی", english: "hen", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/murghi.webp", riddles: { english: "I lay eggs and say 'bawk bawk.' Who am I?", romanUrdu: "Main anday deti hoon aur bawk bawk karti hoon. Main kaun hoon?", urdu: "میں انڈے دیتی ہوں اور باک باک کرتی ہوں۔ میں کون ہوں؟", }, },{id: "murgha", word: { baseRomanUrdu: "murgha", baseUrdu: "مرغا", english: "rooster", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/murgha.webp", riddles: { english: "I am the first to say ‘cock-a-doodle-doo’ in the morning. Who am I?", romanUrdu: "Main subha sabse pehle ‘kukroo koo’ karta hoon. Main kaun hoon?", urdu: "میں صبح سب سے پہلے ‘ککڑو کُو’ کرتا ہوں۔ میں کون ہوں؟", }, },{id: "batakh", word: { baseRomanUrdu: "batakh", baseUrdu: "بطخ", english: "duck", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/batakh.webp", riddles: { english: "I swim in water and say 'quack quack.' Who am I?", romanUrdu: "Main paani mein tairti hoon aur quack quack karti hoon. Main kaun hoon?", urdu: "میں پانی میں تیرتی ہوں اور کواک کواک کرتی ہوں۔ میں کون ہوں؟", }, },{id: "naani", word: { baseRomanUrdu: "naani", baseUrdu: "نانی", english: "grandmother (maternal)", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/book/naaniterimorni-p7zbp9/images/naani.webp", riddles: { english: "She tells old stories with love so deep,\nAnd hugs you warmly before you sleep.", romanUrdu: "Wo kahaniyan sunaye pyaar ke saath,\nSone se pehle karti hai baat.", urdu: "وہ کہانیاں سنائے پیار کے ساتھ،\nسونے سے پہلے کرتی ہے بات۔", }, },{id: "russa_rusi", word: { baseRomanUrdu: "russa rusi", baseUrdu: "روسا روسی", english: "upset", pos: "phrase", }, grammar: { baseGender: null }, variants: [], image: "/qr/book/naaniterimorni-p7zbp9/images/russa_rusi.webp", riddles: { english: "When someone won’t talk and looks away,\nTheir face says they’re not okay.", romanUrdu: "Jab koi na baat kare aur munh phere,\nTab samajh jao dil unke bhare.", urdu: "جب کوئی نہ بات کرے اور مُنہ پھیریں،\nتب سمجھ جاؤ دل ان کے بھریں۔", }, },{id: "de_de", word: { baseRomanUrdu: "de de", baseUrdu: "دے دے", english: "give me", pos: "phrase", }, grammar: { baseGender: null }, variants: [], image: "/qr/book/naaniterimorni-p7zbp9/images/dede.webp", riddles: { english: "A little request said with a plea,\nWhen you want something handed to thee.", romanUrdu: "Chhoti si guzarish, pyaari si baat,\nJab chahiye cheez kisi ki haath.", urdu: "چھوٹی سی گزارش، پیاری سی بات،\nجب چاہیے چیز کسی کے ہاتھ۔", }, },{id: "paisa", word: { baseRomanUrdu: "paisa", baseUrdu: "پیسہ", english: "money", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/book/naaniterimorni-p7zbp9/images/paisa.webp", riddles: { english: "Coins or bills that people spend,\nTo buy things from end to end.", romanUrdu: "Sikke aur not, sab log kharch karein,\nCheezein lene mein istemal karein.", urdu: "سِکے اور نوٹ، سب لوگ خرچ کریں،\nچیزیں لینے میں استعمال کریں۔", }, },{id: "kanjoosi", word: { baseRomanUrdu: "kanjoosi", baseUrdu: "کنجوسی", english: "stinginess", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/book/naaniterimorni-p7zbp9/images/kanjoosi.webp", riddles: { english: "Someone who holds coins tight in their hand,\nNever wants to share, do you understand?", romanUrdu: "Jo sikkey haath mein jor ke pakde,\nBaantne se hamesha thoda akde.", urdu: "جو سکے ہاتھ میں زور سے پکڑے،\nبانٹنے سے ہمیشہ تھوڑا اکڑے۔", }, },{id: "baaki", word: { baseRomanUrdu: "baaki", baseUrdu: "باقی", english: "remaining", pos: "", }, grammar: { baseGender: null }, variants: [], image: "/qr/book/naaniterimorni-p7zbp9/images/baaki.webp", riddles: { english: "What’s left after some is gone,\nThe pieces that still linger on.", romanUrdu: "Jo thoda hissa reh jaye baad mein,\nWohi jo hum dekhein baaki aad mein.", urdu: "جو تھوڑا حصہ رہ جائے بعد میں،\nوہی جو ہم دیکھیں باقی عاد میں۔", }, },{id: "kha_ke", word: { baseRomanUrdu: "kha ke", baseUrdu: "کھا کے", english: "after eating", pos: "phrase", }, grammar: { baseGender: null }, variants: [], image: "/qr/book/naaniterimorni-p7zbp9/images/kha_ke.webp", riddles: { english: "When a tummy is full and smiles appear,\nThis moment happens — loud and clear.", romanUrdu: "Jab pet bhara ho aur muskurahat aaye,\nYeh lamha phir dil ko bhaye.", urdu: "جب پیٹ بھرا ہو اور مسکراہٹ آئے،\nیہ لمحہ پھر دل کو بھائے۔", }, },{id: "pee_ke", word: { baseRomanUrdu: "pee ke", baseUrdu: "پی کے", english: "after drinking", pos: "phrase", }, grammar: { baseGender: null }, variants: [], image: "/qr/book/naaniterimorni-p7zbp9/images/pee_ke.webp", riddles: { english: "When thirst is gone and lips are wet,\nThis moment is what you get.", romanUrdu: "Jab piyasa na rahe bilkul bhi,\nHonthon par boondein chamkein ji.", urdu: "جب پیاسا نہ رہے بالکل بھی،\nہونٹوں پر بوندیں چمکیں جی۔", }, },{id: "chor", word: { baseRomanUrdu: "chor", baseUrdu: "چور", english: "thief", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/book/naaniterimorni-p7zbp9/images/chor.webp", riddles: { english: "Sneaky feet like a tip-toe mouse,\nQuietly creeping through the house.", romanUrdu: "Billi ke jaise qadam uthaye,\nGhar mein chupke chupke aaye.", urdu: "بلی کے جیسے قدم اٹھائے،\nگھر میں چپکے چپکے آئے۔", }, },{id: "rail", word: { baseRomanUrdu: "rail", baseUrdu: "ریل", english: "train", pos: "noun", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/book/naaniterimorni-p7zbp9/images/rail.webp", riddles: { english: "Long like a snake with seats inside,\nTakes you on a rolling ride.", romanUrdu: "Saap si lambi, andar kursiyan,\nChalti rehti, karti safariyan.", urdu: "سانپ سی لمبی، اندر کرسیاں،\nچلتی رہتی، کرتی سفریاں۔", }, },{id: "driver", word: { baseRomanUrdu: "driver", baseUrdu: "ڈرائیور", english: "driver", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/driver.webp", riddles: { english: "I sit in front and steer all day,\nI take you where you need to stay.", romanUrdu: "Aagay baith kar steering sambhalta hun,\nManzil tak pohanchata hun.", urdu: "آگے بیٹھ کر اسٹیرنگ سنبھالتا ہوں،\nمنزل تک پہنچاتا ہوں۔", }, },{id: "gol", word: { baseRomanUrdu: "gol", baseUrdu: "گول", english: "round", pos: "adjective", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/gol.webp", riddles: { english: "No corners here, I curve all the way around,\nA circle shape is what I've found.", romanUrdu: "Koi kona nahin, ghumav hi ghumav hai,\nDaira ya ball meri pehchaan hai.", urdu: "کوئی کونا نہیں، گھماؤ ہی گھماؤ ہے،\nدائرہ یا گیند میری پہچان ہے۔", }, },{id: "dikhao", word: { baseRomanUrdu: "dikhao", baseUrdu: "دکھاؤ", english: "show", pos: "verb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/dikhao.webp", riddles: { english: "Hold it up so all can see,\nShare what you have with them and me!", romanUrdu: "Utha kar dikhao, sabko batao,\nJo tumhare paas hai, sab ko dikhlao.", urdu: "اٹھا کر دکھاؤ، سب کو بتاؤ،\nجو تمہارے پاس ہے، سب کو دکھلاؤ۔", }, },{id: "pilao", word: { baseRomanUrdu: "pilao", baseUrdu: "پلاؤ", english: "serve / give to drink", pos: "verb", }, grammar: { baseGender: null }, variants: [], image: "/qr/assets/images/pilao.webp", riddles: { english: "Fill the cup and pass it near,\nQuench their thirst and bring some cheer!", romanUrdu: "Pyaala bharo aur haath badhao,\nPyaas bujhao, khushi laao.", urdu: "پیالہ بھرو اور ہاتھ بڑھاؤ،\nپیاس بجھاؤ، خوشی لاؤ۔", }, },{id: "girti", word: { baseRomanUrdu: "girti", baseUrdu: "گرتی", english: "falls", pos: "verb", }, grammar: { baseGender: "feminine" }, variants: [], image: "/qr/assets/images/girti.webp", riddles: { english: "Down she comes from up so high,\nLike the rain that falls from the sky.", romanUrdu: "Upar se neechay aa jaati hai,\nBaarish ki tarah zameen ko chooti hai.", urdu: "اوپر سے نیچے آ جاتی ہے،\nبارش کی طرح زمین کو چھوتی ہے۔", }, },{id: "rasto", word: { baseRomanUrdu: "rasto", baseUrdu: "راستوں", english: "paths", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/rasto.webp", riddles: { english: "We wind through towns and all along the lane,\nFollow us and you'll reach home again.", romanUrdu: "Hum gali aur sheher se guzarte hain,\nManzil tak pohanchane mein madad karte hain.", urdu: "ہم گلی اور شہر سے گزرتے ہیں،\nمنزل تک پہنچانے میں مدد کرتے ہیں۔", }, },{id: "makora", word: { baseRomanUrdu: "makora", baseUrdu: "مکوڑا", english: "insect", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/makora.webp", riddles: { english: "Tiny legs and crawling slow,\nUp the tree is how I go!", romanUrdu: "Chhoti chhoti tanghain, rengta hun dheeray,\nUpar charhna meri adaat hai meeray.", urdu: "چھوٹی چھوٹی ٹانگیں، رینگتا ہوں دھیرے،\nاوپر چڑھنا میری عادت ہے میرے۔", }, },{id: "darakht", word: { baseRomanUrdu: "darakht", baseUrdu: "درخت", english: "tree", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/darakht.webp", riddles: { english: "My roots go deep, my branches wide,\nBirds and insects like to hide inside.", romanUrdu: "Meray jur gehra, shaakhein door door,\nParindey aur makore meri chhav mein rehte hain zaroor.", urdu: "میری جڑ گہری، شاخیں دور دور،\nپرندے اور مکوڑے میری چھاؤ میں رہتے ہیں ضرور۔", }, },{id: "beh_gaya", word: { baseRomanUrdu: "beh gaya", baseUrdu: "بہہ گیا", english: "washed away", pos: "phrase", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/beh_gaya.png", riddles: { english: "The water swept me far and wide,\nI flowed away and couldn't hide.", romanUrdu: "Paani ne mujhe door le liya,\nBeh kar main zameen se dur gaya.", urdu: "پانی نے مجھے دور لے لیا،\nبہہ کر میں زمین سے دور گیا۔", }, },{id: "sooraj", word: { baseRomanUrdu: "sooraj", baseUrdu: "سورج", english: "sun", pos: "noun", }, grammar: { baseGender: "masculine" }, variants: [], image: "/qr/assets/images/sooraj.webp", riddles: { english: "I rise each morning, warm and bright,\nI fill the world with golden light.", romanUrdu: "Subah uthta hun, roshni bikherta hun,\nSari duniya ko garam aur ujla karta hun.", urdu: "صبح اٹھتا ہوں، روشنی بکھیرتا ہوں،\nساری دنیا کو گرم اور اجلا کرتا ہوں۔", }, }];export function buildVariantLookup(vocabList) {  const lookup = {};  const normalizeKey = (key) => {    if (!key) return "";    return key.trim().toLowerCase();  };  const addEntry = ({    key,    parentId,    matchType,    romanUrdu,    urdu,    baseRomanUrdu,    baseUrdu,    english,    pos,    gender,    number,    form,    image,  }) => {    if (!key) return;    const finalKey = normalizeKey(key);    lookup[finalKey] = {      parentId,      matchType,      romanUrdu,      urdu,      baseRomanUrdu,      baseUrdu,      english,      pos,      gender,      number,      form,      image,    };  };  vocabList.forEach((entry) => {    addEntry({      key: entry.word.baseRomanUrdu,      parentId: entry.id,      matchType: "base",      romanUrdu: entry.word.baseRomanUrdu,      urdu: entry.word.baseUrdu,      baseRomanUrdu: entry.word.baseRomanUrdu,      baseUrdu: entry.word.baseUrdu,      english: entry.word.english,      pos: entry.word.pos,      gender: entry.grammar.baseGender,      number: null,      form: "base",      image: entry.image,    });    addEntry({      key: entry.word.baseUrdu,      parentId: entry.id,      matchType: "base",      romanUrdu: entry.word.baseRomanUrdu,      urdu: entry.word.baseUrdu,      baseRomanUrdu: entry.word.baseRomanUrdu,      baseUrdu: entry.word.baseUrdu,      english: entry.word.english,      pos: entry.word.pos,      gender: entry.grammar.baseGender,      number: null,      form: "base",      image: entry.image,    });    const variants = Array.isArray(entry.variants) ? entry.variants : [];    variants.forEach((variant) => {      addEntry({        key: variant.romanUrdu,        parentId: entry.id,        matchType: "variant",        romanUrdu: variant.romanUrdu,        urdu: variant.urdu,        baseRomanUrdu: entry.word.baseRomanUrdu,        baseUrdu: entry.word.baseUrdu,        english: entry.word.english,        pos: entry.word.pos,        gender: variant.gender,        number: variant.number,        form: variant.form,        image: entry.image,      });      addEntry({        key: variant.urdu,        parentId: entry.id,        matchType: "variant",        romanUrdu: variant.romanUrdu,        urdu: variant.urdu,        baseRomanUrdu: entry.word.baseRomanUrdu,        baseUrdu: entry.word.baseUrdu,        english: entry.word.english,        pos: entry.word.pos,        gender: variant.gender,        number: variant.number,        form: variant.form,        image: entry.image,      });    });  });  return lookup;}export const variantLookup = buildVariantLookup(vocab);